async function autoApproveOT(
  AttendanceTransID,
  UserMasterID,
  OverTimeDate,
  OverTimeIn,
  OverTimeOut,
  OverTimeInDateTime,
  OverTimeOutDateTime,
  OverTimeHourAndMin,
  AttendancePolicyID,
  CompanyMasterID
) {
  await deleteOvertimeForAttendance(UserMasterID, OverTimeDate);
  await overTimeCalculation.create({
    AttendanceTransID: AttendanceTransID,
    UserMasterID: UserMasterID,
    OverTimeDate: OverTimeDate,
    OverTimeIn: OverTimeIn,
    OverTimeOut: OverTimeOut,
    UpdateTimeIn: OverTimeIn,
    UpdateTimeOut: OverTimeOut,
    UpdateOverTimeHourAndMin: Math.round(Number(OverTimeHourAndMin)),
    OverTimeInDateTime: OverTimeInDateTime,
    OverTimeOutDateTime: OverTimeOutDateTime,
    UpdateTimeInDateTime: OverTimeInDateTime,
    UpdateTimeOutDateTime: OverTimeOutDateTime,
    OverTimeHourAndMin: Math.round(Number(OverTimeHourAndMin)),
    AttendancePolicyID: AttendancePolicyID,
    AuthorizationRequired: 3,
    CompanyMasterID: CompanyMasterID,
    createBy: UserMasterID,
    autoApprove: true,
  });
}

