async function add_ExtraDays_Manual(
  userMasterID,
  date,
  extraDaysValue,
  createBy,
  createByIp,
  transaction
) {
  try {
    await delete_ExtraDay_Attendance_Manual(userMasterID, date, transaction);
    const promiseArray = [];
    const authorizationdetails = await FormAuthorizationDetails.findOne(
      {
        where: {
          AuthorizationMasterID: authorizationMasterTypes.compensatoryOff, // Compensatory Off
          userMasterID,
          status: 1,
        },
        include: [
          {
            model: AuthorizationCriteriaMaster,
            attributes: ['AuthorizationCriteria'],
          },
        ],
      },
      { transaction }
    );

    const authorizationStatus =
      authorizationdetails && authorizationdetails.AuthorizationCriteriaMaster
        ? authorizationdetails.AuthorizationCriteriaMaster
            .AuthorizationCriteria == 'Sequeance No'
          ? 2
          : 1
        : 0;

    const requestData = await ExtraDays.create(
      {
        userMasterID: userMasterID,
        date: date,
        days: extraDaysValue,
        authorizationStatus,
        createBy,
        createByIp,
      },
      { hooks: false, transaction }
    );

    if (authorizationStatus != 0) {
      // user Details
      const userDetails = await UserMaster.findOne({
        raw: true,
        where: {
          userMasterID,
        },
      });

      if (!userDetails) throw new Error('User not found!');

      // For Sequence No
      if (authorizationStatus == 2) {
        const authorizationData = await ExtraDaysAuthorization.create(
          {
            extraDaysID: requestData.extraDaysID,
            userMasterID: authorizationdetails.AuthorizedByUserMasterId[0],
            authstatus: 2,
            createBy,
            createByIp,
          },
          { hooks: false, transaction }
        );

        // Create UserInbox
        promiseArray.push(
          UserInbox.create(
            {
              activityTable: ExtraDaysAuthorization.getTableName(),
              activityTablePK:
                authorizationData.toJSON().extraDaysAuthorizationID,
              message: `${
                userDetails.displayName
              } has requested a Extra days for ${moment(date).format(
                'DD/MM/YYYY'
              )}.`,
              assignedTo: authorizationdetails.AuthorizedByUserMasterId[0],
              assignedBy: userMasterID,
              createBy,
              createByIp,
            },
            { transaction }
          )
        );

        const notification = {
          title: 'Extra Days',
          body: userDetails.displayName + ' requested for a Extra Days.',
        };
        const data = {
          screen: 'extradaysauth',
          isScheduled: 'true',
          scheduledTime: new Date().toISOString(),
        };

        // send Notification
        promiseArray.push(
          sendNotification(authorizationData.userMasterID, notification, data)
        );
      } else {
        // For Any
        for (
          let j = 0;
          j < authorizationdetails.AuthorizedByUserMasterId.length;
          j++
        ) {
          const authorizationData = await ExtraDaysAuthorization.create(
            {
              extraDaysID: requestData.extraDaysID,
              userMasterID: authorizationdetails.AuthorizedByUserMasterId[j],
              authstatus: 2,
              createBy,
              createByIp,
            },
            { hooks: false, transaction }
          );

          // Create UserInbox
          promiseArray.push(
            UserInbox.create(
              {
                activityTable: ExtraDaysAuthorization.getTableName(),
                activityTablePK:
                  authorizationData.toJSON().extraDaysAuthorizationID,
                message: `${
                  userDetails.displayName
                } has requested a Extra Days for ${moment(date).format(
                  'DD/MM/YYYY'
                )}.`,
                assignedTo: authorizationdetails.AuthorizedByUserMasterId[j],
                assignedBy: userMasterID,
                createBy,
                createByIp,
              },
              { transaction }
            )
          );

          const notification = {
            title: 'Extra Day',
            body: userDetails.displayName + ' requested for a Extra Days.',
          };
          const data = {
            screen: 'extradaysauth',
            isScheduled: 'true',
            scheduledTime: new Date().toISOString(),
          };
          // send Notification
          promiseArray.push(
            sendNotification(authorizationData.userMasterID, notification, data)
          );
        }
      }

      await Promise.all(promiseArray);
    }
  } catch (error) {
    throw new Error('Error in Extra Days Auth: ' + error.message);
  }
}

async function addCoffMobile(
  userMasterID,
  date,
  companyMasterId,
  attendancePolicy,
  total_In_Hrs
) {
  try {
    if (attendancePolicy.coffhalfday && attendancePolicy.cofffullday) {
      let coffValue = 0;
      if (
        total_In_Hrs >= Number(attendancePolicy.coffhalfday) &&
        total_In_Hrs < Number(attendancePolicy.cofffullday)
      ) {
        coffValue = 0.5;
      } else if (
        total_In_Hrs >= Number(attendancePolicy.cofffullday) &&
        (!attendancePolicy.coffOneAndHalfDay ||
          total_In_Hrs < Number(attendancePolicy.coffOneAndHalfDay))
      ) {
        coffValue = 1;
      } else if (
        attendancePolicy.coffOneAndHalfDay &&
        total_In_Hrs >= Number(attendancePolicy.coffOneAndHalfDay) &&
        (!attendancePolicy.coffTwoFullDay ||
          total_In_Hrs < Number(attendancePolicy.coffTwoFullDay))
      ) {
        coffValue = 1.5;
      } else if (
        attendancePolicy.coffTwoFullDay &&
        total_In_Hrs >= Number(attendancePolicy.coffTwoFullDay)
      ) {
        coffValue = 2;
      }
      let trans = await HrLeaveTypes.findOne({
        where: {
          LeaveID: 6,
          companyMasterID: companyMasterId,
        },
      });

      if (trans) {
        let LeaveTranId = trans.LeaveTranId;

        let YearMM = date.substring(0, 7);
        YearMM = YearMM.replace('-', '');

        let coff = await coffMaster.findOne({
          raw: true,
          where: {
            userMasterID: userMasterID,
            LeaveCreatedDate: date,
          },
        });

        if (coff) {
          if (coff.LeaveBalTranId) {
            await HrLeaveBalance.destroy({
              where: {
                LeaveBalTranId: coff.LeaveBalTranId,
              },
            });
          }

          if (coff.authorizationStatus != 0) {
            const authData = await CompensatoryOffAuthorization.findAll({
              where: {
                coffMasterID: coff.coffMasterID,
              },
            });

            const allIds = authData.map(
              (e) => e.CompensatoryOffAuthorizationID
            );

            await UserInbox.destroy({
              where: {
                activityTable: CompensatoryOffAuthorization.getTableName(),
                activityTablePK: allIds,
              },
            });

            await CompensatoryOffAuthorization.destroy({
              where: {
                coffMasterID: coff.coffMasterID,
              },
            });

            await coffMaster.destroy({
              where: {
                userMasterID: userMasterID,
                LeaveCreatedDate: date,
              },
            });
          }
        }
        if (coffValue > 0) {
          await coffAuthorization(
            userMasterID,
            date,
            coffValue,
            YearMM,
            LeaveTranId,
            userMasterID,
            ''
          );
        }
      }
    }
  } catch (error) {
    throw new Error('Error in add Coff: ' + error.message);
  }
}

