async function monthStartDateBetween(startDate, endDate) {
  var start = startDate.split('-');
  var end = endDate.split('-');
  var startYear = parseInt(start[0]);
  var endYear = parseInt(end[0]);
  var dates = [];

  for (var i = startYear; i <= endYear; i++) {
    var endMonth = i != endYear ? 11 : parseInt(end[1]) - 1;
    var startMon = i === startYear ? parseInt(start[1]) - 1 : 0;
    for (var j = startMon; j <= endMonth; j = j > 12 ? j % 12 || 11 : j + 1) {
      var month = j + 1;
      var displayMonth = month < 10 ? '0' + month : month;
      dates.push([i, displayMonth, '01'].join('-'));
    }
  }
  return dates;
}

async function getAutomticShiftAssigned(userid, date) {
  let day = date.toLocaleString('en-us', {
    weekday: 'long',
  });

  //department
  let assigndepartment = await employeeDepartment(userid, date);
  if (assigndepartment) {
    assigndepartment = assigndepartment.departmentID;
  } else {
    assigndepartment = null;
  }

  //Designation
  let assigndesignation = await employeeDesignation(userid, date);
  if (assigndesignation) {
    assigndesignation = assigndesignation.designationID;
  } else {
    assigndesignation = null;
  }

  //Branch
  let branch = await employeeBranch(userid, date);
  if (branch) {
    branch = branch.branchID;
  } else {
    branch = null;
  }

  //user Details
  let user_Details = await userDetails(userid);

  let get_branchs = [];
  if (branch && assigndepartment && assigndesignation) {
    get_branchs = await shiftTime.findAll({
      raw: true,
      where: {
        day: day,
        '$shift.companyMasterID$': user_Details.companyMasterId,
        '$shift.status$': 1,
        '$shift.branchID$': branch,
        [Sequelize.Op.or]: [
          {
            [Sequelize.Op.and]: [
              { '$shift.table$': 'designations' },
              { '$shift.referenceId$': assigndesignation },
            ],
          },
          {
            [Sequelize.Op.and]: [
              { '$shift.table$': 'departments' },
              { '$shift.referenceId$': assigndepartment },
            ],
          },
        ],
      },
      include: [
        {
          model: shiftModel,
          as: 'shift',
        },
      ],
    });
  } else if (branch && assigndepartment) {
    get_branchs = await shiftTime.findAll({
      raw: true,
      where: {
        day: day,
        '$shift.companyMasterID$': user_Details.companyMasterId,
        '$shift.status$': 1,
        '$shift.branchID$': branch,
        '$shift.table$': 'departments',
        '$shift.referenceId$': assigndepartment,
      },
      include: [
        {
          model: shiftModel,
          as: 'shift',
        },
      ],
    });
  } else if (branch && assigndesignation) {
    get_branchs = await shiftTime.findAll({
      raw: true,
      where: {
        day: day,
        '$shift.companyMasterID$': user_Details.companyMasterId,
        '$shift.status$': 1,
        '$shift.branchID$': branch,
        '$shift.table$': 'designations',
        '$shift.referenceId$': assigndesignation,
      },
      include: [
        {
          model: shiftModel,
          as: 'shift',
        },
      ],
    });
  }

  if (get_branchs.length == 0) {
    get_branchs = await shiftTime.findAll({
      raw: true,
      where: {
        day: day,
        '$shift.companyMasterID$': user_Details.companyMasterId,
        '$shift.status$': 1,
        '$shift.branchID$': {
          [Sequelize.Op.eq]: null,
        },

        [Sequelize.Op.or]: [
          {
            '$shift.table$': {
              [Sequelize.Op.eq]: null,
            },
          },
          {
            '$shift.table$': '',
          },
        ],

        [Sequelize.Op.or]: [
          {
            '$shift.referenceId$': {
              [Sequelize.Op.eq]: null,
            },
          },
          {
            '$shift.referenceId$': 0,
          },
        ],
      },
      include: [
        {
          model: shiftModel,
          as: 'shift',
        },
      ],
    });
  }

  if (get_branchs.length > 0) {
    for (var i = 0; i < get_branchs.length; i++) {
      let date1 = formatAMPM(date);
      var startTime = moment(date1, 'HH:mm a');
      var endTime = moment(get_branchs[i].statTime, 'HH:mm: a');
      var duration = moment.duration(startTime.diff(endTime));
      var hours = parseInt(duration.asHours());
      hours = hours * 60;
      var minutes = Math.abs((parseInt(duration.asMinutes()) % 60) + hours);
      get_branchs[i].min = minutes;
    }
    get_branchs.sort(function (a, b) {
      return a.min - b.min;
    });

    return get_branchs[0];
  } else {
    return null;
  }
}

