async function calculateEarlyby(
  AttendanceDate,
  ShiftIntime,
  ShiftOuttime,
  punchOuTime
) {
  if (
    new Date(AttendanceDate + ' ' + ShiftIntime) <
    new Date(AttendanceDate + ' ' + ShiftOuttime)
  ) {
    //day Shift
    const AttendanceOutTime = new Date(AttendanceDate + ' ' + ShiftOuttime);
    if (new Date(AttendanceOutTime) > new Date(punchOuTime)) {
      const time2 = new Date(AttendanceOutTime);
      const time1 = new Date(punchOuTime);

      // Calculate the time difference in milliseconds
      const timeDifference = time2 - time1;

      // Convert the time difference from milliseconds to minutes
      const differenceInMinutes = Math.floor(timeDifference / (1000 * 60));

      return differenceInMinutes;
    } else {
      return null;
    }
  } else {
    //night shift
    AttendanceDate = new Date(AttendanceDate);
    AttendanceDate = AttendanceDate.setDate(AttendanceDate.getDate() + 1);
    AttendanceDate = new Date(AttendanceDate).toISOString().slice(0, 10);

    const AttendanceOutTime = new Date(AttendanceDate + ' ' + ShiftOuttime);
    if (new Date(AttendanceOutTime) > new Date(punchOuTime)) {
      const time2 = new Date(AttendanceOutTime);
      const time1 = new Date(punchOuTime);

      // Calculate the time difference in milliseconds
      const timeDifference = time2 - time1;

      // Convert the time difference from milliseconds to minutes
      const differenceInMinutes = Math.floor(timeDifference / (1000 * 60));

      return differenceInMinutes;
    } else {
      return null;
    }
  }
}

async function calculateLateby(AttendanceDate, ShiftIntime, punchInime) {
  const AttendanceInTime = new Date(AttendanceDate + ' ' + ShiftIntime);

  if (new Date(AttendanceInTime) < new Date(punchInime)) {
    const time1 = new Date(AttendanceInTime);
    const time2 = new Date(punchInime);

    // Calculate the time difference in milliseconds
    const timeDifference = time2 - time1;

    // Convert the time difference from milliseconds to minutes
    const differenceInMinutes = Math.floor(timeDifference / (1000 * 60));

    return differenceInMinutes;
  } else {
    return null;
  }
}

