async function sendNotification(id, notification, body) {
  let get_user = await UserMaster.findOne({
    raw: true,
    where: {
      userMasterID: id,
      status: 1,
    },
  });
  if (get_user) {
    if (get_user.firebaseToken != null && get_user.firebaseToken != '') {
      const firebase_token = get_user.firebaseToken;

      // Common message structure
      const message_notification = {
        token: firebase_token, // Set the registration token here
        notification: notification,
        data: body, // Custom data payload
      };

      // Conditionally add platform-specific options
      if (get_user.deviceType && get_user.deviceType.toLowerCase() === 'ios') {
        // iOS-specific options
        message_notification.apns = {
          payload: {
            aps: {
              alert: {
                title: notification.title,
                body: notification.body,
              },
              sound: 'default', // Enable sound for iOS notifications
              badge: 1, // Badge count for iOS
            },
          },
          headers: {
            'apns-priority': '10', // High priority for iOS
            'apns-expiration': (
              Math.floor(Date.now() / 1000) +
              60 * 60 * 24
            ).toString(), // Expiration for 24 hours as a string
          },
        };
      } else {
        // Android-specific options
        message_notification.android = {
          priority: 'high', // High priority for Android
          ttl: 60 * 60 * 24 * 1000, // 24 hours in milliseconds for TTL
        };
      }

      // Send notification through the appropriate admin (iosFirebaseAdmin or androidFirebaseAdmin)
      const Notification_ =
        get_user.deviceType && get_user.deviceType.toLowerCase() === 'ios'
          ? iosFirebaseAdmin
          : androidFirebaseAdmin;

      Notification_.messaging()
        .send(message_notification)
        .then((response) => {})
        .catch((error) => {
          console.log('Error sending notification:', error);
        });
    }
  }
}

async function precedence(opr) {
  switch (opr) {
    case '+':
    case '-':
      return 1;
    case '*':
    case '/':
      return 2;
    default:
      return -1;
  }
}

async function isOperator(ch) {
  if (ch == '+' || ch == '-' || ch == '*' || ch == '/') {
    return true;
  } else {
    return false;
  }
}

async function infixtopostfix(formula, grade_salary_structure_data) {
  var i,
    str = '';
  var stack = [];
  var postfix = '';
  var top = -1;
  // formula="((basic+100)/(hra*100))/hra";

  for (i = 0; i < formula.length; i++) {
    ch = formula.charAt(i);
    str = '';
    if (
      ch == '(' ||
      ch == ')' ||
      ch == '+' ||
      ch == '-' ||
      ch == '*' ||
      ch == '/'
    ) {
      str = ch;
      if (str == '(') {
        top++;
        stack.push(str);
      } else if (str == ')') {
        while (top > -1 && stack[top] != '(') {
          postfix = postfix + stack[top] + ',';
          stack.pop();
          top--;
        }
        stack.pop();
        top--;
      } else {
        var x = await precedence(stack[top]);

        var y = await precedence(str);

        while (top > -1 && x >= y) {
          postfix = postfix + stack[top] + ',';
          top--;
          stack.pop();
          x = await precedence(stack[top]);

          y = await precedence(str);
        }
        top++;
        stack.push(str);
      }
    } else {
      for (j = i; j < formula.length; j++, i++) {
        ch = formula.charAt(j);
        if (
          ch == '(' ||
          ch == ')' ||
          ch == '+' ||
          ch == '-' ||
          ch == '*' ||
          ch == '/'
        ) {
          i--;
          break;
        } else {
          str = str + ch;
        }
      }
      postfix = postfix + str + ',';
    }
  }

  while (top > -1) {
    postfix = postfix + stack[top] + ',';
    stack.pop();
    top--;
  }

  var finalvalue = formulaCalculation(postfix, grade_salary_structure_data);
  return finalvalue;
}

async function isNumeric(str) {
  if (typeof str != 'string') return false; // we only process strings!
  return (
    !isNaN(str) && // use type coercion to parse the _entirety_ of the string (`parseFloat` alone does not do this)...
    !isNaN(parseFloat(str))
  ); // ...and ensure strings of whitespace fail
}

