function formulaCalculation(postfix, grade_salary_structure_data) {
  let stack = [];
  let equation = postfix.split(',');

  for (let i = 0; i < equation.length; i++) {
    const token = equation[i].trim();

    if (['+', '-', '*', '/'].includes(token)) {
      const op2 = stack.pop();
      const op1 = stack.pop();

      let op1value = resolveValue(op1, grade_salary_structure_data);
      let op2value = resolveValue(op2, grade_salary_structure_data);

      let result = 0;
      if (token === '+') result = op1value + op2value;
      else if (token === '-') result = op1value - op2value;
      else if (token === '*') result = op1value * op2value;
      else if (token === '/') result = op1value / op2value;

      stack.push(result);
    } else {
      stack.push(token);
    }
  }

  // Final result might be a string (if no operator was present), so resolve it
  return resolveValue(stack[0], grade_salary_structure_data);
}

function resolveValue(token, data) {
  const match = data.find((d) => d.payheadName === token);
  if (match) return parseFloat(match.finalvalue);
  if (isNumeric(token)) return parseFloat(token);
  return 0;
}

// --- calculation Grade structure data
async function gradeStructureCalculation(
  gradeStructureData = [],
  ctc,
  AmountIn,
  yearMonth,
  calculatedGross = 0,
  calculationOf,
  stateid,
  corporationId,
  gender,
  payheadMasterId,
  payheadAmount,
  ptSlabData = []
) {
  let aTotal = 0,
    extra_aTotal = 0,
    bTotal = 0,
    cTotal = 0;

  for (let n = 0; n < gradeStructureData.length; n++) {
    let value = 0;
    let yearly_value = 0;

    // if CTC

    if (AmountIn == '0' && gradeStructureData[n].payheadMasterId == 1) {
      gradeStructureData[n].finalvalue = Number(ctc);
      continue;
    }

    // Gross

    if (AmountIn == '1' && gradeStructureData[n].payheadMasterId == 50) {
      gradeStructureData[n].finalvalue = +calculatedGross || Number(ctc);
      continue;
    }

    // set if payheadmasterid and amount is available
    if (
      payheadMasterId &&
      payheadMasterId == gradeStructureData[n].payheadMasterId
    ) {
      gradeStructureData[n].fieldFixAmount = Number(payheadAmount);
    }

    // continue if other calculation

    if (
      calculationOf == 'other' &&
      gradeStructureData[n].salaryFieldSrNo == 'A' &&
      gradeStructureData[n].considerIn != 'net'
    )
      continue;

    // PT calculation

    if (gradeStructureData[n].payheadMasterId == 15) {
      const month = String(yearMonth).slice(4, 6);
      const GrossAmountForPT = +calculatedGross || 0;
      const isCorpNull = corporationId === null || corporationId === undefined;
      let getPTData = [];

      if (ptSlabData.length) {
        const filtered = ptSlabData.filter(
          (e) =>
            e.corporationId == corporationId &&
            e.applicableFromYYYYMM <= yearMonth
        );

        const maxApplicable = Math.max(
          ...filtered.map((e) => e.applicableFromYYYYMM)
        );

        getPTData = filtered.filter(
          (e) => +e.applicableFromYYYYMM == +maxApplicable
        );
      } else {
        getPTData = await ProfessionalTaxSlabMaster.findAll({
          where: {
            stateMasterID: +stateid,
            status: 1,
            applicableFromYYYYMM: {
              [Sequelize.Op.eq]: Sequelize.literal(`(
        SELECT MAX("applicableFromYYYYMM")
        FROM "professionalTaxSlabMasters"
        WHERE "applicableFromYYYYMM" <= '${+yearMonth}'
          AND "stateMasterID" = ${+stateid}
          AND "status" = 1
          AND ${
            isCorpNull
              ? `"corporationId" IS NULL`
              : `"corporationId" = ${corporationId}`
          }
      )`),
            },
            corporationId,
          },
        });
      }
      const PTCalculation = getPTData[0]?.ptCalculation || null;

      // if PT Calculation is Half yearly

      if (PTCalculation == PTCalculationEnum.HALFYEARLY) {
        const gross = GrossAmountForPT * 6;

        const ptData = getPTData.filter(
          (e) => +e.fromAmount <= +gross && +e.toAmount >= +gross
        );

        let PTAmount = 0;

        if (ptData.length) {
          if (gender == 'female') {
            PTAmount = Math.max(ptData[0].femaleTax, ptData[1]?.femaleTax || 0);
          } else {
            PTAmount = Math.max(ptData[0].maleTax, ptData[1]?.maleTax || 0);
          }
        }

        value = Math.round(+PTAmount / 6);
      } else {
        const ptData = getPTData.find(
          (e) =>
            +e.fromAmount <= +GrossAmountForPT &&
            +e.toAmount >= +GrossAmountForPT &&
            e.month == month
        );

        if (ptData) {
          if (gender == 'female') {
            value = ptData.femaleTax;
          } else {
            value = ptData.maleTax;
          }
        }
      }
    }

    // Set extra fields to zero
    else if (
      [9, 16, 17, 24, 34, 43, 78, 83, 96, 97, 99, 67, 101].includes(
        gradeStructureData[n].payheadMasterId
      )
    ) {
      value = 0;
    } else {
      let tempValue = 0,
        tempValue1 = 0;

      // if formula
      if (gradeStructureData[n].formula) {
        tempValue = Number(
          await infixtopostfix(
            gradeStructureData[n].formula,
            gradeStructureData
          )
        );
      } else {
        tempValue = +gradeStructureData[n].fieldFixAmount;
      }

      // For Formula1

      if (
        gradeStructureData[n].formula1 ||
        gradeStructureData[n].fieldFixAmount1
      ) {
        if (gradeStructureData[n].formula1) {
          tempValue1 = Number(
            await infixtopostfix(
              gradeStructureData[n].formula1,
              gradeStructureData
            )
          );
        } else {
          tempValue1 = Number(gradeStructureData[n].fieldFixAmount1);
        }
      }

      // set final value according to formulaPreference
      value =
        gradeStructureData[n].formulaPreference == FormulaPreferenceEnum.HIGHER
          ? Math.max(tempValue, tempValue1)
          : gradeStructureData[n].formulaPreference ==
              FormulaPreferenceEnum.LOWER
            ? Math.min(tempValue, tempValue1)
            : tempValue;

      // if fixamount then get from hrsalaymaster data
      if (
        gradeStructureData[n].EmployeeSalaryAmount &&
        +gradeStructureData[n].fieldFixAmount &&
        !gradeStructureData[n].fieldFixAmount1 &&
        !gradeStructureData[n].formula1 &&
        !gradeStructureData[n].formula
      ) {
        value = gradeStructureData[n].EmployeeSalaryAmount;
      }
    }

    let length = 12,
      salaryfieldroundno = 0;

    if (
      gradeStructureData[n].salaryFieldWhenMonth &&
      gradeStructureData[n].salaryFieldWhenMonth?.[0] != 0
    ) {
      length = gradeStructureData[n].salaryFieldWhenMonth.length;
      // yearly_value = Number(value) * Number(length);
    }

    if (gradeStructureData[n].salaryFieldRound == 'Y') {
      gradeStructureData[n].actualvalue = Number(value.toFixed(3));
      gradeStructureData[n].finalvalue =
        gradeStructureData[n].roundOffType == 0
          ? Math.ceil(value.toFixed(2))
          : Math.round(value);
      gradeStructureData[n].yearly_finalvalue = Math.round(yearly_value);
    } else {
      salaryfieldroundno = !gradeStructureData[n].salaryFieldRoundNo
        ? 0
        : +gradeStructureData[n].salaryFieldRoundNo;

      gradeStructureData[n].actualvalue = Number(value.toFixed(3));
      gradeStructureData[n].finalvalue = Number(
        value.toFixed(salaryfieldroundno)
      );
      gradeStructureData[n].yearly_finalvalue = Number(
        yearly_value.toFixed(salaryfieldroundno)
      );
    }

    if (gradeStructureData[n].salaryfieldmaxrange) {
      if (Number(value) > Number(gradeStructureData[n].salaryfieldmaxrange))
        gradeStructureData[n].finalvalue =
          gradeStructureData[n].salaryfieldmaxrange;
    }

    gradeStructureData[n].yearly_finalvalue = salaryfieldroundno
      ? (gradeStructureData[n].finalvalue * length).toFixed(salaryfieldroundno)
      : Math.round(gradeStructureData[n].finalvalue * length);

    if (![1, 50, 92].includes(gradeStructureData[n].payheadMasterId)) {
      if (
        gradeStructureData[n].salaryFieldSrNo == 'A' &&
        gradeStructureData[n].considerIn != 'net'
      )
        aTotal += gradeStructureData[n].finalvalue
          ? +gradeStructureData[n].finalvalue
          : 0;
      if (
        gradeStructureData[n].salaryFieldSrNo == 'A' &&
        gradeStructureData[n].considerIn == 'net'
      )
        extra_aTotal += gradeStructureData[n].finalvalue
          ? +gradeStructureData[n].finalvalue
          : 0;
      if (gradeStructureData[n].salaryFieldSrNo == 'B')
        bTotal += gradeStructureData[n].finalvalue
          ? +gradeStructureData[n].finalvalue
          : 0;
      if (gradeStructureData[n].salaryFieldSrNo == 'C')
        cTotal += gradeStructureData[n].finalvalue
          ? +gradeStructureData[n].finalvalue
          : 0;
    }
  }

  return { gradeStructureData, aTotal, extra_aTotal, bTotal, cTotal };
}

async function assignSalaryStructure(
  grade_salary_structure_data_temp = [],
  ctc,
  stateid,
  AmountIn,
  yearMonth,
  gender,
  corporationId,
  companyId,
  skillCategory,
  payheadMasterId = null,
  payheadAmount = 0,
  hasMinimumWages = false,
  ptSlabData = [],
  minWagesMasterData
) {
  let aTotal = 0,
    bTotal = 0,
    cTotal = 0,
    extra_aTotal = 0,
    minWagesMasterId = null;

  const NET_CTC_GROSS = [...grade_salary_structure_data_temp].filter((e) =>
    [1, 50, 92].includes(e.payheadMasterId)
  );

  const EPF_Data = [...grade_salary_structure_data_temp].find(
    (e) => e.payheadMasterId == 5
  );

  const grade_salary_structure_data = [
    ...grade_salary_structure_data_temp,
  ].filter((e) => ![1, 50, 92, 5].includes(e.payheadMasterId));

  const minWages = [];

  if (hasMinimumWages && companyId && stateid && yearMonth) {
    let minWagesData = null;
    if (minWagesMasterData) {
      minWagesData = minWagesMasterData;
    } else {
      minWagesData = await MinWagesMaster.findOne({
        where: {
          companyMasterId: companyId,
          stateMasterId: stateid,
          applicableYYYYMM: {
            [Sequelize.Op.lte]: +yearMonth,
          },
        },
        order: [['applicableYYYYMM', 'DESC']],
      });
    }

    const amount = minWagesData
      ? skillCategory == SkillCategoryType.SKILLED
        ? minWagesData?.skilled
        : skillCategory == SkillCategoryType.SEMISKILLED
          ? minWagesData?.semiSkilled
          : skillCategory == SkillCategoryType.UNSKILLED
            ? minWagesData?.unSkilled
            : 0
      : 0;
    minWagesMasterId = minWagesData?.id || null;

    minWages.push({
      payheadName: 'Minimum Wages',
      fieldFixAmount: amount,
    });
  }

  // filter Salary field A Data

  const A_Data = grade_salary_structure_data.filter(
    (e) => e.salaryFieldSrNo == 'A' && e.considerIn != 'net'
  );

  const with_A_Data = [...NET_CTC_GROSS, ...minWages, ...A_Data];

  // calculate only A part
  const calculatedData = await gradeStructureCalculation(
    with_A_Data,
    ctc,
    AmountIn,
    yearMonth,
    0,
    'A',
    stateid,
    corporationId,
    gender,
    payheadMasterId,
    payheadAmount,
    ptSlabData
  );

  // final calculated gross
  const calculatedGross = calculatedData.aTotal;

  //final A calculation
  const calculated_A = calculatedData.gradeStructureData.filter(
    (e) => ![1, 50, 92].includes(e.payheadMasterId)
  );

  const WithOut_A_Data = grade_salary_structure_data.filter(
    (e) => e.salaryFieldSrNo != 'A' || e.considerIn == 'net'
  );

  // calculate with out A Part part
  const calculate_Without_A = await gradeStructureCalculation(
    [...NET_CTC_GROSS, ...calculated_A, ...minWages, ...WithOut_A_Data],
    ctc,
    AmountIn,
    yearMonth,
    calculatedGross,
    'other',
    stateid,
    corporationId,
    gender,
    payheadMasterId,
    payheadAmount,
    ptSlabData
  );
  // final calulated Data
  const finalStructureData = calculate_Without_A.gradeStructureData.filter(
    (e) =>
      ![1, 50, 92].includes(e.payheadMasterId) &&
      e.payheadName != 'Minimum Wages'
  );

  // set calculated data

  aTotal = +calculatedGross;
  extra_aTotal = +calculate_Without_A.extra_aTotal;
  bTotal = +calculate_Without_A.bTotal;
  cTotal = +calculate_Without_A.cTotal;

  // ----------------Calculate EPF amount ------------------

  if (EPF_Data) {
    const PF_Amount =
      finalStructureData.find((e) => e.payheadMasterId == 4)?.finalvalue || 0;
    const EPS_Amount =
      finalStructureData.find((e) => e.payheadMasterId == 12)?.finalvalue || 0;

    const finalvalue1 =
      +PF_Amount - +EPS_Amount > 0 ? +PF_Amount - +EPS_Amount : 0;

    const finalvalue =
      EPF_Data.salaryFieldRound == 'Y'
        ? EPF_Data.roundOffType == 0
          ? Math.ceil(finalvalue1.toFixed(2))
          : Math.round(finalvalue1)
        : !EPF_Data.salaryFieldRound
          ? Math.round(finalvalue1)
          : finalvalue1.toFixed(+EPF_Data.salaryFieldRoundNo);

    const actualvalue = +finalvalue1.toFixed(3);
    const yearly_finalvalue = Math.round(+finalvalue * 12);

    cTotal += +finalvalue;

    // Add finalvalue dynamically
    const EPF_Data_temp = {
      ...EPF_Data,
      finalvalue,
      actualvalue,
      yearly_finalvalue,
    };

    finalStructureData.splice(+EPF_Data.salaryfieldindex, 0, EPF_Data_temp);
  }

  // set CTC GROSS and NET SALARY
  [...NET_CTC_GROSS].forEach((e) => {
    // for CTC

    if (e.payheadMasterId == 1) {
      const amount =
        e.salaryFieldRound == 'Y'
          ? Math.round(+aTotal + +cTotal + +extra_aTotal)
          : (+aTotal + +cTotal + +extra_aTotal).toFixed(
              !e.salaryFieldRoundNo ? 0 : +e.salaryFieldRoundNo
            );

      e.finalvalue = +amount;
      e.yearly_finalvalue = Math.round(amount * 12);
      e.actualvalue = +amount;
    }
    // GROSS
    if (e.payheadMasterId == 50) {
      const amount =
        e.salaryFieldRound == 'Y'
          ? Math.round(+aTotal)
          : (+aTotal).toFixed(
              !e.salaryFieldRoundNo ? 0 : +e.salaryFieldRoundNo
            );

      e.finalvalue = +amount;
      e.yearly_finalvalue = Math.round(amount * 12);
      e.actualvalue = +amount;
    }

    // NET SALARY
    if (e.payheadMasterId == 92) {
      const amount =
        e.salaryFieldRound == 'Y'
          ? Math.round(+aTotal - +bTotal + +extra_aTotal)
          : (+aTotal - +bTotal + +extra_aTotal).toFixed(
              !e.salaryFieldRoundNo ? 0 : +e.salaryFieldRoundNo
            );

      e.finalvalue = +amount;
      e.yearly_finalvalue = Math.round(amount * 12);
      e.actualvalue = +amount;
    }
  });

  return {
    salaryStructureData: [...finalStructureData, ...NET_CTC_GROSS],
    minWagesMasterId,
  };
}

async function manualchangeSalaryStructure(
  grade_salary_structure_data_temp = [],
  ctc,
  gradeid,
  stateid,
  AmountIn,
  userMasterID,
  payheadmasterid,
  payheadAmount,
  yearMonth,
  gender
) {
  let aTotal = 0,
    bTotal = 0,
    cTotal = 0,
    extra_aTotal = 0;

  const NET_CTC_GROSS = [...grade_salary_structure_data_temp].filter(
    (e) => [1, 50, 92].includes(e.payheadmasterid) && e.sort == 2
  );

  const EPF_Data = [...grade_salary_structure_data_temp].find(
    (e) => e.payheadmasterid == 5
  );

  const grade_salary_structure_data = [
    ...grade_salary_structure_data_temp,
  ].filter((e) => ![1, 50, 92, 5].includes(e.payheadmasterid) || e.sort != 2);

  for (let n = 0; n < grade_salary_structure_data.length; n++) {
    let value = 0;
    let yearly_value = 0;

    if (
      AmountIn == '0' &&
      grade_salary_structure_data[n].sort == 1 &&
      grade_salary_structure_data[n].payheadname == 'CTC'
    ) {
      grade_salary_structure_data[n].fieldfixamount = Number(ctc);
    } else if (
      AmountIn == '1' &&
      grade_salary_structure_data[n].sort == 1 &&
      grade_salary_structure_data[n].payheadname == 'GROSS'
    ) {
      grade_salary_structure_data[n].fieldfixamount = Number(ctc);
    }

    if (payheadmasterid == grade_salary_structure_data[n].payheadmasterid) {
      grade_salary_structure_data[n].fieldfixamount = Number(payheadAmount);
    }

    if (grade_salary_structure_data[n].payheadmasterid == 15) {
      const month = String(yearMonth).slice(4, 6);

      let get_one_data1 = await ProfessionalTaxSlabMaster.findOne({
        where: {
          stateMasterID: +stateid,
          fromAmount: { [Sequelize.Op.lte]: +ctc },
          toAmount: { [Sequelize.Op.gte]: +ctc },
          status: 1,
          month: +month,
          applicableFromYYYYMM: {
            [Sequelize.Op.lte]: String(yearMonth),
          },
        },
        order: [['applicableFromYYYYMM', 'DESC']],
      });

      if (get_one_data1) {
        if (gender == 'female') {
          value = get_one_data1.femaleTax;
        } else {
          value = get_one_data1.maleTax;
        }
      } else {
        value = 0;
      }

      if (grade_salary_structure_data[n].salaryfieldwhenmonth[0] != 0) {
        let length = grade_salary_structure_data[n].salaryfieldwhenmonth.length;
        yearly_value = Number(value) * Number(length);
      } else {
        yearly_value = Number(value) * 12;
      }
    } else if (
      [9, 16, 17, 24, 34, 43, 78, 83, 96, 97, 99, 67, 101].includes(
        grade_salary_structure_data[n].payheadmasterid
      )
    ) {
      value = 0;
    } else {
      if (grade_salary_structure_data[n].formula) {
        value = Number(
          await infixtopostfix(
            grade_salary_structure_data[n].formula,
            ctc,
            gradeid,
            grade_salary_structure_data
          )
        );
      } else {
        value = Number(grade_salary_structure_data[n].fieldfixamount);
      }
    }

    let length = 12,
      salaryfieldroundno = 0;

    if (grade_salary_structure_data[n].salaryfieldwhenmonth[0] != 0) {
      length = grade_salary_structure_data[n].salaryfieldwhenmonth.length;
    }

    if (grade_salary_structure_data[n].salaryfieldround == 'Y') {
      grade_salary_structure_data[n].actualvalue = Number(value.toFixed(3));
      grade_salary_structure_data[n].finalvalue =
        grade_salary_structure_data[n].roundofftype == 0
          ? Math.ceil(value.toFixed(2))
          : Math.round(value);
      grade_salary_structure_data[n].yearly_finalvalue =
        Math.round(yearly_value);
    } else {
      salaryfieldroundno = !grade_salary_structure_data[n].salaryfieldroundno
        ? 0
        : +grade_salary_structure_data[n].salaryfieldroundno;

      grade_salary_structure_data[n].actualvalue = Number(value.toFixed(3));
      grade_salary_structure_data[n].finalvalue = Number(
        value.toFixed(salaryfieldroundno)
      );
      grade_salary_structure_data[n].yearly_finalvalue = Number(
        yearly_value.toFixed(salaryfieldroundno)
      );
    }

    if (grade_salary_structure_data[n].salaryfieldmaxrange) {
      if (
        Number(value) >
        Number(grade_salary_structure_data[n].salaryfieldmaxrange)
      )
        grade_salary_structure_data[n].finalvalue =
          grade_salary_structure_data[n].salaryfieldmaxrange;
    }

    grade_salary_structure_data[n].yearly_finalvalue = salaryfieldroundno
      ? (grade_salary_structure_data[n].finalvalue * length).toFixed(
          salaryfieldroundno
        )
      : Math.round(grade_salary_structure_data[n].finalvalue * length);

    if (![1, 50, 92].includes(grade_salary_structure_data[n].payheadmasterid)) {
      if (
        grade_salary_structure_data[n].salaryfieldsrno == 'A' &&
        grade_salary_structure_data[n].considerin != 'net'
      )
        aTotal += +grade_salary_structure_data[n].finalvalue;
      if (
        grade_salary_structure_data[n].salaryfieldsrno == 'A' &&
        grade_salary_structure_data[n].considerin == 'net'
      )
        extra_aTotal += +grade_salary_structure_data[n].finalvalue;
      if (grade_salary_structure_data[n].salaryfieldsrno == 'B')
        bTotal += +grade_salary_structure_data[n].finalvalue;
      if (grade_salary_structure_data[n].salaryfieldsrno == 'C')
        cTotal += +grade_salary_structure_data[n].finalvalue;
    }
  }

  // ----------------Calculate EPF amount ------------------

  if (EPF_Data) {
    const PF_Amount =
      grade_salary_structure_data.find((e) => e.payheadmasterid == 4)
        ?.finalvalue || 0;
    const EPS_Amount =
      grade_salary_structure_data.find((e) => e.payheadmasterid == 12)
        ?.finalvalue || 0;

    const finalvalue1 =
      +PF_Amount - +EPS_Amount > 0 ? +PF_Amount - +EPS_Amount : 0;

    const finalvalue =
      EPF_Data.salaryFieldRound == 'Y'
        ? EPF_Data.roundofftype == 0
          ? Math.ceil(finalvalue1.toFixed(2))
          : Math.round(finalvalue1)
        : !EPF_Data.salaryFieldRound
          ? Math.round(finalvalue1)
          : finalvalue1.toFixed(+EPF_Data.salaryFieldRoundNo);

    const actualvalue = +finalvalue1.toFixed(3);
    const yearly_finalvalue = Math.round(+finalvalue * 12);

    cTotal += +finalvalue;

    // Add finalvalue dynamically
    const EPF_Data_temp = {
      ...EPF_Data,
      finalvalue,
      actualvalue,
      yearly_finalvalue,
    };

    grade_salary_structure_data.splice(
      +EPF_Data.salaryfieldindex,
      0,
      EPF_Data_temp
    );
  }

  // set CTC GROSS and NET SALARY
  [...NET_CTC_GROSS].forEach((e) => {
    // for CTC

    if (e.payheadmasterid == 1) {
      const amount =
        e.salaryfieldround == 'Y'
          ? Math.round(+aTotal + +cTotal + +extra_aTotal)
          : (+aTotal + +cTotal + +extra_aTotal).toFixed(
              !e.salaryfieldroundno ? 0 : +e.salaryfieldroundno
            );

      e.finalvalue = +amount;
      e.yearly_finalvalue = Math.round(amount * 12);
      e.actualvalue = +amount;
    }
    // GROSS
    if (e.payheadmasterid == 50) {
      const amount =
        e.salaryfieldround == 'Y'
          ? Math.round(+aTotal)
          : (+aTotal).toFixed(
              !e.salaryfieldroundno ? 0 : +e.salaryfieldroundno
            );

      e.finalvalue = +amount;
      e.yearly_finalvalue = Math.round(amount * 12);
      e.actualvalue = +amount;
    }

    // NET SALARY
    if (e.payheadmasterid == 92) {
      const amount =
        e.salaryfieldround == 'Y'
          ? Math.round(+aTotal - +bTotal + +extra_aTotal)
          : (+aTotal - +bTotal + +extra_aTotal).toFixed(
              !e.salaryfieldroundno ? 0 : +e.salaryfieldroundno
            );

      e.finalvalue = +amount;
      e.yearly_finalvalue = Math.round(amount * 12);
      e.actualvalue = +amount;
    }
  });

  return [...grade_salary_structure_data, ...NET_CTC_GROSS];
}

const formatDateMonthInWords = (inputDate) => {
  // Split the input into month and day parts
  if (!inputDate) return '';
  const [year, month, day] = inputDate.split('-');

  // Create a Date object with the year set to the current year
  const currentDate = new Date();
  const currentYear = currentDate.getFullYear();

  // Create a new Date object with the provided month and day
  const formattedDate = new Date(currentYear, month - 1, day);

  // Get the day and month in a more readable format
  const formattedDay = formattedDate.getDate();
  const formattedMonth = formattedDate.toLocaleString('default', {
    month: 'long',
  });

  // Construct the final formatted string
  const result = `${formattedDay}${getDaySuffix(
    formattedDay
  )} ${formattedMonth}`;

  return result;
};

const getDaySuffix = (day) => {
  if (day >= 11 && day <= 13) {
    return 'th';
  }
  switch (day % 10) {
    case 1:
      return 'st';
    case 2:
      return 'nd';
    case 3:
      return 'rd';
    default:
      return 'th';
  }
};
function paginate(array, page_size, page_number) {
  return array.slice((page_number - 1) * page_size, page_number * page_size);
}

async function updateviewstatusAll(tableName, authstatus, userMasterID) {
  let model;
  if (tableName == 'leave') {
    model = LeaveAuthorizationRequest;
  } else if (tableName == 'expense') {
    model = expenseAuthorizations;
  } else if (tableName == 'overtime') {
    model = OvertimeAuthorizationRequest;
  }

  await model.update(
    {
      viewstatus: 1,
    },
    {
      where: {
        authstatus: authstatus,
        userMasterID: userMasterID,
      },
    }
  );

  return;
}

