async function getAllUserByBranch(branchMasterID, date, status, page, limit) {
  const condition = {
    branchID: branchMasterID,
    applicableDate: {
      [Sequelize.Op.lte]: date,
    },
    [Sequelize.Op.or]: [
      {
        endDate: {
          [Sequelize.Op.gte]: date,
        },
      },
      {
        endDate: null,
      },
    ],
    status: 1,
  };

  const paginateCondition = {};

  if (page && limit) {
    paginateCondition.offset = (page - 1) * limit;
    paginateCondition.limit = limit;
  }

  const get_branch_users = await EmployeeBranch.findAndCountAll({
    raw: true,
    where: condition,
    ...paginateCondition,

    include: [{ model: UserMaster, as: 'employee', where: { status: status } }],
  });

  return get_branch_users;
}

