async function employeeShift(userid, date, datetime) {
  datetime = new Date(datetime);
  let getShift = await EmployeeShift.findOne({
    raw: true,
    where: {
      userMasterID: userid,
      status: 1,
      startDate: {
        [Sequelize.Op.lte]: new Date(date),
      },
      [Sequelize.Op.or]: [
        {
          endDate: {
            [Sequelize.Op.gte]: new Date(date),
          },
        },
        {
          endDate: { [Sequelize.Op.eq]: null },
        },
      ],
    },
  });

  if (getShift) {
    if (getShift.shiftID) {
      getShift = await Shift.findOne({
        raw: true,
        where: {
          shiftID: getShift.shiftID,
        },
      });
    } else {
      let day = new Date(date).toLocaleString('en-us', { weekday: 'long' });
      let get_shifts = await shiftTime.findAll({
        raw: true,
        where: {
          day: day,
          '$shift.shiftID$': getShift.shiftsID,
          '$shift.status$': 1,
        },
        include: [
          {
            model: shiftModel,
            as: 'shift',
          },
        ],
      });

      if (get_shifts.length > 0) {
        for (var i = 0; i < get_shifts.length; i++) {
          let date1 = formatAMPM(datetime);
          var startTime = moment(date1, 'HH:mm a');
          var endTime = moment(get_shifts[i].statTime, 'HH:mm: a');
          var duration = moment.duration(startTime.diff(endTime));
          var hours = parseInt(duration.asHours());
          hours = hours * 60;
          var minutes = Math.abs((parseInt(duration.asMinutes()) % 60) + hours);
          get_shifts[i].min = minutes;
        }
        get_shifts.sort(function (a, b) {
          return a.min - b.min;
        });

        getShift = await Shift.findOne({
          raw: true,
          where: {
            shiftID: get_shifts[0].shiftID,
          },
        });
      } else {
        return null;
      }
    }
  }
  return getShift;
}

async function getShiftData_Manual(
  getEmployeeShift,
  getShiftRoster,
  date,
  transaction
) {
  try {
    // Find Current Day
    const today = asiaKolkataDateTime(new Date(date)).slice(0, 10);
    date = new Date(date);
    let day = new Date(date).toLocaleString('en-us', {
      weekday: 'long',
    });

    let shift = null;

    if (getShiftRoster) {
      shift = await Shift.findOne(
        {
          where: {
            shiftID: getShiftRoster.shiftID,
          },
          include: [
            {
              required: true,
              model: shiftTime,
              where: {
                day: day,
              },
            },
          ],
        },
        transaction
      );
    } else {
      if (getEmployeeShift) {
        if (getEmployeeShift.shiftID) {
          shift = await Shift.findOne(
            {
              where: {
                shiftID: getEmployeeShift.shiftID,
              },
              include: [
                {
                  required: true,
                  model: shiftTime,
                  where: {
                    day: day,
                  },
                },
              ],
            },
            transaction
          );
        } else {
          let day = new Date(today).toLocaleString('en-us', {
            weekday: 'long',
          });
          let get_shifts = await shiftTime.findAll({
            // raw: true,
            where: {
              day: day,
              '$shift.shiftID$': getEmployeeShift.shiftsID,
              '$shift.status$': 1,
            },
            include: [
              {
                model: shiftModel,
                as: 'shift',
              },
            ],
            transaction,
          });

          if (get_shifts.length > 0) {
            for (var i = 0; i < get_shifts.length; i++) {
              let date1 = formatAMPM(date);
              var startTime = moment(date1, 'HH:mm a');
              var endTime = moment(get_shifts[i].statTime, 'HH:mm: a');
              var duration = moment.duration(startTime.diff(endTime));
              var hours = parseInt(duration.asHours());
              hours = hours * 60;
              var minutes = Math.abs(
                (parseInt(duration.asMinutes()) % 60) + hours
              );
              get_shifts[i].min = minutes;
            }
            get_shifts.sort(function (a, b) {
              return a.min - b.min;
            });

            shift = await Shift.findOne(
              {
                // raw: true,
                where: {
                  shiftID: get_shifts[0].shiftID,
                },
                include: [
                  {
                    required: true,
                    model: shiftTime,
                    where: {
                      day: day,
                    },
                  },
                ],
              },
              transaction
            );
          }
        }
      }
    }
    return shift;
  } catch (error) {
    throw new Error('Error in getShiftData: ' + error.message);
  }
}

