async function calculateDateTimeDifference(dateTime1, dateTime2) {
  //datetime2 should be greater than datetime1
  //Time difference will be returned in minute format

  if (dateTime1 && dateTime2) {
    const timeDifference =
      (new Date(dateTime2) - new Date(dateTime1)) / (1000 * 60);

    return timeDifference;
  }

  return null;
}

const dateRegex = /^(?:\d{4})-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])$/;

const isValidDate = (dateString) => {
  return dateRegex.test(dateString);
};
const yearMonthCompactRegex = /^(?:\d{4})(0[1-9]|1[0-2])$/;

const isValidYearMonthCompact = (input) => {
  return yearMonthCompactRegex.test(input);
};
async function checkSubscriptionPlanExpiration(companyMasterID) {
  const getSubscriptionPlanData = await CompanySubscriptionMaster.findOne({
    where: {
      companyMasterID: companyMasterID,
      status: 1,
    },
    raw: true,
    attributes: [
      'companyPlanMasterID',
      'companyMasterID',
      'productMasterID',
      'totalUser',
      'totalTracking',
      'startDate',
      'endDate',
    ],
  });

  if (!getSubscriptionPlanData) {
    return null;
  }

  const { endDate } = getSubscriptionPlanData;
  const getDateTimeDifference = await calculateDateTimeDifference(
    new Date(),
    new Date(endDate)
  );

  const leftDaysForSubscriptionExpiration = Math.ceil(
    (getDateTimeDifference ? getDateTimeDifference : 0) / (60 * 24)
  );

  getSubscriptionPlanData.subscriptionData = {
    showSubscriptionExpirationMessage: leftDaysForSubscriptionExpiration <= 15,
    subscriptionExpirationDays: leftDaysForSubscriptionExpiration,
    subscriptionExpirationMessage:
      leftDaysForSubscriptionExpiration < 0
        ? 'Subscription plan has already expired.'
        : leftDaysForSubscriptionExpiration <= 15
          ? `Subscription plan will expire within ${leftDaysForSubscriptionExpiration} days.`
          : '',
  };

  return getSubscriptionPlanData;
}

async function sendMailforExpense(
  expenseHeadId,
  userExpenseID,
  Amount,
  Description,
  senderID
) {
  const userExpense = await UserExpense.findOne({
    raw: true,
    where: {
      userExpenseID: userExpenseID,
    },
  });
  if (!userExpense) {
    return;
  }

  let Expense_Head = await ExpenseHeadModel.findOne({
    raw: true,
    where: {
      expenseHeadId: expenseHeadId,
    },
  });
  Expense_Head = Expense_Head ? Expense_Head.expenseHead : '';

  let Expense_Category = await ExpenseCategoryModel.findOne({
    raw: true,
    where: {
      expenseCategoryId: userExpense.expenseCategoryId,
    },
  });
  Expense_Category = Expense_Category ? Expense_Category.expenseCategory : '';

  const userMasterID = userExpense.userMasterID;
  const expenseDate = userExpense.expense_date;

  let ExpenseType = '';
  if (userExpense.visitID) ExpenseType = 'Visit';
  else if (userExpense.ToursMasterID) ExpenseType = 'Tour';
  else ExpenseType = 'Personal';

  const UserDetails = await userDetails(userExpense.userMasterID);
  if (!UserDetails) return;

  const companyMasterID = UserDetails.companyMasterId;
  let get_MailTemplate;
  const get_NotificationPolicy =
    await findCompanyNotificationPolicy(companyMasterID);

  if (get_NotificationPolicy) {
    get_MailTemplate = await mailTemplateEditor.findOne({
      raw: true,
      where: {
        companyMasterID: companyMasterID,
        status: 1,
        mailTypeID: 2,
      },
    });

    if (get_MailTemplate) {
      let empcode = '',
        empname = '',
        empnumber = '',
        department = '',
        designation = '',
        branch = '';

      let emp_name = await UserMaster.findOne({
        raw: true,
        where: {
          userMasterID: userMasterID,
          status: 1,
        },
        attributes: ['displayName', 'userNumber'],
      });
      empnumber = emp_name ? emp_name.userNumber : '';
      empname = emp_name ? emp_name.displayName : '';

      let emp_code = await EmployeeJoiningDetails.findOne({
        raw: true,
        where: {
          userMasterID: userMasterID,
          status: 1,
        },
        attributes: ['employeeCode'],
      });
      empcode = emp_code ? emp_code.employeeCode : '';

      let emp_branch = await EmployeeBranch.findOne({
        raw: true,
        where: {
          userMasterID: userMasterID,
          status: 1,
          applicableDate: {
            [Sequelize.Op.lte]: new Date(),
          },
          [Sequelize.Op.or]: [
            {
              endDate: { [Sequelize.Op.gte]: new Date() },
            },
            {
              endDate: { [Sequelize.Op.eq]: null },
            },
          ],
        },
        attributes: ['branchID'],
        include: [
          {
            model: BranchMaster,
            as: 'branchMaster',
            attributes: ['branchName'],
          },
        ],
      });
      branch = emp_branch ? emp_branch['branchMaster.branchName'] : '';

      let emp_department = await EmployeeDepartment.findOne({
        raw: true,
        where: {
          userMasterID: userMasterID,
          status: 1,
          applicableDate: {
            [Sequelize.Op.lte]: new Date(),
          },
          [Sequelize.Op.or]: [
            {
              endDate: { [Sequelize.Op.gte]: new Date() },
            },
            {
              endDate: { [Sequelize.Op.eq]: null },
            },
          ],
        },
        attributes: ['departmentID'],
        include: [
          {
            model: Department,
            as: 'department',
            attributes: ['departmentName'],
          },
        ],
      });
      department = emp_department
        ? emp_department['department.departmentName']
        : '';

      let emp_designation = await EmployeeDesignation.findOne({
        raw: true,
        where: {
          userMasterID: userMasterID,
          status: 1,
          applicableDate: {
            [Sequelize.Op.lte]: new Date(),
          },
          [Sequelize.Op.or]: [
            {
              endDate: { [Sequelize.Op.gte]: new Date() },
            },
            {
              endDate: { [Sequelize.Op.eq]: null },
            },
          ],
        },
        attributes: ['designationID'],
        include: [
          {
            model: Designation,
            as: 'designation',
            attributes: ['designationName'],
          },
        ],
      });
      designation = emp_designation
        ? emp_designation['designation.designationName']
        : '';

      get_MailTemplate.subject = get_MailTemplate.subject
        .split('[EmployeeCode]')
        .join(empcode);
      get_MailTemplate.subject = get_MailTemplate.subject
        .split('[EmployeeName]')
        .join(empname);
      get_MailTemplate.subject = get_MailTemplate.subject
        .split('[EmployeeNumber]')
        .join(empnumber);
      get_MailTemplate.subject = get_MailTemplate.subject
        .split('[Department]')
        .join(department);
      get_MailTemplate.subject = get_MailTemplate.subject
        .split('[Designation]')
        .join(designation);
      get_MailTemplate.subject = get_MailTemplate.subject
        .split('[Branch]')
        .join(branch);
      get_MailTemplate.subject = get_MailTemplate.subject
        .split('[ExpenseType]')
        .join(ExpenseType);
      get_MailTemplate.subject = get_MailTemplate.subject
        .split('[ExpenseCategory]')
        .join(Expense_Category);
      get_MailTemplate.subject = get_MailTemplate.subject
        .split('[ExpenseHead]')
        .join(Expense_Head);
      get_MailTemplate.subject = get_MailTemplate.subject
        .split('[ExpenseDate]')
        .join(userExpense.expense_date ? userExpense.expense_date : '');
      get_MailTemplate.subject = get_MailTemplate.subject
        .split('[Amount]')
        .join(Amount);
      get_MailTemplate.subject = get_MailTemplate.subject
        .split('[ExpenseDescription]')
        .join(Description);

      get_MailTemplate.body = get_MailTemplate.body
        .split('[EmployeeCode]')
        .join(empcode);
      get_MailTemplate.body = get_MailTemplate.body
        .split('[EmployeeName]')
        .join(empname);
      get_MailTemplate.body = get_MailTemplate.body
        .split('[EmployeeNumber]')
        .join(empnumber);
      get_MailTemplate.body = get_MailTemplate.body
        .split('[Department]')
        .join(department);
      get_MailTemplate.body = get_MailTemplate.body
        .split('[Designation]')
        .join(designation);
      get_MailTemplate.body = get_MailTemplate.body
        .split('[Branch]')
        .join(branch);
      get_MailTemplate.body = get_MailTemplate.body
        .split('[ExpenseType]')
        .join(ExpenseType);
      get_MailTemplate.body = get_MailTemplate.body
        .split('[ExpenseCategory]')
        .join(Expense_Category);
      get_MailTemplate.body = get_MailTemplate.body
        .split('[ExpenseHead]')
        .join(Expense_Head);
      get_MailTemplate.body = get_MailTemplate.body
        .split('[ExpenseDate]')
        .join(userExpense.expense_date ? userExpense.expense_date : '');
      get_MailTemplate.body = get_MailTemplate.body
        .split('[Amount]')
        .join(Amount);
      get_MailTemplate.body = get_MailTemplate.body
        .split('[ExpenseDescription]')
        .join(Description);
    }
  }

  const user = await userDetails(senderID);

  if (user.email && get_MailTemplate) {
    let data = {
      email_id: user.email,
      body: get_MailTemplate.body,
      subject: get_MailTemplate.subject,
      email: get_NotificationPolicy.email,
      password: get_NotificationPolicy.password,
      port: get_NotificationPolicy.port,
      host: get_NotificationPolicy.hostmail,
      secure: get_NotificationPolicy.secure,
    };
    sendEmailForLeave(data);
  }
}

async function getUserByCompanyandDateRange(
  companyMasterID,
  page,
  limit,
  startdate,
  enddate
) {
  if (!startdate && !enddate) {
    const date = new Date().toISOString().slice(0, 10);
    startdate = date;
    enddate = date;
  }

  const condition = {
    joiningDate: {
      [Sequelize.Op.lte]: new Date(enddate),
    },
    [Sequelize.Op.or]: [
      {
        leavingDate: { [Sequelize.Op.gte]: new Date(startdate) },
      },
      {
        leavingDate: { [Sequelize.Op.eq]: null },
        [Sequelize.Op.or]: [
          {
            '$userMaster.deactiveDate$': {
              [Sequelize.Op.gte]: new Date(startdate),
            },
          },
          {
            '$userMaster.deactiveDate$': { [Sequelize.Op.eq]: null },
          },
        ],
      },
    ],
    '$userMaster.companyMasterId$': companyMasterID,
    '$userMaster.status$': [0, 1],
  };

  const paginateCondition = {};
  if (page && limit) {
    paginateCondition.offset = (page - 1) * limit;
    paginateCondition.limit = limit;
  }

  const companyUser = await EmployeeJoiningDetails.findAndCountAll({
    raw: true,
    where: condition,
    ...paginateCondition,
    include: [{ model: UserMaster }],
    order: [[{ model: UserMaster }, 'displayName', 'ASC']],
  });
  return companyUser;
}

async function getUserByBranchandDateRange(
  branchMasterID,
  page,
  limit,
  startdate,
  enddate
) {
  if (!startdate && !enddate) {
    const date = new Date().toISOString().slice(0, 10);
    startdate = date;
    enddate = date;
  }

  const condition = {
    branchID: branchMasterID,
    applicableDate: {
      [Sequelize.Op.lte]: new Date(enddate),
    },
    [Sequelize.Op.or]: [
      {
        endDate: {
          [Sequelize.Op.gte]: new Date(startdate),
        },
      },
      {
        endDate: null,
      },
    ],
    status: 1,
  };

  const get_branch_users = await EmployeeBranch.findAndCountAll({
    raw: true,
    where: condition,
  });
  let allActiveUsersID = [];
  for (let userID of get_branch_users.rows) {
    allActiveUsersID.push(userID.userMasterID);
  }

  const condition1 = {
    joiningDate: {
      [Sequelize.Op.lte]: new Date(enddate),
    },
    [Sequelize.Op.or]: [
      {
        leavingDate: { [Sequelize.Op.gte]: new Date(startdate) },
      },
      {
        leavingDate: { [Sequelize.Op.eq]: null },
        [Sequelize.Op.or]: [
          {
            '$userMaster.deactiveDate$': {
              [Sequelize.Op.gte]: new Date(startdate),
            },
          },
          {
            '$userMaster.deactiveDate$': { [Sequelize.Op.eq]: null },
          },
        ],
      },
    ],
    userMasterID: allActiveUsersID,
    '$userMaster.status$': [0, 1],
  };

  const paginateCondition = {};

  if (page && limit) {
    paginateCondition.offset = (page - 1) * limit;
    paginateCondition.limit = limit;
  }

  const branchUser = await EmployeeJoiningDetails.findAndCountAll({
    raw: true,
    where: condition1,
    ...paginateCondition,
    include: [{ model: UserMaster }],
    order: [[{ model: UserMaster }, 'displayName', 'ASC']],
  });

  branchUser.rows.forEach((row) => {
    const branchData = get_branch_users.rows.find(
      (user) => user.userMasterID === row.userMasterID
    );
    if (branchData) {
      row.branchStartDate = branchData.applicableDate;
      row.branchEndDate = branchData.endDate;
    }
  });

  return branchUser;
}

async function getFinancialYearDatesFromDate(dateString) {
  const fiscalYearStartMonth = 4;

  const [year, month, day] = dateString.split('-').map(Number);

  let startDate, endDate;

  if (month >= fiscalYearStartMonth) {
    startDate = new Date(year, fiscalYearStartMonth - 1, 1); // Month is zero-indexed
    endDate = new Date(year + 1, fiscalYearStartMonth - 1, 0);
  } else {
    startDate = new Date(year - 1, fiscalYearStartMonth - 1, 1);
    endDate = new Date(year, fiscalYearStartMonth - 1, 0);
  }

  return {
    startDate:
      new Date(startDate).getFullYear() +
      '-' +
      ('0' + (new Date(startDate).getMonth() + 1)).slice(-2) +
      '-' +
      ('0' + new Date(startDate).getDate()).slice(-2),
    endDate:
      new Date(endDate).getFullYear() +
      '-' +
      ('0' + (new Date(endDate).getMonth() + 1)).slice(-2) +
      '-' +
      ('0' + new Date(endDate).getDate()).slice(-2),
  };
}

async function getBranchByLatLong(
  companyMasterID,
  latitude,
  longitude,
  userMasterID,
  attendancePolicy,
  employeeBranch
) {
  let response = {
    id: null,
    locationType: '',
  };
  const date = asiaKolkataDateTime(new Date()).slice(0, 10);

  const branchMasterCondition = {
    companyMasterID: companyMasterID,
    status: 1,
  };
  if (attendancePolicy) {
    if (attendancePolicy.attBrType == attendanceBranchTypeRule.SELECTED) {
      branchMasterCondition.branchMasterID = {
        [Sequelize.Op.in]: attendancePolicy.attBranch?.map((e) => +e),
      };
    } else if (
      attendancePolicy.attBrType == attendanceBranchTypeRule.ASSIGNED &&
      employeeBranch
    ) {
      branchMasterCondition.branchMasterID = +employeeBranch.branchMasterID;
    } else if (
      attendancePolicy.attBrType == attendanceBranchTypeRule.ASSIGNED &&
      !employeeBranch
    ) {
      return response;
    }
  }
  const all_company_branch = await branchMaster.findAll({
    raw: true,
    where: branchMasterCondition,
  });
  let live_branch = null;
  if (all_company_branch.length > 0) {
    let flag = 0;
    for (var i = 0; i < all_company_branch.length; i++) {
      if (
        all_company_branch[i].latitude &&
        all_company_branch[i].longitude &&
        all_company_branch[i].radius
      ) {
        function toRad(Value) {
          return (Value * Math.PI) / 180;
        }
        var R = 6371000;
        var dLat = toRad(latitude - all_company_branch[i].latitude);
        var dLon = toRad(longitude - all_company_branch[i].longitude);
        var lat1 = toRad(all_company_branch[i].latitude);
        var lat2 = toRad(latitude);
        var a =
          Math.sin(dLat / 2) * Math.sin(dLat / 2) +
          Math.sin(dLon / 2) *
            Math.sin(dLon / 2) *
            Math.cos(lat1) *
            Math.cos(lat2);
        var c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
        var mainradius = R * c;

        if (all_company_branch[i].radius > mainradius) {
          live_branch = all_company_branch[i].branchMasterID;
          flag = 1;
          break;
        }
      }
    }
  }

  if (live_branch) {
    response.id = live_branch;
    response.locationType = 'branch';
  } else {
    const allWorkingLocation = await employeeWorkingLocation(
      userMasterID,
      new Date(date)
    );
    if (allWorkingLocation.length > 0) {
      let flag = 0;
      for (var i = 0; i < allWorkingLocation.length; i++) {
        if (
          allWorkingLocation[i].latitude &&
          allWorkingLocation[i].longitude &&
          allWorkingLocation[i].radius
        ) {
          function toRad(Value) {
            return (Value * Math.PI) / 180;
          }
          var R = 6371000;
          var dLat = toRad(latitude - allWorkingLocation[i].latitude);
          var dLon = toRad(longitude - allWorkingLocation[i].longitude);
          var lat1 = toRad(allWorkingLocation[i].latitude);
          var lat2 = toRad(latitude);
          var a =
            Math.sin(dLat / 2) * Math.sin(dLat / 2) +
            Math.sin(dLon / 2) *
              Math.sin(dLon / 2) *
              Math.cos(lat1) *
              Math.cos(lat2);
          var c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
          var mainradius = R * c;

          if (allWorkingLocation[i].radius > mainradius) {
            live_branch = allWorkingLocation[i].workingLocationID;
            flag = 1;
            break;
          }
        }
      }
    }

    if (live_branch) {
      response.id = live_branch;
      response.locationType = 'workinglocation';
    }
  }
  return response;
}

async function employeeWorkingLocation(userid, date) {
  const getWorkingLocation = await EmployeeWorkingLocation.findOne({
    raw: true,
    where: {
      userMasterID: userid,
      status: 1,
      startDate: {
        [Sequelize.Op.lte]: new Date(date),
      },
      [Sequelize.Op.or]: [
        {
          endDate: {
            [Sequelize.Op.gte]: new Date(date),
          },
        },
        {
          endDate: { [Sequelize.Op.eq]: null },
        },
      ],
    },
  });

  if (getWorkingLocation) {
    const allLocations = [];
    const findAllLocation = await WorkingLocation.findAll({
      raw: true,
      where: {
        workingLocationID: {
          [Sequelize.Op.in]: [...getWorkingLocation.workingLocationIDs],
        },
        status: 1,
      },
    });
    for (let currentLocation of getWorkingLocation.workingLocationIDs) {
      const Location = findAllLocation.find(
        (e) => e.workingLocationID == currentLocation
      );
      if (Location) allLocations.push(Location);
    }

    return allLocations;
  } else {
    return [];
  }
}

