async function countMonthCombinedPenalties(Policy, trans) {
  const user_salaryPolicy = await employeeSalaryPolicy(
    trans.userMasterID,
    trans.AttendanceDate
  );

  let start_Date;
  let end_Date;

  const month = Number(trans.AttendanceDate.substring(5, 7));
  const year = Number(trans.AttendanceDate.substring(0, 4));
  const monday = daysInMonth(month, year);

  if (user_salaryPolicy) {
    const date = user_salaryPolicy['salaryPolicy.salaryCycleDate'];

    const salary_startdate = date < 10 ? '0' + date : date;

    start_Date = trans.AttendanceDate.substring(0, 8) + salary_startdate;

    let date1 = new Date(start_Date);
    date1.setDate(date1.getDate() + (monday - 1));

    end_Date = trans.AttendanceDate;
  } else {
    start_Date = trans.AttendanceDate.substring(0, 8) + '01';

    end_Date = trans.AttendanceDate;
  }

  const monthly_Attendance = await attendanceTransaction.findAll({
    where: {
      userMasterID: trans.userMasterID,
      fulldayhalfday: 1,
      AttendanceDate: {
        [Sequelize.Op.between]: [start_Date, end_Date],
        [Sequelize.Op.ne]: trans.AttendanceDate,
      },
      [Sequelize.Op.or]: [
        {
          EarlyBy: { [Sequelize.Op.ne]: '', [Sequelize.Op.not]: null },
        },
        {
          LateBy: { [Sequelize.Op.ne]: '', [Sequelize.Op.not]: null },
        },
      ],
    },
    include: [
      {
        required: false,
        model: UserShortLeave,
        where: { authorizationStatus: 3 },
      },
    ],
    order: [['AttendanceDate', 'ASC']],
  });

  let count = 0;
  for (let k = 0; k < monthly_Attendance.length; k++) {
    //---------------------------Short leave condition---------------------
    const shortLeave = monthly_Attendance[k].userShortLeaves?.[0] || null;

    if (shortLeave) continue;

    const penaltyLateByCount =
      Math.ceil(
        +monthly_Attendance[k].LateBy - +Policy['lateEarlyPolicy.graceInTime'] >
          0
          ? +monthly_Attendance[k].LateBy -
              Number(Policy['lateEarlyPolicy.graceInTime'])
          : 0
      ) / Number(Policy['lateEarlyPolicy.combinedmaxminute']);

    const penaltyEarlyByCount = Math.ceil(
      Number(monthly_Attendance[k].EarlyBy) /
        Number(Policy['lateEarlyPolicy.combinedmaxminute'])
    );
    count += penaltyEarlyByCount + penaltyLateByCount;
  }

  return count;
}

async function getCurrentEarlyByPenalty(trans, LateEarlyPolicy) {
  if (!trans.EarlyBy || +trans.fulldayhalfday == 0) return 0;

  if (
    LateEarlyPolicy['lateEarlyPolicy.earlydeductioncategory'] == 'slotwise' &&
    LateEarlyPolicy['lateEarlyPolicy.earlydeductioncycle'] == 'daywise'
  ) {
    //Slot Used till last attendance for current Month
    const MonthEarlyByCount = await countMonthEarlyByPenalties(
      LateEarlyPolicy,
      trans
    );

    //Slot Used for current Attendance
    const CurrentEarlyByCount = await CountCurrentPenalties(
      LateEarlyPolicy['lateEarlyPolicy.earlymaxminute'],
      trans.EarlyBy
    );

    //Sum of both Slot Used
    const totalPenalties =
      Number(MonthEarlyByCount) + Number(CurrentEarlyByCount);

    //if sum is within the count allowed in the policy
    if (
      totalPenalties <= Number(LateEarlyPolicy['lateEarlyPolicy.earlynoof'])
    ) {
      return (
        Number(LateEarlyPolicy['lateEarlyPolicy.earlymaxminute']) *
        +CurrentEarlyByCount
      );
    } else {
      return 0;
    }
  } else if (
    LateEarlyPolicy['lateEarlyPolicy.earlydeductioncategory'] == 'countwise'
  ) {
    if (
      Number(LateEarlyPolicy['lateEarlyPolicy.earlymaxminute']) <
      Number(trans.EarlyBy)
    ) {
      return 0;
    }
    const Penaltycount = await countEarlyPenalties(trans);
    if (Penaltycount >= Number(LateEarlyPolicy['lateEarlyPolicy.earlynoof'])) {
      return 0;
    } else {
      return Number(LateEarlyPolicy['lateEarlyPolicy.earlymaxminute']);
    }
  } else {
    return 0;
  }
}

