async function earlyByPermissionOLD(trans, shift, finalEarlyby) {
  let goEarlyUsed = 0;
  if (
    shift.goEarly &&
    shift.goEarly > 0 &&
    shift.goEarlyallowdays &&
    shift.goEarlyallowdays > 0
  ) {
    if (finalEarlyby != '' && finalEarlyby != 0) {
      let isOnLeave;

      //Leave Logic
      isOnLeave = await UserLeave.findOne({
        where: {
          userMasterID: trans.userMasterID,
          DayType: 'Second Half',
          FromDate: {
            [Sequelize.Op.lte]: new Date(trans.AttendanceDate),
          },
          ToDate: {
            [Sequelize.Op.gte]: new Date(trans.AttendanceDate),
          },
        },
      });

      if (!isOnLeave) {
        const currentDate = new Date(trans.AttendanceDate)
          .toISOString()
          .slice(0, 10);

        const user_salaryPolicy = await employeeSalaryPolicy(
          trans.userMasterID,
          currentDate
        );

        let start_Date;
        let end_Date;

        const month = Number(currentDate.substring(5, 7));
        const year = Number(currentDate.substring(0, 4));
        const monday = daysInMonth(month, year);

        if (user_salaryPolicy) {
          const date = user_salaryPolicy['salaryPolicy.salaryCycleDate'];

          const salary_startdate = date < 10 ? '0' + date : date;

          start_Date = currentDate.substring(0, 8) + salary_startdate;

          let date1 = new Date(start_Date);
          date1.setDate(date1.getDate() + (monday - 1));

          end_Date =
            date1.getFullYear() +
            '-' +
            String(date1.getMonth() + 1).padStart(2, '0') +
            '-' +
            String(date1.getDate()).padStart(2, '0');
        } else {
          start_Date = currentDate.substring(0, 8) + '01';

          end_Date = start_Date.substring(0, 8) + monday;
        }

        //To get all attendance of current month
        let monthly_Attendance = await sequelize.query(
          `  
       select * from "attendanceTransactions" where "userMasterID"=$id and "fulldayhalfday"!='0' and ("AttendanceDate" BETWEEN $startdate and $enddate) and ("Status"=1 or "Status"=0) ORDER BY "AttendanceDate"
       `,
          {
            bind: {
              id: trans.userMasterID,
              startdate: start_Date,
              enddate: end_Date,
            },
            type: Sequelize.SELECT,
          }
        );
        monthly_Attendance = monthly_Attendance[0];

        if (shift.goEarly >= Number(finalEarlyby)) {
          if (monthly_Attendance.length != 0) {
            let count = 0;
            for (var i = 0; i < monthly_Attendance.length; i++) {
              if (monthly_Attendance[i].goEarlyUsed != 0) {
                count++;
              }
            }

            if (count < shift.goEarlyallowdays) {
              goEarlyUsed = 1;
            }
          } else {
            //If First Day
            if (shift.goEarlyallowdays > 0) {
              goEarlyUsed = 1;
            }
          }
        }
      }
    }
  }

  return goEarlyUsed;
}

function isInFinancialYear(dateRangeStart, dateRangeEnd) {
  const startDate = new Date(dateRangeStart);
  const endDate = new Date(dateRangeEnd);
  // Extract year from start date
  let startYear = startDate.getFullYear();
  // Determine the financial year based on the start date

  if (startDate.getMonth() < 3) startYear--;

  const financialStartDate = new Date(
    moment(`${startYear}-04-01`).format('YYYY-MM-DD')
  );
  const financialEndDate = new Date(
    moment(`${startYear + 1}-03-31`).format('YYYY-MM-DD')
  );

  // Check if the end date falls within the financial year
  return endDate >= financialStartDate && endDate <= financialEndDate;
}

const isInCalendarYear = (startDate, endDate) => {
  const startYear = new Date(startDate).getFullYear();
  const endYear = new Date(endDate).getFullYear();

  // const startYear = startDate.getFullYear();
  // const endYear = endDate.getFullYear();

  return startYear === endYear;
};

async function addAsopalavBreakTime(trans, continueIN) {
  if (!trans.lunchBreak) {
    const diff =
      (new Date(continueIN).getTime() - new Date(trans.OutDateTime).getTime()) /
      60 /
      1000;
    const LunchBreak = {
      diff: Math.round(diff),
      starttime: trans.OutDateTime,
      endtime: continueIN,
      type: 'lunchBreak',
    };

    return LunchBreak;
  } else if (!trans.teaBreak) {
    const diff =
      (new Date(continueIN).getTime() - new Date(trans.OutDateTime).getTime()) /
      60 /
      1000;
    const TeaBreak = {
      diff: Math.round(diff),
      starttime: trans.OutDateTime,
      endtime: continueIN,
      type: 'teaBreak',
    };

    return TeaBreak;
  } else {
    const EmptyBreak = {
      diff: null,
      starttime: null,
      endtime: null,
      type: null,
    };
    return EmptyBreak;
  }
}

async function getAsopalavBreakTime_Manual(trans, continueIN, LastOutLog) {
  if (!trans.lunchBreak) {
    const diff =
      (new Date(continueIN).getTime() - new Date(LastOutLog).getTime()) /
      60 /
      1000;
    const LunchBreak = {
      diff: Math.round(diff),
      starttime: LastOutLog,
      endtime: continueIN,
      type: 'lunchBreak',
    };

    return LunchBreak;
  } else if (!trans.teaBreak) {
    const diff =
      (new Date(continueIN).getTime() - new Date(LastOutLog).getTime()) /
      60 /
      1000;
    const TeaBreak = {
      diff: Math.round(diff),
      starttime: LastOutLog,
      endtime: continueIN,
      type: 'teaBreak',
    };

    return TeaBreak;
  } else {
    const EmptyBreak = {
      diff: null,
      starttime: null,
      endtime: null,
      type: null,
    };
    return EmptyBreak;
  }
}

async function addAsopalavBreakTimePenalty(userid, date, penaltyID) {
  const findPenalty = await Penalty.findOne({
    raw: true,
    where: {
      penaltyID: penaltyID,
    },
  });

  if (!findPenalty) return;

  const findUserPenalty = await EmployeePenalties.findOne({
    where: {
      userMasterID: userid,
      penaltyDate: date,
      penaltyID: penaltyID,
    },
  });

  if (findUserPenalty) return;

  await EmployeePenalties.create({
    userMasterID: userid,
    penaltyID: penaltyID,
    penaltyAmount: findPenalty.penaltyAmount,
    description: findPenalty.penaltyName,
    createBy: userid,
    penaltyDate: date,
  });
}

async function addAsopalavBreakTimePenalty_Manual(
  findPenalty,
  userid,
  date,
  penaltyID,
  transaction
) {
  const findUserPenalty = await EmployeePenalties.findOne({
    where: {
      userMasterID: userid,
      penaltyDate: date,
      penaltyID: penaltyID,
    },
    transaction,
  });

  if (findUserPenalty) return;

  await EmployeePenalties.create(
    {
      userMasterID: userid,
      penaltyID: penaltyID,
      penaltyAmount: findPenalty.penaltyAmount,
      description: findPenalty.penaltyName,
      createBy: userid,
      penaltyDate: date,
    },
    { transaction }
  );
}

async function getLeave(userMasterID, date) {
  const approvedLeave = await executeQuery(
    `SELECT hlm."LeaveName",hlm."LeaveID" from "userLeaves" as ul INNER join "userLeaveTransactions" as ult on ul."UserLeaveApplicationID"=ult."ReferenceID" INNER join "hrLeaveTypes" as hlt on ult."LeaveTranId"=hlt."LeaveTranId" inner join "hrLeaveMasters" as hlm on hlm."LeaveID"=hlt."LeaveID" WHERE ul."authorizationStatus" not in (4) and ul."status"=1 and ul."userMasterID"=` +
      userMasterID +
      ` and ult."status"=1 and (TO_DATE(ult."date", 'YYYY-MM-DD')>='` +
      date +
      `' and TO_DATE(ult."date", 'YYYY-MM-DD')<='` +
      date +
      `')`
  );

  if (approvedLeave.length > 0) {
    if (approvedLeave[0].LeaveID == 18) {
      return 'L.W.P';
    } else {
      return approvedLeave[0].LeaveName;
    }
  } else {
    const findLeave = await UserLeave.findOne({
      raw: true,
      where: {
        status: 1,
        userMasterID: userMasterID,
        [Sequelize.Op.or]: [
          {
            FromDate: {
              [Sequelize.Op.between]: [date, date],
            },
          },
          {
            ToDate: {
              [Sequelize.Op.between]: [date, date],
            },
          },
          {
            FromDate: {
              [Sequelize.Op.lte]: date,
            },
            ToDate: {
              [Sequelize.Op.gte]: date,
            },
          },
        ],
        authorizationStatus: [0, 1, 2],
      },
    });

    if (findLeave) {
      return 'Leave';
    } else {
      return null;
    }
  }
}

