async function getSalaryData(userId, month) {
  const salarydata = await HRSalaryTrasaction.findAll({
    raw: true,
    where: {
      userMasterID: userId,
      salaryYYYYMM: month,
    },
    include: [
      {
        model: HRSalaryMaster,
        include: [
          {
            model: GradeSalaryStructure,
            include: [
              { model: GradeStructure, attributes: [] },
              {
                model: HRSalaryFields,
                include: [
                  {
                    model: Payheadmaster,
                    attributes: [],
                  },
                ],
                attributes: [],
              },
            ],
            attributes: [],
          },
        ],
        attributes: [],
      },
      {
        model: UserMaster,
        as: 'createByUser',
        attributes: ['displayName'],
      },
    ],

    attributes: [
      [
        Sequelize.col(
          'hrSalaryMaster.gradeSalaryStructure.hrSalaryField.payheadMasterId'
        ),
        'payheadMasterId',
      ],
      [
        Sequelize.col(
          'hrSalaryMaster.gradeSalaryStructure.hrSalaryField.Payheadmaster.payheadName'
        ),
        'payheadName',
      ],
      [
        Sequelize.col(
          'hrSalaryMaster.gradeSalaryStructure.hrSalaryField.payheadDisplayName'
        ),
        'payheadDisplayName',
      ],
      [Sequelize.col('hrSalaryMaster.EmployeeSalaryAmount'), 'actualAmount'],
      'EmployeeSalaryAmount',
      'salaryYYYYMM',
      'userMasterID',
      'SalaryCalcOnDays',
      'createBy',
      'calculatedOn',
      [Sequelize.col('createByUser.displayName'), 'createByUserName'],
      [
        Sequelize.col(
          'hrSalaryMaster.gradeSalaryStructure.gradeStructure.baseOnCalculation'
        ),
        'baseOnCalculation',
      ],
      [Sequelize.col('hrSalaryMaster.gradeSalaryStructure.formula'), 'formula'],
      [
        Sequelize.col(
          'hrSalaryMaster.gradeSalaryStructure.hrSalaryField.salaryFieldSrNo'
        ),
        'salaryFieldSrNo',
      ],
      [
        Sequelize.col(
          'hrSalaryMaster.gradeSalaryStructure.hrSalaryField.salaryFieldSide'
        ),
        'salaryFieldSide',
      ],
      [
        Sequelize.col(
          'hrSalaryMaster.gradeSalaryStructure.hrSalaryField.considerIn'
        ),
        'considerIn',
      ],
    ],

    order: [
      // Order by salaryfieldindex in GradeSalaryStructure
      [
        { model: HRSalaryMaster, as: 'hrSalaryMaster' },
        { model: GradeSalaryStructure, as: 'gradeSalaryStructure' },
        'salaryfieldindex',
        'ASC',
      ],

      // Order by payheadName in Payheadmaster
      [
        { model: HRSalaryMaster, as: 'hrSalaryMaster' },
        { model: GradeSalaryStructure, as: 'gradeSalaryStructure' },
        { model: HRSalaryFields, as: 'hrSalaryField' },
        { model: Payheadmaster, as: 'Payheadmaster' },
        'payheadName',
        'ASC',
      ],
    ],
  });

  const depositData = await deposit.findAll({
    where: {
      depositReceiveAs: 'salary',
      salaryMonth: month,
      ReferenceId: {
        [Sequelize.Op.not]: null,
      },
      userMasterID: userId,
      status: 1,
    },
    include: [{ model: depositcategory, attributes: ['depositcategoryname'] }],
  });

  let startdate =
    month.toString().slice(0, 4) +
    '-' +
    month.toString().slice(4, 6) +
    '-' +
    '01';
  let enddate =
    month.toString().slice(0, 4) +
    '-' +
    month.toString().slice(4, 6) +
    '-' +
    daysInMonth(month.toString().slice(4, 6), month.toString().slice(0, 4));

  const findDate = await HrLeaveMonthlyTrans.findOne({
    raw: true,
    where: {
      userMasterID: userId,
      AttnYearMon: month,
    },
  });

  if (findDate) {
    if (findDate.monthstartdate) startdate = findDate.monthstartdate;
    if (findDate.monthenddate) enddate = findDate.monthenddate;
  }

  let finaldata = [];

  const attendancePolicy = await employeeAttendancePolicy(userId, enddate);

  await Promise.all(
    salarydata.map(async (e) => {
      if (e.payheadMasterId == 24) {
        const incentive = await Employeeincentive.findAll({
          raw: true,
          where: {
            userMasterID: userId,
            status: 1,
            incentiveDate: {
              [Sequelize.Op.between]: [startdate, enddate],
            },
            // yearmonth: month,
            ReferenceId: {
              [Sequelize.Op.not]: null,
            },
          },
          group: [
            'incentivetype.IncentivetypeID',
            'incentivetype.incentivetypename',
            'incentivetype.consider',
          ],
          include: [
            {
              model: Incentivetype,
              // where: { showinsalaryslip: 'true' },
              attributes: [],
            },
          ],
          attributes: [
            [Sequelize.col('incentivetype.IncentivetypeID'), 'IncentivetypeID'],
            [
              Sequelize.col('incentivetype.incentivetypename'),
              'incentivetypename',
            ],
            [
              Sequelize.col('incentivetype.inc_type_displayName'),
              'inc_type_displayName',
            ],
            [Sequelize.col('incentivetype.consider'), 'consider'],

            [
              Sequelize.literal(`coalesce(sum(NULLIF("amount",null)), 0)`),
              'amount',
            ],
          ],
        });

        incentive.forEach((data) => {
          finaldata.push({
            payheadMasterId: e.payheadMasterId,
            payheadName: data.inc_type_displayName
              ? data.inc_type_displayName
              : data.incentivetypename,
            actualAmount: e.actualAmount,
            EmployeeSalaryAmount: data.amount,
            salaryYYYYMM: e.salaryYYYYMM,
            userMasterID: e.userMasterID,
            baseOnCalculation: e.baseOnCalculation,
            formula: e.formula,
            salaryFieldSrNo: e.salaryFieldSrNo,
            salaryFieldSide: e.salaryFieldSide,
            consider: data.consider,
          });
        });
      } else if (e.payheadMasterId == 34) {
        const penaltydata = await EmployeePenalties.findAll({
          raw: true,
          where: {
            userMasterID: userId,
            status: 1,
            penaltyDate: {
              [Sequelize.Op.between]: [startdate, enddate],
            },
            RefrenceId: {
              [Sequelize.Op.not]: null,
            },
          },
          group: ['penalty.penaltyID', 'penalty.penaltyName'],
          include: [
            {
              model: Penalty,
              as: 'penalty',
              // where: { deductionFromSalary: true },
              attributes: [],
            },
          ],
          attributes: [
            [Sequelize.col('penalty.penaltyID'), 'penaltyID'],
            [
              Sequelize.literal(
                `coalesce(sum(NULLIF("employeePenalty"."penaltyAmount", null)), 0)`
              ),
              'amount',
            ],
            [Sequelize.col('penalty.penaltyName'), 'penaltyName'],
          ],
        });

        penaltydata.map((data) => {
          finaldata.push({
            payheadMasterId: e.payheadMasterId,
            payheadName: data.penaltyName,
            actualAmount: e.actualAmount,
            EmployeeSalaryAmount: data.amount,
            salaryYYYYMM: e.salaryYYYYMM,
            userMasterID: e.userMasterID,
            baseOnCalculation: e.baseOnCalculation,
            formula: e.formula,
            salaryFieldSrNo: e.salaryFieldSrNo,
            salaryFieldSide: e.salaryFieldSide,
          });
        });
      } else if (e.payheadMasterId == 43) {
        if (attendancePolicy && +e.EmployeeSalaryAmount > 0) {
          finaldata.push({ ...e, consider: attendancePolicy.consider });
        }
      } else if (e.payheadMasterId == 96) {
        const depositToDeduction = depositData.length
          ? [...depositData].filter(
              (e) => e.depositReceiveAs == 'salary' && e.salaryMonth == month
            )
          : [];
        const result = Object.values(
          depositToDeduction.reduce((acc, curr) => {
            if (!acc[curr.depositcategory.depositcategoryname]) {
              acc[curr.depositcategory.depositcategoryname] = {
                payheadMasterId: e.payheadMasterId,
                payheadDisplayName: '',
                payheadName: curr.depositcategory.depositcategoryname,
                actualAmount: 0,
                EmployeeSalaryAmount: 0,
                salaryYYYYMM: e.salaryYYYYMM,
                userMasterID: e.userMasterID,
                baseOnCalculation: e.baseOnCalculation,
                formula: e.formula,
                salaryFieldSrNo: e.salaryFieldSrNo,
                salaryFieldSide: e.salaryFieldSide,
              };
            }
            acc[
              curr.depositcategory.depositcategoryname
            ].EmployeeSalaryAmount += curr.amount; // Sum the amount
            return acc;
          }, {})
        );
        finaldata = [...finaldata, ...result];
      } else if (e.payheadMasterId == 97) {
        const depositToPay = depositData.length
          ? [...depositData].filter(
              (e) => e.depositPayAs == 'salary' && e.salaryMonthToPay == month
            )
          : [];
        const result = Object.values(
          depositToPay.reduce((acc, curr) => {
            if (!acc[curr.depositcategory.depositcategoryname]) {
              acc[curr.depositcategory.depositcategoryname] = {
                payheadMasterId: e.payheadMasterId,
                payheadDisplayName: '',
                payheadName: curr.depositcategory.depositcategoryname,
                actualAmount: 0,
                EmployeeSalaryAmount: 0,
                salaryYYYYMM: e.salaryYYYYMM,
                userMasterID: e.userMasterID,
                baseOnCalculation: e.baseOnCalculation,
                formula: e.formula,
                salaryFieldSrNo: e.salaryFieldSrNo,
                salaryFieldSide: e.salaryFieldSide,
                considerIn: e.considerIn,
              };
            }
            acc[
              curr.depositcategory.depositcategoryname
            ].EmployeeSalaryAmount += curr.amount; // Sum the amount
            return acc;
          }, {})
        );
        finaldata = [...finaldata, ...result];
      } else if (e.payheadMasterId == 67) {
        if (+e.EmployeeSalaryAmount > 0) {
          finaldata.push({ ...e });
        }
      } else if (e.payheadMasterId == 101) {
        if (+e.EmployeeSalaryAmount > 0) {
          finaldata.push({ ...e });
        }
      } else {
        // for Gratuity
        if (e.payheadMasterId == 83) {
          if (+e.EmployeeSalaryAmount > 0) finaldata.push(e);
        } else {
          finaldata.push(e);
        }
      }
    })
  );

  return finaldata;
}

async function getSundaysBetweenDates(startDate, endDate) {
  const sundays = [];
  let currentDate = new Date(startDate);
  let enddate = new Date(endDate);

  while (currentDate <= enddate) {
    if (currentDate.getDay() === 0) {
      sundays.push(new Date(currentDate).toISOString().slice(0, 10));
    }
    currentDate.setDate(currentDate.getDate() + 1);
  }

  return sundays;
}

async function getAttendanceData(
  userMasterID,
  start_date,
  end_date,
  includeShift
) {
  const includeArray = [];
  if (includeShift) {
    includeArray.push({
      model: Shift,
      attributes: ['shiftID'],
      include: [{ model: ShiftTIme }],
    });
  }

  const attendancedata = await attendanceTransaction.findAll({
    where: {
      userMasterID,
      AttendanceDate: {
        [Sequelize.Op.between]: [start_date, end_date],
      },

      roundOffMinutes: {
        [Sequelize.Op.or]: [
          {
            [Sequelize.Op.eq]: Sequelize.literal(`
              (SELECT MAX(at2."roundOffMinutes") 
               FROM "attendanceTransactions" AS at2 
               WHERE at2."AttendanceDate" = "attendanceTransaction"."AttendanceDate" 
               AND at2."userMasterID" = "attendanceTransaction"."userMasterID"
               AND at2."roundOffMinutes" IS NOT NULL
              )
            `),
          },

          {
            [Sequelize.Op.and]: [
              Sequelize.literal(`
                NOT EXISTS (
                  SELECT 1 FROM "attendanceTransactions" AS at2
                  WHERE at2."AttendanceDate" = "attendanceTransaction"."AttendanceDate"
                  AND at2."userMasterID" = "attendanceTransaction"."userMasterID"
                  AND at2."roundOffMinutes" IS NOT NULL
                )
              `),
              { [Sequelize.Op.is]: null },
            ],
          },
        ],
      },
      AttendanceTransID: {
        [Sequelize.Op.notIn]: Sequelize.literal(`    
          (WITH duplicate_records AS (
          SELECT
              "trans1"."AttendanceTransID",
              "trans1"."AttendanceDate",
              "trans1"."roundOffMinutes",
              ROW_NUMBER() OVER (
                  PARTITION BY "trans1"."AttendanceDate", "trans1"."roundOffMinutes"
                  ORDER BY "trans1"."AttendanceTransID" ASC
              ) AS row_num
          FROM "attendanceTransactions" AS "trans1"
          JOIN (
              SELECT "AttendanceDate", "roundOffMinutes"
              FROM "attendanceTransactions"
              WHERE "userMasterID" = ${userMasterID}
              AND "AttendanceDate" BETWEEN '${start_date}' and '${end_date}'
              GROUP BY "AttendanceDate", "roundOffMinutes"
              HAVING COUNT(*) > 1
          ) AS "trans"
          ON "trans1"."AttendanceDate" = "trans"."AttendanceDate"
          AND COALESCE(CAST("trans1"."roundOffMinutes" AS INTEGER), -1) =
              COALESCE(CAST("trans"."roundOffMinutes" AS INTEGER), -1)
          WHERE "trans1"."userMasterID" = ${userMasterID}
          AND "trans1"."AttendanceDate" BETWEEN '${start_date}' and '${end_date}'
      )
      SELECT "AttendanceTransID"
      FROM duplicate_records
      WHERE row_num > 1)`),
      },
    },
    include: includeArray,
    order: [['AttendanceDate', 'ASC']],
  });

  return attendancedata;
}

// Asopalav

async function getOTDaysforAsopalav(userMasterID, yearMonth) {
  const findleavedata = await HrLeaveMonthlyTrans.findAll({
    raw: true,
    where: {
      userMasterID: userMasterID,
      AttnYearMon: yearMonth,
    },
    include: [{ model: HrLeaveTypes, attributes: ['LeaveID'] }],
  });

  let ot_min = 0;
  let date = '';

  const attendancedata = await getAttendanceData(
    userMasterID,
    findleavedata[0].monthstartdate,
    findleavedata[0].monthenddate,
    false
  );

  const present = attendancedata.reduce((acc, obj) => {
    return acc + +obj.fulldayhalfday;
  }, 0);

  const monday = daysInMonth(
    yearMonth.toString().slice(4, 6),
    yearMonth.toString().slice(0, 4)
  );

  const findWeekoff_HolidayData = findleavedata
    .filter(
      (e) => e['hrLeaveType.LeaveID'] == 7 || e['hrLeaveType.LeaveID'] == 9
    )
    .reduce((acc, obj) => acc + +obj.AttnVal, 0);

  const ot_days = +present + +findWeekoff_HolidayData - +monday;

  if (ot_days > 0) {
    date = findleavedata[0].monthenddate;
    ot_min = +ot_days * (+attendancedata[0].Shifthrs * 60);
  }

  return {
    minutes: ot_min,
    date: date,
  };
}

