async function addThreeDaysExtraAmount(
  userMasterID,
  month,
  absent,
  createBy,
  createByIp,
  end_date
) {
  await sequelize.transaction(async (t) => {
    // find incentive
    const incentive = await Employeeincentive.findOne({
      raw: true,
      where: {
        userMasterID: userMasterID,
        yearmonth: month,
        IncentivetypeID: 129, // incentive id
      },
    });

    if (incentive) {
      await Employeeincentive.destroy(
        {
          where: {
            employeeincentiveID: incentive.employeeincentiveID,
          },
        },
        { transaction: t }
      );
    }

    if (+absent <= 7) {
      // add 3 days incentive
      const salary = await getUserSalaryMasterByMonth(userMasterID, month);

      const gross =
        +[...salary].find((e) => e.payheadMasterId == 50)
          ?.EmployeeSalaryAmount || 0;

      const daysinmonth = daysInMonth(
        month.toString().slice(4, 6),
        month.toString().slice(0, 4)
      );

      const incentiveAmount = (+gross / +daysinmonth) * 3;

      if (+incentiveAmount > 0) {
        await Employeeincentive.create(
          {
            userMasterID: userMasterID,
            yearmonth: month,
            amount: Math.round(+incentiveAmount),
            incentiveDate: end_date,
            IncentivetypeID: 129, // incentive id
            createBy: createBy,
            createByIp: createByIp,
          },
          { transaction: t }
        );
      }
    }
  });
}

// SRI VAISHNAVI RETAIL (INDIA) LLP

async function checkSundayPresentDoublesalary(
  attendancedata,
  userMasterID,
  start_date,
  end_date,
  branchId,
  month,
  createBy,
  createByIp
) {
  if (+attendancedata.length > 0) {
    await sequelize.transaction(async (t) => {
      // delete incentive

      await Employeeincentive.destroy(
        {
          where: {
            userMasterID: userMasterID,
            yearmonth: +month,
            IncentivetypeID: 159, // incentive id
          },
        },
        { transaction: t }
      );

      let sundaydoubleCount = 0;

      if ([427, 430, 433, 432, 2553].includes(branchId)) {
        const sundays = await getSundaysBetweenDates(start_date, end_date);

        for (const sunday of sundays) {
          let sun = false,
            sat = false,
            mon = false;

          const att = attendancedata.find(
            (e) => e.AttendanceDate == sunday && +e.fulldayhalfday == 1
          );

          if (att) {
            sun = true;

            // set date for saturday

            let date = new Date(sunday);

            date.setDate(date.getDate() - 1);

            const before_date =
              date.getFullYear() +
              '-' +
              String(date.getMonth() + 1).padStart(2, '0') +
              '-' +
              String(date.getDate()).padStart(2, '0');

            if (new Date(before_date) < new Date(start_date)) {
              const satAtt = await attendanceTransaction.findOne({
                raw: true,
                where: {
                  userMasterID: userMasterID,
                  AttendanceDate: before_date,
                  fulldayhalfday: 1,
                },
              });

              if (satAtt) sat = true;
            } else {
              const satAtt = attendancedata.find(
                (e) => e.AttendanceDate == before_date && +e.fulldayhalfday == 1
              );
              if (satAtt) sat = true;
            }

            if (sat == true) {
              // set date for monday

              let date1 = new Date(sunday);

              date1.setDate(date1.getDate() + 1);

              const after_date =
                date1.getFullYear() +
                '-' +
                String(date1.getMonth() + 1).padStart(2, '0') +
                '-' +
                String(date1.getDate()).padStart(2, '0');

              if (new Date(end_date) < new Date(after_date)) {
                const monAtt = await attendanceTransaction.findOne({
                  raw: true,
                  where: {
                    userMasterID: userMasterID,
                    AttendanceDate: after_date,
                    fulldayhalfday: 1,
                  },
                });

                if (monAtt) mon = true;
              } else {
                const monAtt = attendancedata.find(
                  (e) =>
                    e.AttendanceDate == after_date && +e.fulldayhalfday == 1
                );
                if (monAtt) mon = true;
              }
            }
            // check branch wise

            if ([427, 430, 433].includes(branchId)) {
              if (sun == true && sat == true && mon == true)
                sundaydoubleCount++;
            }

            if ([432, 2553].includes(branchId)) {
              if (sun == true && sat == true) sundaydoubleCount++;
            }
          }
        }
      }

      // holiday double salary

      const holiday = await weekoffHolidayTran.findAll({
        raw: true,
        where: {
          userMasterID: userMasterID,
          date: {
            [Sequelize.Op.between]: [start_date, end_date],
          },
          tableName: 'holiday',
          [Sequelize.Op.or]: [
            { optionalHoliday: false },
            { optionalHoliday: null },
          ],
        },
      });

      const holidaydates = holiday.map((e) => e.date);

      const holiday_presentday = attendancedata
        .filter((obj) => holidaydates.includes(obj.AttendanceDate))
        .reduce((acc, obj) => acc + +obj.fulldayhalfday, 0);

      sundaydoubleCount += +holiday_presentday;

      const salary = await getUserSalaryMasterByMonth(userMasterID, month);

      const gross =
        [...salary].find((e) => e.payheadMasterId == 50)
          ?.EmployeeSalaryAmount || 0;

      const daysinmonth = daysInMonth(
        month.toString().slice(4, 6),
        month.toString().slice(0, 4)
      );

      const incentiveAmount = (+gross / +daysinmonth) * +sundaydoubleCount;

      if (+incentiveAmount > 0) {
        await Employeeincentive.create(
          {
            userMasterID: userMasterID,
            yearmonth: +month,
            amount: Math.round(+incentiveAmount),
            incentiveDate: end_date,
            IncentivetypeID: 159, // add incentive id
            createBy: createBy,
            createByIp: createByIp,
          },
          { transaction: t }
        );
      }
    });
  }
}

