async function incomeTaxCalculationByUserId(userId, financialYear) {
  const yearRange = financialYear.split('-');
  const currentFinancialYear = yearRange[0];

  const startDate = yearRange[0] + '-' + '04' + '-' + '01';
  const endDate = yearRange[1] + '-' + '03' + '-' + '31';

  let startMonth = yearRange[0] + '04';
  let endMonth = yearRange[1] + '03';

  async function taxAmountZero() {
    const data = [];
    for (let i = 0; i < financialMonths.length; i++) {
      const year = i < 9 ? currentFinancialYear : +currentFinancialYear + 1;
      const month =
        norMonths.indexOf(financialMonths[i]) + 1 < 10
          ? '0' + (norMonths.indexOf(financialMonths[i]) + 1)
          : norMonths.indexOf(financialMonths[i]) + 1;
      data.push({
        yearMonth: year + String(month),
        month: financialMonths[i] + ' ' + year,
        amount: 0,
        edit: false,
      });
    }
    return data;
  }

  const salaryStructure = await HRSalaryMasterFields.findOne({
    where: {
      userMasterID: userId,
    },
  });

  let finalData = [],
    salaryMasterdata = [],
    salarydata = [],
    previousSalaryData = [],
    manualIncomeTaxYearMonth = [],
    toCalculateSalaryData = [],
    toCalculateSalaryMasterData = [],
    toCalcultePreviousSalaryData = [],
    incometaxPayableAmount = 0,
    incomeTaxRemainingAmount = 0,
    paidAmount = 0,
    showpreviousMonth;

  if (!salaryStructure) {
    finalData = await taxAmountZero();
  } else {
    const joining = await EmployeeJoiningDetails.findOne({
      raw: true,
      where: {
        userMasterID: userId,
      },
      include: [{ model: UserMaster, attributes: ['gender'] }],
    });

    if (!joining) {
      finalData = await taxAmountZero();
      return {
        data: finalData,
      };
    }

    // if joining Date is greater than endDate

    if (new Date(joining.joiningDate) > new Date(endDate)) {
      finalData = await taxAmountZero();
      return {
        data: finalData,
      };
    }
    // if joining Date occures in selected financial year
    else if (
      new Date(joining.joiningDate) >= new Date(startDate) &&
      new Date(joining.joiningDate) <= new Date(endDate)
    ) {
      startMonth =
        joining.joiningDate.slice(0, 4) + joining.joiningDate.slice(5, 7);

      if (
        joining.leavingDate &&
        new Date(joining.leavingDate) <= new Date(endDate)
      ) {
        endMonth =
          joining.leavingDate.slice(0, 4) + joining.leavingDate.slice(5, 7);
      }

      salaryMasterdata = await getAllSalaryMasterByRange(
        userId,
        startMonth,
        endMonth
      );
      salarydata = await getAllSalaryDataByRange(userId, startMonth, endMonth);

      previousSalaryData = await getPreviousSalaryByMonthRange(
        userId,
        startMonth,
        endMonth
      );
    }
    // if joining Date is before selected financial Year
    else {
      if (
        joining.leavingDate &&
        new Date(joining.leavingDate) <= new Date(endDate)
      ) {
        endMonth =
          joining.leavingDate.slice(0, 4) + joining.leavingDate.slice(5, 7);
      }

      salaryMasterdata = await getAllSalaryMasterByRange(
        userId,
        startMonth,
        endMonth
      );
      salarydata = await getAllSalaryDataByRange(userId, startMonth, endMonth);

      previousSalaryData = await getPreviousSalaryByMonthRange(
        userId,
        startMonth,
        endMonth
      );
    }

    // calculate for salaryMaster

    const calculatedSalaryMaster =
      toCalculatesalaryMasterData(salaryMasterdata);

    // Calculate gross salary excluding professional tax (PT)

    const grossWithOutPT =
      +calculatedSalaryMaster.salaryMasterGross -
      +calculatedSalaryMaster.ptAmount;

    const totalLeaveEncash = +calculatedSalaryMaster.leaveEncash;
    const totalLTA = +calculatedSalaryMaster.LTA;

    const todayDate = asiaKolkataDateTime(new Date()).slice(0, 10);

    const salaryPolicy = await employeeSalaryPolicy(userId, todayDate);
    // to get Previous Month Salary Cycle Date
    const priviousSalaryCycleDates = await getPreviousMonthSalaryCycleDate(
      todayDate,
      salaryPolicy
    );
    // previous salary cycle Month
    const previousMonth =
      priviousSalaryCycleDates.previousSalaryCycleStartDate.slice(0, 4) +
      priviousSalaryCycleDates.previousSalaryCycleStartDate.slice(5, 7);

    // send previousMonth in response
    showpreviousMonth = previousMonth;

    // to get previous month's financial year
    const getPreviousMonth_FinancialYear =
      await getFinancialYearByMonth(previousMonth);

    // to merge financial years ex. 20232024

    const previousyear = getPreviousMonth_FinancialYear.split('-').join('');
    const selectedyear = financialYear.split('-').join('');

    // get All months of selected financial Year
    const getAllMonths = await getYearMonthByRange(startMonth, endMonth);
    // set flag to push previous month's incomeTax in finalData
    let topushData = false;

    // if previous month financial year and requested financial year are same
    if (+previousyear == +selectedyear) {
      let incomeTaxDeductedAmount = 0,
        previousManualTaxData = 0;

      // get All Manual IncomeTax Declaration

      const manualTaxdata = await manualIncomeTaxdeduction.findAll({
        raw: true,
        where: {
          userMasterID: userId,
          yearMonth: {
            [Sequelize.Op.in]: getAllMonths,
          },
        },
        include: [
          {
            model: UserMaster,
            as: 'manualIncomeTaxdeductionCreatedBy',
            attributes: ['displayName'],
          },
        ],
      });

      // push incomeTax Amount in finalData which is already Calculated
      for (const data of getAllMonths) {
        let incomeTaxAmount = 0,
          toEdit = true,
          createdName = '';
        const month = data.toString().slice(4, 6);
        const year = data.toString().slice(0, 4);
        //check month is less than or equal to previous Month
        if (+data <= +previousMonth) {
          // find salary data of particular month
          const salary = salarydata.find((e) => e.month == data);

          if (data == previousMonth) {
            //if previous month's salary not calculated
            if (salary && salary.salaryData.length == 0) {
              // check previous salary is available or not

              const previousSalary = previousSalaryData.filter(
                (e) => e.yearMonth == data
              );

              // if previous salary is not available
              if (previousSalary.length === 0) {
                const salaryMaster = salaryMasterdata.find(
                  (e) => e.month == data
                );
                if (salaryMaster) {
                  (topushData = true),
                    manualIncomeTaxYearMonth.push(data),
                    toCalculateSalaryMasterData.push(salaryMaster);
                  continue;
                }
              } else {
                // For Edit
                toEdit = false;
              }
            }
          }

          // if salary is available
          if (salary) {
            if (salary.salaryData.length == 0) {
              // check previous salary is available or not
              const previousSalary = previousSalaryData.filter(
                (e) => e.yearMonth == data
              );

              if (previousSalary.length > 0) {
                toEdit = false; // Edit Logic
                toCalcultePreviousSalaryData.push(previousSalary);
                const tdsData = previousSalary.find(
                  (e) => e.payheadMasterId == 9
                );
                if (tdsData) {
                  incomeTaxAmount = +tdsData.amount;
                }
              } else {
                // check manual TDS Amount
                const manualData = manualTaxdata.find(
                  (e) => e.yearMonth == data
                );
                if (manualData) {
                  previousManualTaxData += +manualData.amount;
                  incomeTaxAmount = +manualData.amount;
                  createdName =
                    manualData['manualIncomeTaxdeductionCreatedBy.displayName'];
                }
                manualIncomeTaxYearMonth.push(data),
                  toCalculateSalaryData.push(salary);
              }
            } else {
              toEdit = false; // Edit Logic
              toCalculateSalaryData.push(salary);
              const tdsData = salary.salaryData.find(
                (e) => e.payheadMasterId == 9
              );
              if (tdsData) incomeTaxAmount = +tdsData.EmployeeSalaryAmount;
            }
          }
          incomeTaxDeductedAmount += !toEdit ? incomeTaxAmount : 0;
          finalData.push({
            yearMonth: data,
            month: norMonths[+month - 1] + ' ' + year,
            amount: showAmount(incomeTaxAmount),
            edit: toEdit,
            changeBy: createdName,
          });
        } else {
          const salaryMaster = salaryMasterdata.find((e) => e.month == data);
          if (salaryMaster)
            toCalculateSalaryMasterData.push(salaryMaster),
              manualIncomeTaxYearMonth.push(data);
          continue;
        }
      }

      const priviousCalculatedSalary = toCalculateEmployeeSalaryData(
        toCalculateSalaryData
      );
      const futureSalaryMasterAmount = toCalculatesalaryMasterData(
        toCalculateSalaryMasterData
      );

      const previousUploadedSalary = toCalculatePreviousUploadedSalary(
        toCalcultePreviousSalaryData
      );

      const totalLeaveEncash =
        +priviousCalculatedSalary.leaveEncash +
        +futureSalaryMasterAmount.leaveEncash +
        +previousUploadedSalary.leaveEncash;
      const totalLTA =
        +priviousCalculatedSalary.LTA +
        +futureSalaryMasterAmount.LTA +
        +previousUploadedSalary.LTA;

      // employee Declaration data

      const employeeDeclarationAmount = await getEmployeeDeclarationAmount(
        userId,
        financialYear,
        totalLeaveEncash,
        totalLTA
      );

      // Amount to calculate incomeTax
      let taxableAmount =
        +priviousCalculatedSalary.salaryGross -
        +priviousCalculatedSalary.PtAmount +
        (+previousUploadedSalary.salaryGross -
          +previousUploadedSalary.ptAmount) +
        (+futureSalaryMasterAmount.salaryMasterGross -
          +futureSalaryMasterAmount.ptAmount) -
        +employeeDeclarationAmount;

      // find employee regime

      const employeeRegime = await EmployeeTaxRegime.findOne({
        raw: true,
        where: {
          userMasterID: userId,
          financialYear: financialYear,
        },
      });

      const regime = employeeRegime ? employeeRegime.regime : 'New Regime';

      const condition = {
        financialYear,
        regime,
      };

      const [taxRebate, taxStandardDeduction] = await Promise.all([
        TaxRebate.findOne({
          where: condition,
        }),
        TaxStandardDeduction.findOne({
          where: condition,
        }),
      ]);

      // standard deductions

      if (taxStandardDeduction) taxableAmount -= +taxStandardDeduction.amount;

      let { incomeTaxAmount: totalIncomeTaxAmount, marginalReliefAmt } =
        await incomeTaxCalculationByRegime(
          taxableAmount,
          joining['userMaster.gender'],
          financialYear,
          regime,
          'cal',
          +taxRebate?.amount || 0
        );

      //  incometax rebate u/s 87A

      if (taxRebate && +taxRebate.amount >= +totalIncomeTaxAmount)
        totalIncomeTaxAmount = 0;

      // -----------------------whichever is less condition (marginalrelief amount or totalIncomeTaxAmount) ----------------------------------

      // check condition for applicable
      // marginalrelief applicable from 2025-2026 and in only new regime

      if (
        regime == 'New Regime' &&
        +String(financialYear).slice(0, 4) >= 2025
      ) {
        // set min condtion

        const ExtraAmount =
          +taxableAmount - +marginalReliefAmt > 0
            ? +taxableAmount - +marginalReliefAmt
            : 0;

        totalIncomeTaxAmount =
          ExtraAmount && totalIncomeTaxAmount
            ? Math.min(totalIncomeTaxAmount, ExtraAmount)
            : totalIncomeTaxAmount;
      }

      // CESS 4% on income tax Data --------------------------------------------
      totalIncomeTaxAmount += (+totalIncomeTaxAmount * 4) / 100;

      // current financial year amount
      incometaxPayableAmount = +totalIncomeTaxAmount;
      incomeTaxRemainingAmount =
        +totalIncomeTaxAmount - +incomeTaxDeductedAmount;
      paidAmount = +incomeTaxDeductedAmount;

      const monthData = manualTaxdata.filter((e) =>
        topushData
          ? +e.yearMonth >= +previousMonth
          : +e.yearMonth > +previousMonth
      );

      const totalmanualAmount = monthData.reduce(
        (acc, obj) => acc + +obj.amount,
        0
      );

      // per Month incomeTaxAmount
      const perMonthAmount =
        (+totalIncomeTaxAmount -
          +incomeTaxDeductedAmount -
          +previousManualTaxData -
          +totalmanualAmount) /
        (toCalculateSalaryMasterData.length - monthData.length);

      // push remaining month's incomeTax Amount in finalData
      for (const data of getAllMonths) {
        // if month is previous months greater than or equal to
        if (+data >= +previousMonth) {
          if (+data == +previousMonth) {
            // check flag for salary calculated or not
            if (!topushData) continue;
          }

          const month = data.toString().slice(4, 6);
          const year = data.toString().slice(0, 4);
          let createdName = '';
          const findMonthlytaxdata = manualTaxdata.find(
            (e) => e.yearMonth == data
          );
          if (findMonthlytaxdata)
            createdName =
              findMonthlytaxdata[
                'manualIncomeTaxdeductionCreatedBy.displayName'
              ];

          finalData.push({
            yearMonth: data,
            month: norMonths[+month - 1] + ' ' + year,
            amount: findMonthlytaxdata
              ? showAmount(+findMonthlytaxdata.amount)
              : showAmount(perMonthAmount),
            edit: data == getAllMonths[getAllMonths.length - 1] ? false : true,
            changeBy: createdName,
          });
        }
      }
    } else if (+previousyear > +selectedyear) {
      for (const data of getAllMonths) {
        let incomeTaxAmount = 0;
        // find salary data of paricular month
        const salary = salarydata.find((e) => e.month == data);
        // add data for salarydata
        //------------------------- toCalculateSalaryData = salarydata;----------------
        // if salary is available
        if (salary) {
          // salary not calculated
          if (salary.salaryData.length === 0) {
            // check previous salary is available or not

            const previousSalary = previousSalaryData.filter(
              (e) => e.yearMonth == data
            );

            if (previousSalary.length > 0) {
              toCalcultePreviousSalaryData.push(previousSalary);
              const tdsData = previousSalary.find(
                (e) => e.payheadMasterId == 9
              );
              if (tdsData) {
                incomeTaxAmount = +tdsData.amount;
              }
            } else {
              toCalculateSalaryData.push(salary);
            }
          } else {
            toCalculateSalaryData.push(salary);
            const tdsData = salary.salaryData.find(
              (e) => e.payheadMasterId == 9
            );
            if (tdsData) incomeTaxAmount = +tdsData.EmployeeSalaryAmount;
          }
        }
        const month = data.toString().slice(4, 6);
        const year = data.toString().slice(0, 4);
        //sum of payableAmount
        incometaxPayableAmount += incomeTaxAmount;
        paidAmount += incomeTaxAmount;

        finalData.push({
          yearMonth: data,
          month: norMonths[+month - 1] + ' ' + year,
          amount: showAmount(+incomeTaxAmount),
          edit: false,
        });
      }
    } else {
      //if future selected financial Year
      // to send data in response
      toCalculateSalaryMasterData = salaryMasterdata;
      // employee Declaration data
      const employeeDeclarationAmount = await getEmployeeDeclarationAmount(
        userId,
        financialYear,
        totalLeaveEncash,
        totalLTA
      );

      // set taxable amount
      let taxableAmount = grossWithOutPT;

      // substract Employee Declaration Amount
      if (employeeDeclarationAmount)
        taxableAmount -= +employeeDeclarationAmount;

      // find employee regime
      const employeeRegime = await EmployeeTaxRegime.findOne({
        raw: true,
        where: {
          userMasterID: userId,
          financialYear: financialYear,
        },
      });

      // if employee regime is not set it calculte as a New Regime
      const regime = employeeRegime ? employeeRegime.regime : 'New Regime';

      const condition = {
        financialYear,
        regime,
      };

      const [taxRebate, taxStandardDeduction] = await Promise.all([
        TaxRebate.findOne({
          where: condition,
        }),
        TaxStandardDeduction.findOne({
          where: condition,
        }),
      ]);

      // substract Standard Deduction Amount
      if (taxStandardDeduction) taxableAmount -= +taxStandardDeduction.amount;

      let { incomeTaxAmount: finalTotalIncomeTaxAmount, marginalReliefAmt } =
        await incomeTaxCalculationByRegime(
          +taxableAmount,
          joining['userMaster.gender'],
          financialYear,
          regime,
          'cal',
          +taxRebate?.amount || 0
        );

      //  incometax rebate u/s 87A
      if (taxRebate && +taxRebate.amount >= +finalTotalIncomeTaxAmount)
        finalTotalIncomeTaxAmount = 0;

      // -----------------------whichever is less condition (marginalrelief amount or totalIncomeTaxAmount) ----------------------------------

      // check condition for applicable
      // marginalrelief applicable from 2025-2026 and in only new regime

      if (
        regime == 'New Regime' &&
        +String(financialYear).slice(0, 4) >= 2025
      ) {
        // set min condtion

        const ExtraAmount =
          +taxableAmount - +marginalReliefAmt > 0
            ? +taxableAmount - +marginalReliefAmt
            : 0;

        finalTotalIncomeTaxAmount =
          ExtraAmount && finalTotalIncomeTaxAmount
            ? Math.min(finalTotalIncomeTaxAmount, ExtraAmount)
            : finalTotalIncomeTaxAmount;
      }

      // CESS 4% on income tax Data --------------------------------------------
      finalTotalIncomeTaxAmount += (+finalTotalIncomeTaxAmount * 4) / 100;

      // for future all amount is pending
      incometaxPayableAmount = +finalTotalIncomeTaxAmount;
      incomeTaxRemainingAmount = +finalTotalIncomeTaxAmount;

      // all months of future financialyear
      manualIncomeTaxYearMonth = salaryMasterdata.map((e) => e.month);
      // FIND EMPLOYEES MANUAL TAX
      const manualTaxdata = await manualIncomeTaxdeduction.findAll({
        raw: true,
        where: {
          userMasterID: userId,
          yearMonth: {
            [Sequelize.Op.in]: manualIncomeTaxYearMonth,
          },
        },
        include: [
          {
            model: UserMaster,
            as: 'manualIncomeTaxdeductionCreatedBy',
            attributes: ['displayName'],
          },
        ],
      });
      // TOTAL MANUAL TAX
      const totalmanualAmount = manualTaxdata.reduce(
        (acc, obj) => acc + +obj.amount,
        0
      );

      // PER MONTH TAX
      const perMonthIncomeTax =
        (finalTotalIncomeTaxAmount - +totalmanualAmount) /
        (salaryMasterdata.length > 0
          ? +salaryMasterdata.length - manualTaxdata.length
          : 1);

      for (const data of salaryMasterdata) {
        const month = data.month.toString().slice(4, 6);
        const year = data.month.toString().slice(0, 4);
        // find manual data of particular month
        const findMonthlytaxdata = manualTaxdata.find(
          (e) => e.yearMonth == data.month
        );
        let createdName = '';
        if (findMonthlytaxdata)
          createdName =
            findMonthlytaxdata['manualIncomeTaxdeductionCreatedBy.displayName'];

        finalData.push({
          yearMonth: data.month,
          month: norMonths[+month - 1] + ' ' + year,
          amount: findMonthlytaxdata
            ? showAmount(+findMonthlytaxdata.amount)
            : showAmount(perMonthIncomeTax),
          edit:
            data.month == salaryMasterdata[salaryMasterdata.length - 1].month
              ? false
              : true,
          changeBy: createdName,
        });
      }
    }
  }

  return {
    data: finalData,
    payableAmount: showAmount(+incometaxPayableAmount),
    remainingAmount: showAmount(+incomeTaxRemainingAmount),
    paidAmount: showAmount(+paidAmount),
    previousMonth: showpreviousMonth,
    previousSalary: toCalculateSalaryData,
    futureSalary: toCalculateSalaryMasterData,
    previousUploadedSalary: toCalcultePreviousSalaryData,
  };
}

const convert12H24HTime = (time) => moment(time, 'h:mm A').format('HH:mm');

const generateCronExpression = (time, date) => {
  const [hour, minute] = time.split(':');
  return `${minute} ${hour} * * *`;
};

const modifyTime = (timeString, number, timeType, timeFormat) => {
  // Parse the time string using moment
  let time = moment(timeString, 'hh:mm A');
  // Modify the time based on timeType and timeFormat
  if (timeType === 'before') {
    time.subtract(number, timeFormat);
  } else if (timeType === 'after') {
    time.add(number, timeFormat);
  }
  // Update the time in the object
  time = time.format('hh:mm A');
  return time;
};

const sendBulkNotification = async (tokens, payload, deviceType) => {
  try {
    const admin =
      deviceType === 'ios' ? iosFirebaseAdmin : androidFirebaseAdmin;

    // Split tokens into chunks of 500
    const tokenChunks = [];
    for (let i = 0; i < tokens.length; i += 500) {
      tokenChunks.push(tokens.slice(i, i + 500));
    }

    // Send notifications for each chunk concurrently
    const responses = await Promise.all(
      tokenChunks.map(async (chunk) =>
        admin.messaging().sendEachForMulticast({
          tokens: chunk,
          notification: payload.notification,
        })
      )
    );
    return;
  } catch (error) {
    throw new Error(error);
  }
};
const norMonths = [
  'Jan',
  'Feb',
  'Mar',
  'Apr',
  'May',
  'Jun',
  'Jul',
  'Aug',
  'Sep',
  'Oct',
  'Nov',
  'Dec',
];

async function incomeTaxCalculationandComputation(userId, financialYear) {
  // FOR INCOME TAX COMPUTATION ----------------------------------------------------------------

  const data = await incomeTaxCalculationByUserId(userId, financialYear);

  const toCalculateSalaryData = data.previousSalary || [];
  const toCalculateSalaryMasterData = data.futureSalary || [];

  const toCalculateUploadedSalaryData = data.previousUploadedSalary
    ? data.previousUploadedSalary
    : [];

  const monthlyDeductionData = [];
  let totalDeduction = 0;
  // previous gross salary
  const previousGrossArray = toCalculateSalaryData.map((e) => {
    let monthlydeduction = 0;
    const data = e.salaryData.filter((s) => {
      if (![1, 50, 92].includes(s.payheadMasterId)) {
        if (
          s.salaryFieldSrNo == 'A' &&
          (s.considerIn != 'net' || s.consider == 'gross')
        ) {
          return s;
        } else if (s.payheadMasterId == 15) {
          totalDeduction += +s.EmployeeSalaryAmount;
          monthlydeduction += +s.EmployeeSalaryAmount;
        }
      }
    });

    monthlyDeductionData.push({
      month:
        norMonths[+String(e.month).slice(4, 6) - 1] +
        ' ' +
        String(e.month).slice(0, 4),
      amount: monthlydeduction,
    });
    return {
      month: e.month,
      salaryData: data,
      projectedSalary: false,
    };
  });
  // future gross salary
  const futureGrossArray = toCalculateSalaryMasterData.map((e) => {
    const data = e.salaryData.filter(
      (s) =>
        s.salaryFieldSrNo == 'A' &&
        ![1, 50, 92].includes(s.payheadMasterId) &&
        s.considerIn != 'net'
    );

    // for deduction data
    const monthlyDeductionAmount =
      e.salaryData.find((s) => s.payheadMasterId == 15)?.EmployeeSalaryAmount ||
      0;

    totalDeduction += +monthlyDeductionAmount;
    monthlyDeductionData.push({
      month:
        norMonths[+String(e.month).slice(4, 6) - 1] +
        ' ' +
        String(e.month).slice(0, 4),
      amount: monthlyDeductionAmount,
    });
    return {
      month: e.month,
      salaryData: data,
      projectedSalary: true,
    };
  });

  // uploaded previous salary
  const previousUploadedGrossArray = toCalculateUploadedSalaryData.map((e) => {
    let monthlydeduction = 0;
    const data = e.filter((s) => {
      if (
        s.salaryFieldSrNo == 'A' &&
        ![1, 50, 92].includes(s.payheadMasterId)
      ) {
        s['EmployeeSalaryAmount'] = +s.amount;
        s['payheadName'] = s['Payheadmaster.payheadName'];

        return s;
      } else if (
        // only for pt
        s.payheadMasterId == 15
      ) {
        totalDeduction += +s.amount;
        monthlydeduction += +s.amount;
      }
    });
    monthlyDeductionData.push({
      month:
        norMonths[+String(e[0].yearMonth).slice(4, 6) - 1] +
        ' ' +
        String(e[0].yearMonth).slice(0, 4),
      amount: monthlydeduction,
    });
    return {
      month: e[0].yearMonth,
      salaryData: data,
      projectedSalary: false,
    };
  });

  // Function to parse month and year
  const parseMonthYear = (monthYear) => {
    const [month, year] = monthYear.split(' ');
    return { month, year: parseInt(year) };
  };

  // Sorting monthlyDeductionData by month
  monthlyDeductionData.sort((a, b) => {
    const dateA = parseMonthYear(a.month);
    const dateB = parseMonthYear(b.month);

    if (dateA.year !== dateB.year) {
      return dateA.year - dateB.year;
    } else {
      const months = {
        Jan: 1,
        Feb: 2,
        Mar: 3,
        Apr: 4,
        May: 5,
        Jun: 6,
        Jul: 7,
        Aug: 8,
        Sep: 9,
        Oct: 10,
        Nov: 11,
        Dec: 12,
      };
      return months[dateA.month] - months[dateB.month];
    }
  });

  const allSalary = [
    ...previousGrossArray,
    ...futureGrossArray,
    ...previousUploadedGrossArray,
  ];
  // to set data in ascending order by month
  allSalary.sort((a, b) => a.month - b.month);

  // for final Net Pay Received
  const prevoiusSalary = toCalculateEmployeeSalaryData(toCalculateSalaryData);
  const futureSalary = toCalculatesalaryMasterData(toCalculateSalaryMasterData);

  const uploadedSalary = toCalculatePreviousUploadedSalary(
    toCalculateUploadedSalaryData
  );

  // Amount to calculate incomeTax

  const finalNetPayReceived =
    +prevoiusSalary.salaryGross -
    +prevoiusSalary.PtAmount +
    (+uploadedSalary.salaryGross - +uploadedSalary.ptAmount) +
    (+futureSalary.salaryMasterGross - +futureSalary.ptAmount);

  const totalLeaveEncash =
    +prevoiusSalary.leaveEncash +
    +futureSalary.leaveEncash +
    +uploadedSalary.leaveEncash;
  const totalLTA =
    +prevoiusSalary.LTA + +futureSalary.LTA + +uploadedSalary.LTA;

  const declarationAmount = await getEmployeeDeclarationAmount(
    userId,
    financialYear,
    totalLeaveEncash,
    totalLTA
  );

  // deducted declaration amount

  let taxableAmount = +finalNetPayReceived - +declarationAmount;

  const userRegime = await EmployeeTaxRegime.findOne({
    raw: true,
    where: {
      userMasterID: userId,
      financialYear: financialYear,
    },
    include: [{ model: UserMaster, attributes: ['gender'] }],
  });

  const regime = userRegime ? userRegime.regime : 'New Regime';

  const condition = {
    financialYear,
    regime,
  };

  const [taxRebate, taxStandardDeduction] = await Promise.all([
    TaxRebate.findOne({
      where: condition,
    }),
    TaxStandardDeduction.findOne({
      where: condition,
    }),
  ]);

  // standard deductions

  if (taxStandardDeduction) taxableAmount -= +taxStandardDeduction.amount;

  const slabsWithAmount = await incomeTaxCalculationByRegime(
    taxableAmount,
    userRegime ? userRegime['userMaster.gender'] : 'Male',
    financialYear,
    regime,
    'computation',
    +taxRebate?.amount || 0
  );

  // marginal relief amount
  const marginalReliefAmt = slabsWithAmount.marginalReliefAmt;

  const rebate =
    taxRebate && taxRebate.amount >= +slabsWithAmount.incomeTaxAmount
      ? +slabsWithAmount.incomeTaxAmount
      : 0;

  let grossIncomeTax = +slabsWithAmount.incomeTaxAmount - +rebate;

  // -----------------------whichever is less condition (marginalrelief amount or totalIncomeTaxAmount) ----------------------------------

  // check condition for applicable
  // marginalrelief applicable from 2025-2026 and in only new regime

  if (regime == 'New Regime' && +String(financialYear).slice(0, 4) >= 2025) {
    // set min condtion

    const ExtraAmount =
      +taxableAmount - +marginalReliefAmt > 0
        ? +taxableAmount - +marginalReliefAmt
        : 0;

    grossIncomeTax =
      ExtraAmount && grossIncomeTax
        ? Math.min(grossIncomeTax, ExtraAmount)
        : grossIncomeTax;
  }

  const cess = (grossIncomeTax * 4) / 100;

  const result = {};

  // // Loop through each salary data
  allSalary.forEach(({ salaryData }) => {
    // Loop through each payheadName in salary data
    salaryData.forEach(({ payheadName, EmployeeSalaryAmount, month }) => {
      // If the payheadName doesn't exist in result, initialize it
      if (!result[payheadName]) {
        result[payheadName] = {
          total: 0,
          months: {},
        };
      }

      // Update total
      result[payheadName].total += +EmployeeSalaryAmount;

      // Update months
      result[payheadName].months[month] = +EmployeeSalaryAmount;
    });
  });

  // Initialize an array to store the final formatted data
  const formattedData = [];

  let lastTotal = 0;
  const insertLastRow = {
    payheadName: 'Total Earnings',
    total: 0,
    monthlyData: [],
  };

  // Loop through each payhead in result
  for (const payheadName in result) {
    const payheadInfo = result[payheadName];
    const payheadObj = {
      payheadName,
      total: payheadInfo.total,
      monthlyData: [],
    };

    // Loop through all months and set the value for each payhead
    allSalary.forEach((salary) => {
      payheadObj.monthlyData.push({
        month:
          norMonths[+String(salary.month).slice(4, 6) - 1] +
          ' ' +
          String(salary.month).slice(0, 4),
        amount: salary.salaryData.find((e) => e.payheadName == payheadName)
          ? salary.salaryData.find((e) => e.payheadName == payheadName)
              .EmployeeSalaryAmount
          : 0,
        projectedSalary: salary.projectedSalary,
      });
    });

    // Push the payhead object to the formattedData array
    formattedData.push(payheadObj);
  }

  allSalary.map((salary) => {
    const totalMonthlySalary = salary.salaryData.reduce(
      (acc, obj) => acc + +obj.EmployeeSalaryAmount,
      0
    );
    lastTotal += +totalMonthlySalary;

    insertLastRow.monthlyData.push({
      month:
        norMonths[+String(salary.month).slice(4, 6) - 1] +
        ' ' +
        String(salary.month).slice(0, 4),
      amount: totalMonthlySalary,
    });
  });
  insertLastRow.total = +lastTotal;

  formattedData.push(insertLastRow);
  // add projected salary
  data.data.map((e) => {
    const salarydata = formattedData[0].monthlyData.find(
      (f) => f.month == e.month
    );
    e.projectedSalary = salarydata ? salarydata.projectedSalary : false;
  });

  return {
    data: data.data,
    payableAmount: showAmount(+data.payableAmount),
    remainingAmount: showAmount(+data.remainingAmount),
    paidAmount: showAmount(+data.paidAmount),
    previousMonth: data.previousMonth,
    finalData: formattedData,
    deductionData: monthlyDeductionData,
    totalDeductionAmount: totalDeduction,
    declarationAmount: declarationAmount,
    finalNetPayReceived: finalNetPayReceived,
    taxableAmount: taxableAmount,
    slabs: slabsWithAmount,
    rebate: showAmount(rebate),
    cess: showAmount(+cess),
    grossIncomeTaxAmount: grossIncomeTax,
    netIncomeTaxPayable: showAmount(+grossIncomeTax + +cess),
    rebateUpto: taxRebate && taxRebate.amount ? +taxRebate.amount : 0,
    standardDeduction:
      taxStandardDeduction && taxStandardDeduction.amount
        ? +taxStandardDeduction.amount
        : 0,
  };
}

function minutesToHoursMinutes(minutes) {
  var hours = Math.floor(minutes / 60);
  var remainingMinutes = minutes % 60;
  return (
    (+hours < 10 ? '0' : '') +
    hours +
    ':' +
    (+remainingMinutes < 10 ? '0' : '') +
    remainingMinutes
  );
}

const toGetFormateddate = (date) => {
  if (!date) return '';
  const datetime = asiaKolkataDateTime(date);
  return (
    datetime.slice(0, 10).split('-').reverse().join('-') +
    '' +
    datetime.slice(10)
  );
};

function getTimeHHMMSSFormat(inputTime) {
  const indianTime = new Date(inputTime);
  indianTime.toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' });

  // Format the time to hh:mm:ss
  return `${(+indianTime.getHours() < 10 ? '0' : '') + indianTime.getHours()}:${
    (+indianTime.getMinutes() < 10 ? '0' : '') + indianTime.getMinutes()
  }:${(+indianTime.getSeconds() < 10 ? '0' : '') + indianTime.getSeconds()}`;
}

