async function getIncomeTaxDataforForm16Report(
  userId,
  financialYear,
  startMonth,
  endMonth,
  gender
) {
  // calculated salary data

  const salarydata = await getAllSalaryDataByRange(
    userId,
    startMonth,
    endMonth
  );

  // uploaded salary data

  const previousSalaryData = await getPreviousSalaryByMonthRange(
    userId,
    startMonth,
    endMonth
  );

  const toCalculateGrossSalary = [];
  let storedGross = 0,
    storedLeaveEncash = 0,
    storedLTA = 0;

  // combined all salary
  const allSalaryData = salarydata.map((e) => {
    if (e.salaryData.length === 0) {
      const findUploadSalary = previousSalaryData.filter(
        (p) => p.yearMonth == e.month
      );

      const findGross = findUploadSalary.find((g) => g.payheadMasterId == 50);

      storedLeaveEncash += +(
        findUploadSalary.find((g) => g.payheadMasterId == 67)?.amount || 0
      );
      storedLTA += +(
        findUploadSalary.find((g) => g.payheadMasterId == 20)?.amount || 0
      );

      findUploadSalary.map((f) => {
        f['EmployeeSalaryAmount'] = +f.amount;
        f['payheadName'] = f['Payheadmaster.payheadName'];
      });

      e.salaryData = findUploadSalary;

      if (findGross) storedGross += +findGross.amount;
    } else {
      toCalculateGrossSalary.push(e);
    }
    return e;
  });
  // combined all salary
  const allCalculatedSalary = toCalculateEmployeeSalaryData(
    toCalculateGrossSalary
  );

  const finalGross = (+allCalculatedSalary.salaryGross + +storedGross).toFixed(
    2
  );

  const totalLeaveEncash =
    +allCalculatedSalary.leaveEncash + +storedLeaveEncash;
  const totalLTA = +allCalculatedSalary.LTA + +storedLTA;

  // ------------------------- employee Declaration data ---------------------------------

  const years = String(financialYear).split('-');

  const applicableYYYYMM = years[1] + '03';

  const employeeDeclarationData = await employeeDeclaration.findAll({
    where: {
      assessmentYear: financialYear,
      userMasterID: userId,
      authStatus: 1, // get only Accepted declaration
    },
    include: [
      {
        model: tdsSubSection,
        attributes: [
          'tdsSubSectionCategoryID',
          'tdsSectionID',
          'tdsSubSectionID',
        ],
        include: [
          {
            model: TdsSubSectionLimit,
            where: {
              applicableYYYYMM: { [Sequelize.Op.lte]: +applicableYYYYMM },
            },
            attributes: ['maxLimit'],
            separate: true, // fetch in a separate query
            order: [['applicableYYYYMM', 'DESC']],
            limit: 1, // only the latest,
            required: false,
          },
        ],
      },
    ],
  });

  //   --------- function to calculate declaration amount ------------------------------

  function getAmountOfEmployeeDeclaration(employeeDeclarationData = [], id) {
    const amountdata = employeeDeclarationData
      .filter((e) => +e.tdsSubSection.tdsSectionID == +id)
      .reduce((acc, obj) => {
        const limit = obj.tdsSubSection.tdsSubSectionLimits?.[0]?.maxLimit;
        const declaration = +obj.declarationAmount;
        const amount = limit ? Math.min(declaration, +limit) : declaration;
        return acc + amount;
      }, 0);
    return amountdata ? +amountdata : 0;
  }

  //-------------find declared HRA ------------

  const declaredHRA = await getHRADeclarationByUserId(userId, financialYear);

  // calculate earning HRA

  const amountHRA1 = allSalaryData.reduce((acc, obj) => {
    const hra = obj.salaryData.find((s) => s.payheadMasterId == 3);
    if (hra) acc += +hra.EmployeeSalaryAmount;

    return acc;
  }, 0);

  //---------- basic = basic + D.A

  const basicsalary = allSalaryData.reduce((acc, obj) => {
    const basic = obj.salaryData.find((s) => s.payheadMasterId == 2);
    if (basic) acc += +basic.EmployeeSalaryAmount;
    // DA amount
    const da = obj.salaryData.find((s) => s.payheadMasterId == 35);
    if (da) acc += +da.EmployeeSalaryAmount;

    return acc;
  }, 0);

  // 50% of salary (for metro city) or 40% of salary (for non-metro city):

  let amountHRA2 = 0;

  for (const item of declaredHRA) {
    const range = await getYearMonthByRange(item.fromMonth, item.toMonth);

    const temp_amount = range.reduce((acc, e) => {
      const find_salary = allSalaryData.find((s) => s.month == e);
      if (find_salary) {
        acc += find_salary.salaryData
          .filter((f) => f.payheadMasterId == 2 || f.payheadMasterId == 35)
          .reduce((acc, obj) => acc + +obj.EmployeeSalaryAmount, 0);
      }
      return acc;
    }, 0);

    amountHRA2 +=
      item.city == 'metro'
        ? (temp_amount * 50) / 100
        : (temp_amount * 40) / 100;
  }

  // calculate declare HRA ----- Actual Rent Pay

  // Actual rent paid minus 10% of salary:

  const amountHRA3 =
    declaredHRA.reduce((acc, obj) => acc + +obj.amount, 0) -
    (basicsalary * 10) / 100;

  // declared Amount or earning HRA which one is lesser

  const e2 = Math.min(
    amountHRA1 < 0 ? 0 : +amountHRA1,
    amountHRA2 < 0 ? 0 : +amountHRA2,
    amountHRA3 < 0 ? 0 : +amountHRA3
  ).toFixed(2);

  //------------------------------------------------- under Section 10 declaration calculation ----------------------------------

  // -----------------------------------  Leave Travel Allowance 10(5) ---------------------

  const temp_a2 = getAmountOfEmployeeDeclaration(employeeDeclarationData, 28);

  // compare declared LTA and Earned LTA

  const a2 = Math.min(temp_a2, totalLTA).toFixed(2);

  // -------------------- Gratuity 10(10) ---------------------
  const b2 = getAmountOfEmployeeDeclaration(
    employeeDeclarationData,
    29
  ).toFixed(2);

  // -------------------- Leave Encashment 10(10AA) ---------------------
  const temp_d2 = getAmountOfEmployeeDeclaration(employeeDeclarationData, 30);

  // compare declared LTA and Earned LTA

  const d2 = Math.min(temp_d2, totalLeaveEncash).toFixed(2);

  // ------------------ Agricultural Income 10(1) --------------
  const agriculture_Income = getAmountOfEmployeeDeclaration(
    employeeDeclarationData,
    27
  );

  // -------- Tax Exemption for Educational and Medical Institutions 10(23C) ----------------
  const medicalInstituteAmount = getAmountOfEmployeeDeclaration(
    employeeDeclarationData,
    31
  );

  // -------- Food Allowance Declaration section 10(14)-----
  const foodAll = getAmountOfEmployeeDeclaration(employeeDeclarationData, 25);

  //--------------- section 10(14)(i) ------------
  const sumOfSection_10_14_i = getAmountOfEmployeeDeclaration(
    employeeDeclarationData,
    23
  );

  //--------------- section 10(14)(ii) ------------
  const sumOfSection_10_14_ii = getAmountOfEmployeeDeclaration(
    employeeDeclarationData,
    24
  );

  const g2 = (
    +foodAll +
    +sumOfSection_10_14_i +
    +sumOfSection_10_14_ii +
    +agriculture_Income +
    +medicalInstituteAmount
  ).toFixed(2);

  //  ---------------------- here h2 is sum of all allowance under section 10 ------------------
  const h2 = +a2 + +b2 + +d2 + +e2 + +g2;

  // Total amount of salary received from current employer

  const no3 = (+finalGross - +h2).toFixed(2);

  //-- employee regime
  const employeeRegime = await EmployeeTaxRegime.findOne({
    raw: true,
    where: {
      userMasterID: userId,
      financialYear: financialYear,
    },
  });

  const regime = employeeRegime ? employeeRegime.regime : 'New Regime';

  const condition = {
    financialYear,
    regime,
  };

  //standard deduction under section 16 and rebate

  const [taxRebate, taxStandardDeduction] = await Promise.all([
    TaxRebate.findOne({
      where: condition,
    }),
    TaxStandardDeduction.findOne({
      where: condition,
    }),
  ]);

  // standard deductions

  const a4 = taxStandardDeduction
    ? (+taxStandardDeduction.amount).toFixed(2)
    : 0;

  // calculate pt amount

  const ptAmount = allSalaryData.reduce((acc, obj) => {
    const pt = obj.salaryData.find((s) => s.payheadMasterId == 15);
    if (pt) acc += +pt.EmployeeSalaryAmount;

    return acc;
  }, 0);

  const c4 = (+ptAmount).toFixed(2);

  //Total amount of deductions under section 16 [4(a)+4(b)+4(c)]
  const no5 = (+a4 + +c4).toFixed(2);

  //Income chargeable under the head "Salaries" [(3+1(e)-5]

  const no6 = (+no3 - +no5).toFixed(2);

  // ------ Housing Loan Interest section 24(a) ----

  const housing_Loan_Interest = getAmountOfEmployeeDeclaration(
    employeeDeclarationData,
    26
  );

  const a7 =
    housing_Loan_Interest > 0 ? -housing_Loan_Interest.toFixed(2) : 0.0;

  const no8 = a7;

  // Gross total income (6+8)

  const no9 = (+no6 + +no8).toFixed(2);

  // Deductions under Chapter VI-A

  // find 1.5 lakhs category data

  // ----------- under section 80C----

  const amount = employeeDeclarationData
    .filter((e) => e.tdsSubSection.tdsSubSectionCategoryID == 1)
    .reduce((acc, obj) => acc + +obj.declarationAmount, 0);

  const a10_Gross = (150000).toFixed(2);
  const a10_Deduction =
    +amount > 150000 ? (150000).toFixed(2) : (+amount).toFixed(2);

  // --- under section 80CCC
  const b10_Deduction = +(+getAmountOfEmployeeDeclaration(
    employeeDeclarationData,
    3
  )).toFixed(2);

  // --- under section 80CCD(1)
  const c10_Deduction = +(+getAmountOfEmployeeDeclaration(
    employeeDeclarationData,
    4
  )).toFixed(2);

  const d10_Gross = (150000).toFixed(2);
  const d10_Deduction = (
    +a10_Deduction +
    +b10_Deduction +
    +c10_Deduction
  ).toFixed(2);

  //--- under section 80CCD (1B)

  const e10_Deduction = +(+getAmountOfEmployeeDeclaration(
    employeeDeclarationData,
    5
  )).toFixed(2);

  //--- under section 80CCD (2)

  const f10_Deduction = +(+getAmountOfEmployeeDeclaration(
    employeeDeclarationData,
    6
  )).toFixed(2);

  //--- Medical Insurance Premium  80D All-------

  const g10_Deduction = +(+getAmountOfEmployeeDeclaration(
    employeeDeclarationData,
    7
  )).toFixed(2);

  const g10_Gross = employeeDeclarationData
    .filter((e) => e.tdsSubSection.tdsSectionID == 7)
    .reduce(
      (acc, obj) =>
        acc + (+obj.tdsSubSection.tdsSubSectionLimits?.[0]?.maxLimit || 0),
      0
    );

  //--- Higher Education Loan  80E ---

  const find_80E = employeeDeclarationData.find((e) => e.tdsSubSectionID == 28);

  let h10_Deduction = 0;
  let h10_Gross = 0;

  if (find_80E) {
    h10_Deduction = find_80E.tdsSubSection.tdsSubSectionLimits?.[0]?.maxLimit
      ? +find_80E.declarationAmount >
        +find_80E.tdsSubSection.tdsSubSectionLimits?.[0]?.maxLimit
        ? +(+find_80E.tdsSubSection.tdsSubSectionLimits?.[0]?.maxLimit).toFixed(
            2
          )
        : +(+find_80E.declarationAmount).toFixed(2)
      : +(+find_80E.declarationAmount).toFixed(2);

    h10_Gross = +(
      +find_80E.tdsSubSection.tdsSubSectionLimits?.[0]?.maxLimit || 0
    ).toFixed(2);
  }

  // ---- Donations towards Social Causes (100% deduction without qualifying limit)

  const find_80G1 = employeeDeclarationData.find(
    (e) => e.tdsSubSectionID == 31
  );
  let deductionAmount = 0,
    qualifyingAmount = 0,
    grossAmount = 0;
  if (find_80G1) {
    grossAmount = +((+finalGross * 10) / 100).toFixed(2);
    deductionAmount += +(+find_80G1.declarationAmount).toFixed(2);
  }

  // ---- Donations towards Social Causes (50% deduction without qualifying limit)

  const find_80G2 = employeeDeclarationData.find(
    (e) => e.tdsSubSectionID == 32
  );

  if (find_80G2) {
    deductionAmount += +((+find_80G2.declarationAmount * 50) / 100).toFixed(2);
  }

  // ---- Donations towards Social Causes (100% deduction with qualifying limit)

  const find_80G3 = employeeDeclarationData.find(
    (e) => e.tdsSubSectionID == 33
  );

  if (find_80G3) {
    qualifyingAmount += +((+finalGross * 10) / 100).toFixed(2);
    deductionAmount +=
      (+finalGross * 10) / 100 > +find_80G3.declarationAmount
        ? +(+find_80G3.declarationAmount).toFixed(2)
        : +((+finalGross * 10) / 100).toFixed(2);
  }

  // ---- Donations towards Social Causes (50% deduction with qualifying limit)

  const find_80G4 = employeeDeclarationData.find(
    (e) => e.tdsSubSectionID == 34
  );

  if (find_80G4) {
    qualifyingAmount += +((+finalGross * 10) / 100).toFixed(2);
    deductionAmount +=
      ((+finalGross * 10) / 100) * 0.5 >
      (+find_80G4.declarationAmount * 50) / 100
        ? +((+find_80G4.declarationAmount * 50) / 100).toFixed(2)
        : +(((+finalGross * 10) / 100) * 0.5).toFixed(2);
  }

  //--- Savings account interest tax

  const find_80TTA = employeeDeclarationData.find(
    (e) => e.tdsSubSectionID == 39
  );

  let j10_Deduction = 0;
  let j10_Gross = 0;

  if (find_80TTA) {
    j10_Deduction = find_80TTA.tdsSubSection.tdsSubSectionLimits?.[0]?.maxLimit
      ? +find_80TTA.declarationAmount >
        +find_80TTA.tdsSubSection.tdsSubSectionLimits?.[0]?.maxLimit
        ? +(+find_80TTA.tdsSubSection.tdsSubSectionLimits?.[0]
            ?.maxLimit).toFixed(2)
        : +(+find_80TTA.declarationAmount).toFixed(2)
      : +(+find_80TTA.declarationAmount).toFixed(2);

    j10_Gross = +(+find_80TTA.tdsSubSection.tdsSubSectionLimits?.[0]
      ?.maxLimit).toFixed(2);
  }

  let l10_Deduction = 0;

  //  -------- section 80EEA -------

  l10_Deduction += +getAmountOfEmployeeDeclaration(employeeDeclarationData, 12);

  // ======= Section 80EEB --------------

  l10_Deduction += +getAmountOfEmployeeDeclaration(employeeDeclarationData, 13);

  // ------ Section 80DDB ------------

  l10_Deduction += +getAmountOfEmployeeDeclaration(employeeDeclarationData, 9);

  // ---  Aggregate of deductible amount under Chapter VI-A  [10(d)+10(e)+10(f)+10(g)+10(h)+10(i)+10(j)+10(l)]

  const no11 = +(
    +d10_Deduction +
    +e10_Deduction +
    +f10_Deduction +
    +g10_Deduction +
    +h10_Deduction +
    +deductionAmount +
    +j10_Deduction +
    +l10_Deduction
  ).toFixed(2);

  //----  Total taxable income (9-11)

  const totalTaxableIncome = (+no9 - +no11).toFixed(2);

  // -----------------------Tax Calculation ----------------------------

  let { incomeTaxAmount: taxOnTotalIncome, marginalReliefAmt } =
    await incomeTaxCalculationByRegime(
      totalTaxableIncome,
      gender,
      financialYear,
      regime,
      'cal',
      +taxRebate?.amount || 0
    );

  //  incometax rebate u/s 87A

  let rebate =
    taxRebate && +taxRebate.amount >= +taxOnTotalIncome ? +taxOnTotalIncome : 0;

  // -----------------------whichever is less condition (marginalrelief amount or totalIncomeTaxAmount) ----------------------------------

  // check condition for applicable
  // marginalrelief applicable from 2025-2026 and in only new regime

  if (regime == 'New Regime' && +String(financialYear).slice(0, 4) >= 2025) {
    // set min condtion

    const ExtraAmount =
      +totalTaxableIncome - +marginalReliefAmt > 0
        ? +totalTaxableIncome - +marginalReliefAmt
        : 0;

    taxOnTotalIncome =
      ExtraAmount && taxOnTotalIncome
        ? Math.min(taxOnTotalIncome, ExtraAmount)
        : taxOnTotalIncome;
  }

  // set to fixed

  taxOnTotalIncome = taxOnTotalIncome.toFixed(2);

  // Surcharge Rate

  // CESS 4% on income tax Data --------------------------------------------
  const cess = +rebate > 0 ? 0.0 : ((+taxOnTotalIncome * 4) / 100).toFixed(2);

  // ---- total tax Payable
  const totalTaxPayable = (+taxOnTotalIncome + +cess - +rebate).toFixed(2);

  // -- Net Tax Payable is also totalTaxPayable------

  return {
    finalGross,
    a2,
    b2,
    d2,
    e2,
    g2,
    h2,
    no3,
    a4,
    c4,
    no5,
    no6,
    a7,
    no8,
    no9,
    a10_Gross,
    a10_Deduction,
    b10_Deduction,
    c10_Deduction,
    d10_Gross,
    d10_Deduction,
    e10_Deduction,
    f10_Deduction,
    g10_Deduction,
    g10_Gross,
    h10_Deduction,
    h10_Gross,
    deductionAmount,
    qualifyingAmount,
    grossAmount,
    j10_Deduction,
    j10_Gross,
    l10_Deduction: +l10_Deduction.toFixed(2),
    no11,
    totalTaxableIncome,
    taxOnTotalIncome,
    rebate,
    cess,
    totalTaxPayable,
  };
}

async function getPreviousFy_year(date) {
  const date1 = new Date() || new Date(date);

  let year = date1.getFullYear();
  let month = date1.getMonth() + 1; // getMonth() returns month index starting from 0

  // Assuming the financial year starts in April
  if (month < 4) {
    year--; // If current month is before April, the financial year started last year
  }

  const currentFinancialYearStart = year;

  const previousFinancialYears = [];
  for (let i = 1; i <= 2; i++) {
    previousFinancialYears.push(
      `${currentFinancialYearStart - i}-${currentFinancialYearStart - i + 1}`
    );
  }

  return previousFinancialYears;
}

function accessibleUsers(
  userDetails,
  includeCompany = true,
  includeBranch = true
) {
  const condition = {};

  if (userDetails.accessibleBranches)
    userDetails.accessibleBranches = Array.isArray(
      userDetails.accessibleBranches
    )
      ? userDetails.accessibleBranches
      : [+userDetails.accessibleBranches];
  if (userDetails.accessibleCompanies)
    userDetails.accessibleCompanies = Array.isArray(
      userDetails.accessibleCompanies
    )
      ? userDetails.accessibleCompanies
      : [+userDetails.accessibleCompanies];
  if (
    userDetails.accessibleBranches &&
    userDetails.accessibleBranches.length &&
    includeBranch
  ) {
    condition.include = {
      model: EmployeeBranch,
      attributes: [],
      where: {
        status: 1,
        branchID: userDetails.accessibleBranches,
        applicableDate: { [Sequelize.Op.lte]: new Date() },
        [Sequelize.Op.or]: [
          { endDate: { [Sequelize.Op.gte]: new Date() } },
          { endDate: { [Sequelize.Op.eq]: null } },
        ],
      },
      required: true,
      include: [
        {
          model: BranchMaster,
          as: 'branchMaster',
          attributes: [],
        },
      ],
    };
  } else if (
    userDetails.accessibleCompanies &&
    userDetails.accessibleCompanies.length &&
    includeCompany
  ) {
    condition.where = {};
    condition.where.companyMasterId = userDetails.accessibleCompanies;
  }
  return condition;
}

async function getEmployeeFoodAllowance(userMasterID, date) {
  const foodAllowancePolicy = await EmployeeFoodAllowancePolicy.findOne({
    where: {
      userMasterID,
      startDate: {
        [Sequelize.Op.lte]: new Date(date),
      },
      [Sequelize.Op.or]: [
        {
          endDate: {
            [Sequelize.Op.gte]: new Date(date),
          },
        },
        {
          endDate: { [Sequelize.Op.eq]: null },
        },
      ],
    },
    include: [
      {
        model: FoodAllowancePolicy,
        include: [
          {
            model: FoodAllowancePolicyDetails,
            attributes: [
              [Sequelize.col('foodAllowanceType'), 'type'],
              [Sequelize.col('allowanceType'), 'allType'],
              [Sequelize.col('foodAllowanceTime'), 'time'],
              [Sequelize.col('shiftID'), 'shiftID'],
              [Sequelize.col('foodAllowanceAmount'), 'amount'],
            ],
          },
        ],
      },
      { model: UserMaster, attributes: ['companyMasterId'] },
    ],
  });

  return foodAllowancePolicy;
}

async function addFoodAllowanceInAttendance(attendance) {
  const userMasterID = attendance.userMasterID,
    date = attendance.AttendanceDate,
    shiftID = attendance.Shift,
    Attn_Status = attendance.fulldayhalfday;

  // delete Food Allowance

  const dataOfFoodAllowance = await Employeeincentive.findAll({
    where: {
      userMasterID,
      incentiveDate: date,
    },
    include: [
      {
        required: true,
        model: Incentivetype,
        where: Sequelize.and(
          Sequelize.or(
            Sequelize.where(
              sequelize.fn(
                'TRIM',
                sequelize.fn(
                  'LOWER',
                  sequelize.col('incentivetype.incentivetypename')
                )
              ),
              'food allowance'
            ),
            Sequelize.where(
              sequelize.fn(
                'TRIM',
                sequelize.fn(
                  'LOWER',
                  sequelize.col('incentivetype.incentivetypename')
                )
              ),
              'tea/coffee allowance'
            )
          )
        ),
      },
    ],
  });

  await Employeeincentive.destroy({
    where: {
      employeeincentiveID: dataOfFoodAllowance.map(
        (e) => e.employeeincentiveID
      ),
    },
  });

  let EmpFoodAllowancePolicy = await getEmployeeFoodAllowance(
    userMasterID,
    date
  );

  if (!EmpFoodAllowancePolicy) return;

  EmpFoodAllowancePolicy = EmpFoodAllowancePolicy.toJSON();

  let foodAllowance_Amount = 0,
    teaAllowance_Amount = 0;

  // if no FoodAllowance and no Tea/Coffee Allowance
  if (
    EmpFoodAllowancePolicy &&
    EmpFoodAllowancePolicy.foodAllowancePolicy.foodAllowanceType ==
      FoodAllowanceTypeEnum.NO_FOOD_ALLOWANCE &&
    EmpFoodAllowancePolicy.foodAllowancePolicy.teaAllowanceType ==
      TeaAllowanceTypeEnum.NO_TEA_ALLOWANCE
  )
    return;
  // ----------Food Allowance -------------------

  // if foodAllowanceType is onInOutTime

  if (
    EmpFoodAllowancePolicy.foodAllowancePolicy.foodAllowanceType ==
      FoodAllowanceTypeEnum.ON_INOUT_TIME &&
    EmpFoodAllowancePolicy.foodAllowancePolicy.foodAllowancePolicyDetails &&
    EmpFoodAllowancePolicy.foodAllowancePolicy.foodAllowancePolicyDetails
      .length > 0
  ) {
    let totalAmount = 0;

    const foodAllowanceInDetailsData =
      EmpFoodAllowancePolicy.foodAllowancePolicy.foodAllowancePolicyDetails.find(
        (e) => e.type == 'in' && e.shiftID == shiftID && e.allType == 'food'
      );

    const foodAllowanceOutDetailsData =
      EmpFoodAllowancePolicy.foodAllowancePolicy.foodAllowancePolicyDetails.find(
        (e) => e.type == 'out' && e.shiftID == shiftID && e.allType == 'food'
      );

    if (
      foodAllowanceInDetailsData &&
      new Date(attendance.InDatetime) <
        new Date(date + ' ' + foodAllowanceInDetailsData.time)
    )
      totalAmount += +foodAllowanceInDetailsData.amount;
    if (
      foodAllowanceOutDetailsData &&
      new Date(attendance.OutDateTime) >
        new Date(date + ' ' + foodAllowanceOutDetailsData.time)
    ) {
      // food allowance allowed only when complete working hour
      if (
        EmpFoodAllowancePolicy.foodAllowancePolicy.foodAllowanceCompleteHours &&
        +attendance.InHrs >= +attendance.Shifthrs * 60
      )
        totalAmount += +foodAllowanceOutDetailsData.amount;

      if (
        !EmpFoodAllowancePolicy.foodAllowancePolicy.foodAllowanceCompleteHours
      )
        totalAmount += +foodAllowanceOutDetailsData.amount;
    }

    foodAllowance_Amount = totalAmount;
  }

  // if foodAllowanceType is ON_WORKING_HOURS

  if (
    EmpFoodAllowancePolicy.foodAllowancePolicy.foodAllowanceType ==
      FoodAllowanceTypeEnum.ON_WORKING_HOURS &&
    +attendance.InHrs >=
      +EmpFoodAllowancePolicy.foodAllowancePolicy.minimumWorkingMinutes
  ) {
    foodAllowance_Amount =
      +EmpFoodAllowancePolicy.foodAllowancePolicy.workingTimeAmount;
  }

  // -----------------Tea/Coffee Allowance-------------------------

  // if Tea Allowance Type is ON_IN_TIME

  if (
    EmpFoodAllowancePolicy.foodAllowancePolicy.teaAllowanceType ==
      TeaAllowanceTypeEnum.ON_IN_TIME &&
    EmpFoodAllowancePolicy.foodAllowancePolicy.foodAllowancePolicyDetails &&
    EmpFoodAllowancePolicy.foodAllowancePolicy.foodAllowancePolicyDetails
      .length > 0
  ) {
    const teaAllowanceInDetailsData =
      EmpFoodAllowancePolicy.foodAllowancePolicy.foodAllowancePolicyDetails.find(
        (e) => e.type == 'in' && e.shiftID == shiftID && e.allType == 'tea'
      );

    if (teaAllowanceInDetailsData)
      teaAllowance_Amount = teaAllowanceInDetailsData.amount;
  }

  // if Tea Allowance Type is On Attn Status

  if (
    EmpFoodAllowancePolicy.foodAllowancePolicy.teaAllowanceType ==
    TeaAllowanceTypeEnum.ON_ATTN_STATUS
  ) {
    if (Attn_Status == 0.5)
      teaAllowance_Amount =
        +EmpFoodAllowancePolicy.foodAllowancePolicy.teaHalfDayAmount;
    if (Attn_Status == 1)
      teaAllowance_Amount =
        +EmpFoodAllowancePolicy.foodAllowancePolicy.teaFullDayAmount;
  }

  const foodAllowanceTypeIncentive = await Incentivetype.findAll({
    raw: true,
    where: Sequelize.and(
      Sequelize.or(
        Sequelize.where(
          sequelize.fn(
            'TRIM',
            sequelize.fn(
              'LOWER',
              sequelize.col('incentivetype.incentivetypename')
            )
          ),
          'food allowance'
        ),
        Sequelize.where(
          sequelize.fn(
            'TRIM',
            sequelize.fn(
              'LOWER',
              sequelize.col('incentivetype.incentivetypename')
            )
          ),
          'tea/coffee allowance'
        )
      ),
      Sequelize.where(
        sequelize.col('companyMasterID'),
        EmpFoodAllowancePolicy.userMaster.companyMasterId
      ),
      Sequelize.or(
        Sequelize.where(sequelize.col('status'), 0),
        Sequelize.where(sequelize.col('status'), 1)
      )
    ),
  });

  const foodAllowance = foodAllowanceTypeIncentive.find(
    (e) => String(e.incentivetypename).trim().toLowerCase() == 'food allowance'
  );
  const teaAllowance = foodAllowanceTypeIncentive.find(
    (e) =>
      String(e.incentivetypename).trim().toLowerCase() == 'tea/coffee allowance'
  );

  if (foodAllowance_Amount > 0 && foodAllowance) {
    // Add Food Allowance in Employee Incentive
    await Employeeincentive.create({
      userMasterID,
      yearmonth: String(date).slice(0, 4) + String(date).slice(5, 7),
      amount: foodAllowance_Amount,
      IncentivetypeID: foodAllowance.IncentivetypeID,
      incentiveDate: date,
      createBy: attendance.createBy,
    });
  }

  if (teaAllowance_Amount > 0 && teaAllowance) {
    // Add Tea/Coffee Allowance in Employee Incentive
    await Employeeincentive.create({
      userMasterID,
      yearmonth: String(date).slice(0, 4) + String(date).slice(5, 7),
      amount: teaAllowance_Amount,
      IncentivetypeID: teaAllowance.IncentivetypeID,
      incentiveDate: date,
      createBy: attendance.createBy,
    });
  }

  return;
}

