function getDatesBetween(fromDate, toDate) {
  const dates = [];
  const currentDate = new Date(fromDate);
  const endDate = new Date(toDate);

  while (currentDate <= endDate) {
    dates.push(new Date(currentDate));
    currentDate.setDate(currentDate.getDate() + 1);
  }

  return dates;
}

async function getemployeeLeavePolicy(userid, date) {
  const getEmployeeLeavePolicy = await empLeavePolicy.findOne({
    raw: true,
    where: {
      userMasterID: userid,
      status: 1,
      applicableDate: {
        [Sequelize.Op.lte]: new Date(date),
      },
      [Sequelize.Op.or]: [
        {
          endDate: {
            [Sequelize.Op.gte]: new Date(date),
          },
        },
        {
          endDate: { [Sequelize.Op.eq]: null },
        },
      ],
    },
  });

  if (getEmployeeLeavePolicy) {
    const allLeavePolicy = [];

    for (let leavePolicyID of getEmployeeLeavePolicy.employeeLeavePolicyID) {
      const LeavePolicy = await EmployeeLeavePolicy.findOne({
        raw: true,
        where: {
          id: leavePolicyID,
        },
      });
      if (LeavePolicy) allLeavePolicy.push(LeavePolicy);
    }

    return allLeavePolicy;
  } else {
    return [];
  }
}

// Get End Date of Financial year
function getEndDate(startDate) {
  const date = new Date(startDate); // Initialize with the start date
  date.setFullYear(date.getFullYear() + 1); // Add one year
  date.setDate(date.getDate() - 1); // Subtract one day to get the end date
  return date.toISOString().split('T')[0]; // Return as 'YYYY-MM-DD'
}

// Get Quarterly Dates

function getQuarterlyDates(startDate, endDate) {
  const quarters = [];

  const start = new Date(startDate);
  const end = new Date(endDate);

  // Loop to calculate each quarter
  for (let i = 0; i < 4; i++) {
    const quarterStart = new Date(start);
    quarterStart.setMonth(start.getMonth() + i * 3); // Set quarter start month

    const quarterEnd = new Date(quarterStart);
    quarterEnd.setMonth(quarterEnd.getMonth() + 3); // Set quarter end month
    quarterEnd.setDate(quarterEnd.getDate() - 1); // Set to the day before next quarter

    // Ensure quarter end does not exceed the financial end date
    if (quarterEnd > end) {
      quarterEnd.setTime(end.getTime());
    }

    quarters.push({
      quarter: `Q${i + 1}`,
      startDate: quarterStart.toISOString().split('T')[0],
      endDate: quarterEnd.toISOString().split('T')[0],
    });
  }

  return quarters;
}

// To GET Half Yarly

function getHalfYearlyDates(startDate, endDate) {
  const halves = [];

  const start = new Date(startDate);
  const end = new Date(endDate);

  // First half (H1): From startDate to six months later
  const firstHalfStart = new Date(start);
  const firstHalfEnd = new Date(firstHalfStart);
  firstHalfEnd.setMonth(firstHalfStart.getMonth() + 6); // Add 6 months
  firstHalfEnd.setDate(firstHalfEnd.getDate() - 1); // Set to the day before the 7th month

  halves.push({
    half: 'H1',
    startDate: firstHalfStart.toISOString().split('T')[0],
    endDate: firstHalfEnd.toISOString().split('T')[0],
  });

  // Second half (H2): From the day after the first half ends to endDate
  const secondHalfStart = new Date(firstHalfEnd);
  secondHalfStart.setDate(secondHalfStart.getDate() + 1); // Day after the first half ends

  const secondHalfEnd = new Date(end); // End of the financial year

  halves.push({
    half: 'H2',
    startDate: secondHalfStart.toISOString().split('T')[0],
    endDate: secondHalfEnd.toISOString().split('T')[0],
  });

  return halves;
}

async function checkEmployeeLeavePolicyWhenLeaveApply(leaveData, type) {
  if (leaveData.length === 0) return;

  function dateDiffInDays(a, b) {
    const _MS_PER_DAY = 1000 * 60 * 60 * 24;
    const utc1 = Date.UTC(a.getFullYear(), a.getMonth(), a.getDate());
    const utc2 = Date.UTC(b.getFullYear(), b.getMonth(), b.getDate());
    return Math.floor((utc2 - utc1) / _MS_PER_DAY);
  }

  let message = '';

  const currentDate = asiaKolkataDateTime(new Date()).slice(0, 10);
  const [allCurrentLeavePolicy, user_salaryPolicy] = await Promise.all([
    getemployeeLeavePolicy(leaveData[0].userMasterID, currentDate),
    employeeSalaryPolicy(leaveData[0].userMasterID, currentDate),
  ]);

  const leavePromises = leaveData.map(async (leave) => {
    const leaveType = await HrLeaveTypes.findOne({
      raw: true,
      where: { LeaveTranId: leave.LeaveTranId, status: 1 },
      include: [
        { model: HrLeaveMaster, as: 'LeaveMaster', attributes: ['LeaveName'] },
      ],
    });

    if (!leaveType) return null;

    const leavePolicy = allCurrentLeavePolicy.find(
      (e) => e.leaveId == leaveType.LeaveID
    );
    if (!leavePolicy) return null;

    // ---leave = current leave,type='add' or 'update' ---

    const leaveValidationResult = await validateLeave(
      leave,
      leavePolicy,
      user_salaryPolicy,
      currentDate,
      leaveType,
      type
    );
    if (leaveValidationResult) message = leaveValidationResult;

    return message;
  });

  await Promise.all(leavePromises);

  return message;

  async function validateLeave(
    leave,
    leavePolicy,
    user_salaryPolicy,
    currentDate,
    leaveType,
    type
  ) {
    const dateCheckResult = checkDateRestrictions(
      leave,
      leavePolicy,
      currentDate,
      leaveType
    );
    if (dateCheckResult) return dateCheckResult;

    const maxLeaveResult = await checkMaxLeave(
      leave,
      leavePolicy,
      user_salaryPolicy,
      currentDate,
      leaveType,
      type
    );
    if (maxLeaveResult) return maxLeaveResult;

    if (+leavePolicy.allowHalfDays == 0 && +leave.LeaveDays == 0.5) {
      return `Half-day leave is not allowed for ${leaveType['LeaveMaster.LeaveName']}. Please select a full day.`;
    }

    // --------------------Attachment Require--------------------

    if (
      +leavePolicy.min_leave_attachment > 0 &&
      +leave.LeaveDays >= +leavePolicy.min_leave_attachment &&
      !leave.attachment
    ) {
      return `An attachment is required when taking ${leavePolicy.min_leave_attachment} or more days of ${leaveType['LeaveMaster.LeaveName']}. Please provide the necessary document.`;
    }

    return null;
  }

  // --------------- check date restriction --------------

  function checkDateRestrictions(leave, leavePolicy, currentDate, leaveType) {
    const allDatesOfLeave = getDatesBetween(leave.FromDate, leave.ToDate).map(
      (date) => date.toISOString().split('T')[0]
    );

    // --- check for future leave condition and past leave condition -------------------------------------
    if (
      +leavePolicy.allowFutureApplyDays > 0 ||
      +leavePolicy.allowPastApplyDays > 0
    ) {
      // const currentfromDate = currentDate;

      const futureDate = new Date(currentDate);

      if (+leavePolicy.allowFutureApplyDays) {
        futureDate.setDate(
          futureDate.getDate() + +leavePolicy.allowFutureApplyDays
        );
      } else {
        futureDate.setDate(
          futureDate.getDate() - +leavePolicy.allowPastApplyDays
        );
      }

      const current = futureDate.toISOString().split('T')[0];
      // const unAuthorizedDates = getDatesBetween(
      //   currentfromDate,
      //   currenttoDate
      // ).map((date) => date.toISOString().split('T')[0]);

      // const isAnyDatePresent = unAuthorizedDates.some((date) =>
      //   allDatesOfLeave.includes(date)
      // );

      const isGreater = allDatesOfLeave.some(
        (date) => new Date(date) < new Date(current)
      );

      if (isGreater) {
        if (leavePolicy.allowFutureApplyDays) {
          return `You must apply for leave at least ${leavePolicy.allowFutureApplyDays} days in advance. Please choose a later date.`;
        } else {
          return `You cannot apply for leave that was more than ${leavePolicy.allowPastApplyDays} days ago. Please choose a more recent date.`;
        }
      }
    }

    // --- check for leave apply at a time -------------------------------------

    if (
      +leavePolicy.allowMinInMonth > 0 &&
      +leave.LeaveDays > +leavePolicy.allowMinInMonth
    ) {
      return `You cannot apply for more than ${leavePolicy.allowMinInMonth} days of '${leaveType['LeaveMaster.LeaveName']}' at a time. Please reduce the number of days.`;
    }

    return null;
  }

  // --- check max leave allowed in one month ----------------------------------

  async function calculateLeavesToAllow(
    leaveData,
    leave,
    startDate,
    endDate,
    type
  ) {
    let { currentMonthLeave, futureMonthLeave } = calculateMonthLeaves(
      leaveData,
      leave,
      startDate,
      endDate
    );

    const [approvedLeave, pendingLeaves] = await fetchLeaves(
      leave,
      startDate,
      endDate,
      type
    );
    const approvedLeaveSum = sumLeaveDays(approvedLeave);
    const pendingLeaveSum = sumPendingLeaveDays(
      pendingLeaves,
      startDate,
      endDate
    );

    return +currentMonthLeave + +approvedLeaveSum + +pendingLeaveSum;
  }

  // ---------------------------For Checking MAx Leave Allowed ---------------------------------
  async function checkMaxLeave(
    leave,
    leavePolicy,
    user_salaryPolicy,
    currentDate,
    leaveType,
    type
  ) {
    const cycleDate = user_salaryPolicy
      ? String(user_salaryPolicy['salaryPolicy.salaryCycleDate'])
      : '01';

    // set startDate as default year
    let financialStartDate =
      String(leave.FromDate).slice(0, 4) + '-' + '01' + '-' + '01';
    let financialEndDate =
      String(leave.FromDate).slice(0, 4) + '-' + '12' + '-' + '31';

    if (leavePolicy.leaveOperationalYear == 'April To March') {
      const dates = await getFinancialYearDatesFromDate(leave.FromDate);
      financialStartDate = dates.startDate;
      financialEndDate = dates.endDate;
    }

    financialStartDate =
      financialStartDate.slice(0, 8) + cycleDate.padStart(2, 0);
    financialEndDate = getEndDate(financialStartDate);

    // TO set future financial Year

    const futureDate = new Date(financialEndDate).setDate(
      new Date(financialEndDate).getDate() + 1
    );

    const future_FinancialYear_StartDate = new Date(futureDate)
      .toISOString()
      .slice(0, 10);
    const future_FinancialYear_EndDate = getEndDate(
      future_FinancialYear_StartDate
    );

    let startDate,
      endDate,
      allowedLeave = 0;

    // if Monthly
    if (+leavePolicy.allowMaxInMonth > 0) {
      allowedLeave = +leavePolicy.allowMaxInMonth;
      const dates = getMonthDateRange(leave.FromDate, cycleDate);

      (startDate = dates.startDate), (endDate = dates.endDate);

      const sum = await calculateLeavesToAllow(
        leaveData,
        leave,
        startDate,
        endDate,
        type
      );

      if (+sum > +allowedLeave) {
        return `You have exceeded the limit of ${allowedLeave} days of '${leaveType['LeaveMaster.LeaveName']}' in a month. Please adjust your leave dates.`;
      }

      if (new Date(leave.ToDate) > new Date(endDate)) {
        const { startDate: future_startDate, endDate: future_endDate } =
          getFutureDateRange(startDate);

        const sumFuture = await calculateLeavesToAllow(
          leaveData,
          leave,
          future_startDate,
          future_endDate,
          type
        );

        if (+sumFuture > +allowedLeave) {
          return `You have exceeded the limit of ${allowedLeave} days of '${leaveType['LeaveMaster.LeaveName']}' in a month. Please adjust your leave dates.`;
        }
      }
    }

    // if Quarterly

    if (+leavePolicy.allowMaxInQuarter > 0) {
      allowedLeave = +leavePolicy.allowMaxInQuarter;
      const Alldates = getQuarterlyDates(financialStartDate, financialEndDate);

      const dates = Alldates.find(
        (e) =>
          new Date(e.startDate) <= new Date(leave.FromDate) &&
          new Date(e.endDate) >= new Date(leave.FromDate)
      );

      (startDate = dates.startDate), (endDate = dates.endDate);

      const sum = await calculateLeavesToAllow(
        leaveData,
        leave,
        startDate,
        endDate,
        type
      );

      if (+sum > +allowedLeave) {
        return `You have exceeded the limit of ${allowedLeave} days of '${leaveType['LeaveMaster.LeaveName']}' in a Quarter. Please adjust your leave dates.`;
      }

      if (new Date(leave.ToDate) > new Date(endDate)) {
        let future_StartDate, future_EndDate;

        const future_dates = getQuarterlyDates(
          financialStartDate,
          financialEndDate
        ).find(
          (e) =>
            new Date(e.startDate).getTime() <=
              new Date(leave.ToDate).getTime() &&
            new Date(e.endDate).getTime() >= new Date(leave.ToDate).getTime()
        );
        if (future_dates) {
          (future_StartDate = future_dates.startDate),
            (future_EndDate = future_dates.endDate);
        } else {
          const future_dates = getQuarterlyDates(
            future_FinancialYear_StartDate,
            future_FinancialYear_EndDate
          ).find(
            (e) =>
              new Date(e.startDate).getTime() <=
                new Date(leave.ToDate).getTime() &&
              new Date(e.endDate).getTime() >= new Date(leave.ToDate).getTime()
          );
          (future_StartDate = future_dates.startDate),
            (future_EndDate = future_dates.endDate);
        }

        const future_sum = await calculateLeavesToAllow(
          leaveData,
          leave,
          future_StartDate,
          future_EndDate,
          type
        );

        if (+future_sum > +allowedLeave) {
          return `You have exceeded the limit of ${allowedLeave} days of '${leaveType['LeaveMaster.LeaveName']}' in a Quarter. Please adjust your leave dates.`;
        }
      }
    }

    // if Half Yearly

    if (+leavePolicy.allowMaxInHalfYear > 0) {
      allowedLeave = +leavePolicy.allowMaxInHalfYear;
      const dates = getHalfYearlyDates(
        financialStartDate,
        financialEndDate
      ).find(
        (e) =>
          new Date(e.startDate).getTime() <=
            new Date(leave.FromDate).getTime() &&
          new Date(e.endDate).getTime() >= new Date(leave.FromDate).getTime()
      );
      (startDate = dates.startDate), (endDate = dates.endDate);

      const sum = await calculateLeavesToAllow(
        leaveData,
        leave,
        startDate,
        endDate,
        type
      );
      if (+sum > +allowedLeave) {
        return `You have exceeded the limit of ${allowedLeave} days of '${leaveType['LeaveMaster.LeaveName']}' in a Half Year. Please adjust your leave dates.`;
      }

      if (new Date(leave.ToDate) > new Date(endDate)) {
        let future_StartDate, future_EndDate;

        const future_dates = getHalfYearlyDates(
          financialStartDate,
          financialEndDate
        ).find(
          (e) =>
            new Date(e.startDate).getTime() <=
              new Date(leave.ToDate).getTime() &&
            new Date(e.endDate).getTime() >= new Date(leave.ToDate).getTime()
        );
        if (future_dates) {
          (future_StartDate = future_dates.startDate),
            (future_EndDate = future_dates.endDate);
        } else {
          const future_dates = getHalfYearlyDates(
            future_FinancialYear_StartDate,
            future_FinancialYear_EndDate
          ).find(
            (e) =>
              new Date(e.startDate).getTime() <=
                new Date(leave.ToDate).getTime() &&
              new Date(e.endDate).getTime() >= new Date(leave.ToDate).getTime()
          );
          (future_StartDate = future_dates.startDate),
            (future_EndDate = future_dates.endDate);
        }

        const future_sum = await calculateLeavesToAllow(
          leaveData,
          leave,
          future_StartDate,
          future_EndDate,
          type
        );
        if (+future_sum > +allowedLeave) {
          return `You have exceeded the limit of ${allowedLeave} days of '${leaveType['LeaveMaster.LeaveName']}' in a Half Year. Please adjust your leave dates.`;
        }
      }
    }

    // if Yearly

    if (+leavePolicy.allowMaxInYear > 0) {
      allowedLeave = +leavePolicy.allowMaxInYear;
      (startDate = financialStartDate), (endDate = financialEndDate);

      const sum = await calculateLeavesToAllow(
        leaveData,
        leave,
        startDate,
        endDate,
        type
      );
      if (+sum > +allowedLeave) {
        return `You have exceeded the limit of ${allowedLeave} days of '${leaveType['LeaveMaster.LeaveName']}' in a Year. Please adjust your leave dates.`;
      }

      if (new Date(leave.ToDate) > new Date(endDate)) {
        const future_sum = await calculateLeavesToAllow(
          leaveData,
          leave,
          future_FinancialYear_StartDate,
          future_FinancialYear_EndDate,
          type
        );
        if (+future_sum > +allowedLeave) {
          return `You have exceeded the limit of ${allowedLeave} days of '${leaveType['LeaveMaster.LeaveName']}' in a Year. Please adjust your leave dates.`;
        }
      }
    }

    // let { currentMonthLeave, futureMonthLeave } = calculateMonthLeaves(
    //   leaveData,
    //   leave,
    //   startDate,
    //   endDate
    // );

    // const [approvedLeave, pendingLeaves] = await fetchLeaves(
    //   leave,
    //   startDate,
    //   endDate,
    //   type
    // );
    // const approvedLeaveSum = sumLeaveDays(approvedLeave);
    // const pendingLeaveSum = sumPendingLeaveDays(
    //   pendingLeaves,
    //   startDate,
    //   endDate
    // );

    // if (
    //   +currentMonthLeave + +approvedLeaveSum + +pendingLeaveSum >
    //   +leavePolicy.allowMaxInMonth
    // ) {
    //   return `You have exceeded the limit of ${leavePolicy.allowMaxInMonth} days of '${leaveType['LeaveMaster.LeaveName']}' in a month. Please adjust your leave dates.`;
    // }

    // if (new Date(leave.ToDate) > new Date(endDate)) {
    //   const { startDate: future_startDate, endDate: future_endDate } = getFutureDateRange(startDate);
    //   const [approvedLeaveFuture, pendingLeavesFuture] = await fetchLeaves(
    //     leave,
    //     future_startDate,
    //     future_endDate,
    //     type
    //   );
    //   const approvedLeaveSumFuture = sumLeaveDays(approvedLeaveFuture);
    //   const pendingLeaveSumFuture = sumPendingLeaveDays(
    //     pendingLeavesFuture,
    //     future_startDate,
    //     future_endDate
    //   );

    //   if (
    //     +futureMonthLeave + +approvedLeaveSumFuture + +pendingLeaveSumFuture >
    //     +leavePolicy.allowMaxInMonth
    //   ) {
    //     return `You have exceeded the limit of ${leavePolicy.allowMaxInMonth} days of '${leaveType['LeaveMaster.LeaveName']}' in a month. Please adjust your leave dates.`;
    //   }
    // }

    return null;
  }

  // ---- To create Date Range ------------
  function getMonthDateRange(fromDate, cycleDate) {
    const date = cycleDate.padStart(2, '0');
    let startDate, endDate;

    const fromYear = fromDate.slice(0, 4);
    const fromMonth = fromDate.slice(5, 7);
    const fromDay = fromDate.slice(8, 10);

    // Parse the fromDate and cycleDate into integers
    const fromDateObj = new Date(fromDate);
    const cycleDateInt = parseInt(cycleDate);

    // If fromDate is less than salary policy date
    if (parseInt(fromDay) < cycleDateInt) {
      let tempStartDate = new Date(fromDateObj);
      tempStartDate.setMonth(tempStartDate.getMonth() - 1);

      startDate =
        tempStartDate.getFullYear() +
        '-' +
        String(tempStartDate.getMonth() + 1).padStart(2, '0') +
        '-' +
        date;

      const mondays = daysInMonth(startDate.slice(5, 7), startDate.slice(0, 4));

      let tempEndDate = new Date(startDate);
      tempEndDate.setDate(tempEndDate.getDate() + (mondays - 1));

      endDate =
        tempEndDate.getFullYear() +
        '-' +
        String(tempEndDate.getMonth() + 1).padStart(2, '0') +
        '-' +
        String(tempEndDate.getDate()).padStart(2, '0');
    } else {
      startDate = fromYear + '-' + fromMonth + '-' + date;

      const mondays = daysInMonth(fromMonth, fromYear);

      let tempEndDate = new Date(startDate);
      tempEndDate.setDate(tempEndDate.getDate() + (mondays - 1));

      endDate =
        tempEndDate.getFullYear() +
        '-' +
        String(tempEndDate.getMonth() + 1).padStart(2, '0') +
        '-' +
        String(tempEndDate.getDate()).padStart(2, '0');
    }

    return { startDate, endDate };
  }

  // -- future date range -------
  function getFutureDateRange(startDate) {
    let futureStartDate = new Date(startDate);
    futureStartDate.setMonth(futureStartDate.getMonth() + 1);

    futureStartDate =
      futureStartDate.getFullYear() +
      '-' +
      String(futureStartDate.getMonth() + 1).padStart(2, '0') +
      '-' +
      String(futureStartDate.getDate()).padStart(2, '0');

    const mondays = daysInMonth(
      futureStartDate.slice(5, 7),
      futureStartDate.slice(0, 4)
    );

    let futureEndDate = new Date(futureStartDate);
    futureEndDate.setDate(futureEndDate.getDate() + (mondays - 1));

    futureEndDate =
      futureEndDate.getFullYear() +
      '-' +
      String(futureEndDate.getMonth() + 1).padStart(2, '0') +
      '-' +
      String(futureEndDate.getDate()).padStart(2, '0');

    return { startDate: futureStartDate, endDate: futureEndDate };
  }
  // --------------calculate current month leave --------------

  function calculateMonthLeaves(leaveData, leave, startDate, endDate) {
    let currentMonthLeave = 0,
      futureMonthLeave = 0;

    const sameAllLeave = leaveData.filter(
      (e) => e.LeaveTranId == leave.LeaveTranId
    );
    for (const allLeave of sameAllLeave) {
      if (+allLeave.LeaveDays == 0.5) {
        currentMonthLeave += +allLeave.LeaveDays;
      } else if (new Date(allLeave.ToDate) > new Date(endDate)) {
        currentMonthLeave += Math.max(
          0,
          dateDiffInDays(new Date(allLeave.FromDate), new Date(endDate)) + 1
        );
        futureMonthLeave += Math.max(
          0,
          dateDiffInDays(new Date(endDate), new Date(allLeave.ToDate))
        );
      } else {
        currentMonthLeave += +allLeave.LeaveDays;
      }
    }

    return { currentMonthLeave, futureMonthLeave };
  }

  async function fetchLeaves(leave, startDate, endDate, type) {
    const pendingCondition = buildPendingCondition(
      leave,
      startDate,
      endDate,
      type
    );
    return await Promise.all([
      UserLeaveTransaction.findAll({
        raw: true,
        where: {
          date: { [Sequelize.Op.between]: [startDate, endDate] },
          status: 1,
          LeaveTranId: leave.LeaveTranId,
          '$userLeave.userMasterID$': leave.userMasterID,
        },
        include: [{ model: UserLeave, attributes: [] }],
      }),
      UserLeave.findAll({ raw: true, where: pendingCondition }),
    ]);
  }

  // --------------condition ---------------

  function buildPendingCondition(leave, startDate, endDate, type) {
    const pendingCondition = {
      userMasterID: leave.userMasterID,
      status: 1,
      authorizationStatus: { [Sequelize.Op.in]: [0, 1, 2] },
      LeaveTranId: leave.LeaveTranId,
      [Op.or]: [
        { FromDate: { [Op.between]: [startDate, endDate] } },
        { ToDate: { [Op.between]: [startDate, endDate] } },
        {
          [Op.and]: [
            { FromDate: { [Op.lte]: startDate } },
            { ToDate: { [Op.gte]: endDate } },
          ],
        },
      ],
    };

    if (type == 'update') {
      pendingCondition.UserLeaveApplicationID = {
        [Sequelize.Op.ne]: leave.UserLeaveApplicationID,
      };
    }

    return pendingCondition;
  }
  // ----------sum of approved leave days -----------

  function sumLeaveDays(leaves) {
    return leaves.reduce((acc, obj) => acc + +obj.days, 0);
  }

  // -----------sum of pending leave days -----------------

  function sumPendingLeaveDays(pendingLeaves, startDate, endDate) {
    return pendingLeaves.reduce((acc, pendingleave) => {
      if (new Date(pendingleave.ToDate) > new Date(endDate)) {
        acc += Math.max(
          0,
          dateDiffInDays(new Date(pendingleave.FromDate), new Date(endDate)) + 1
        );
      } else if (new Date(pendingleave.FromDate) < new Date(startDate)) {
        acc += Math.max(
          0,
          dateDiffInDays(new Date(startDate), new Date(pendingleave.ToDate)) + 1
        );
      } else {
        acc += +pendingleave.LeaveDays;
      }
      return acc;
    }, 0);
  }
}

async function getCompanyTree(companyMasterID) {
  const currCompany = await companyMaster.findOne({
    where: { companyMasterID: companyMasterID, status: 1 },
    attributes: ['companyMasterID', 'parentCompanyMasterID'],
    raw: true,
  });

  if (+currCompany.parentCompanyMasterID) {
    const allCompany = await companyMaster.findAll({
      raw: true,
      where: {
        [Sequelize.Op.or]: [
          { companyMasterID: +currCompany.parentCompanyMasterID },
          { parentCompanyMasterID: +currCompany.parentCompanyMasterID },
        ],
        status: 1,
      },
    });

    const companyTreeIds = allCompany.map((item) => item.companyMasterID);
    return companyTreeIds;
  } else {
    const allCompany = await companyMaster.findAll({
      raw: true,
      where: {
        [Sequelize.Op.or]: [
          { companyMasterID: +companyMasterID },
          { parentCompanyMasterID: +companyMasterID },
        ],
        status: 1,
      },
    });

    const companyTreeIds = allCompany.map((item) => item.companyMasterID);
    return companyTreeIds;
  }
}

const formatDateTime = (date) => {
  if (!date) return '';
  const d = new Date(date);
  const day = String(d.getDate()).padStart(2, '0');
  const month = String(d.getMonth() + 1).padStart(2, '0');
  const year = d.getFullYear();
  const hours = String(d.getHours()).padStart(2, '0');
  const minutes = String(d.getMinutes()).padStart(2, '0');
  const seconds = String(d.getSeconds()).padStart(2, '0');

  return `${day}-${month}-${year} ${hours}:${minutes}:${seconds}`;
};

function formatDate(dateObj) {
  return (
    dateObj.getFullYear() +
    '-' +
    String(dateObj.getMonth() + 1).padStart(2, '0') +
    '-' +
    String(dateObj.getDate()).padStart(2, '0')
  );
}

function adjustMonth(dateObj, monthOffset) {
  dateObj.setMonth(dateObj.getMonth() + monthOffset);
  return dateObj;
}

async function getSalaryMonthBySalaryPolicy(
  salaryPolicyFlag,
  salaryCycleDate,
  salaryCycleConsider,
  AttendanceDate
) {
  let start_Date;
  let end_Date;

  const month = Number(String(AttendanceDate).slice(5, 7));
  const year = Number(String(AttendanceDate).slice(0, 4));
  const monday = daysInMonth(month, year);

  if (salaryPolicyFlag) {
    start_Date =
      AttendanceDate.slice(0, 8) +
      (+salaryCycleDate < 10 ? '0' : '') +
      salaryCycleDate;

    const date1 = new Date(start_Date);
    date1.setDate(date1.getDate() + (monday - 1));

    end_Date = formatDate(date1);
  } else {
    start_Date = AttendanceDate.slice(0, 8) + '01';
    end_Date = AttendanceDate.slice(0, 8) + monday;
  }

  if (new Date(start_Date) > new Date(AttendanceDate)) {
    const previousMonthStart = adjustMonth(new Date(start_Date), -1);
    start_Date = formatDate(previousMonthStart);

    const previousMonthEnd = adjustMonth(new Date(end_Date), -1);
    end_Date = formatDate(previousMonthEnd);
  } else if (new Date(end_Date) < new Date(AttendanceDate)) {
    const nextMonthStart = adjustMonth(new Date(start_Date), 1);
    start_Date = formatDate(nextMonthStart);

    const nextMonthEnd = adjustMonth(new Date(start_Date), 1);
    end_Date = formatDate(nextMonthEnd);
  }

  return salaryPolicyFlag && salaryCycleConsider == 'E'
    ? end_Date.slice(0, 4) + end_Date.slice(5, 7)
    : start_Date.slice(0, 4) + start_Date.slice(5, 7);
}

