function getDateTimeFormat(date, time) {
  const dateTime = date + ' ' + time;
  return (
    date +
    ' ' +
    String(new Date(dateTime).getHours()).padStart(2, 0) +
    ':' +
    String(new Date(dateTime).getMinutes()).padStart(2, 0) +
    ':00'
  );
}

function setInOutDirection(logData = []) {
  logData.forEach((item, index) => {
    item.direction = index % 2 === 0 ? 'in' : 'out';
    item.logDateTime =
      item.logDateTime.slice(0, 10) + ' ' + item.logDateTime.slice(11, 16);
  });

  return logData;
}

function sortLogsByDateTime(logData = []) {
  const data = logData.sort((a, b) => {
    const dateA = new Date(a.logDateTime).getTime();
    const dateB = new Date(b.logDateTime).getTime();
    return dateA - dateB; // Ascending order
  });

  return setInOutDirection(data);
}

function calculateOutTimeInMinutes(logData = []) {
  // Ensure logs are sorted by date and time
  let totalOutTimeInMinutes = 0;

  for (let i = 0; i < logData.length - 1; i++) {
    const currentLog = logData[i];
    const nextLog = logData[i + 1];

    // Find "in" followed by "out"
    if (nextLog.direction === 'in' && currentLog.direction === 'out') {
      const inTime = new Date(currentLog.logDateTime).getTime();
      const outTime = new Date(nextLog.logDateTime).getTime();

      // Calculate the difference in minutes
      const timeDifferenceInMinutes = (outTime - inTime) / (1000 * 60);
      totalOutTimeInMinutes += timeDifferenceInMinutes;
    }
  }

  return totalOutTimeInMinutes;
}

async function AddAsopalavBreakTime_Manual(
  userid,
  attendnaceLogs,
  companyid,
  date,
  transid,
  transaction
) {
  // Asopalav Condition

  try {
    const penaltyID = +companyid == 277 ? 90 : +companyid == 298 ? 166 : 201;

    const findPenalty = await Penalty.findOne({
      raw: true,
      where: {
        penaltyID: penaltyID,
      },
      transaction,
    });

    if (!findPenalty) return;

    await EmployeePenalties.destroy({
      where: {
        userMasterID: userid,
        penaltyDate: date,
        penaltyID: penaltyID,
      },
      transaction,
    });

    if (attendnaceLogs.length === 0) return;

    const totalBreakTime =
      new Date(date + ' 09:35 AM') > new Date(attendnaceLogs[0].logDateTime)
        ? 90
        : 45;

    for (let j = 0; j < attendnaceLogs.length; j++) {
      if (j != 0 && attendnaceLogs[j].direction == 'in') {
        const attendance = await attendanceTransaction.findOne({
          where: {
            AttendanceTransID: transid,
          },
          transaction,
        });

        const breakTime = await getAsopalavBreakTime_Manual(
          attendance,
          new Date(attendnaceLogs[j].logDateTime),
          new Date(attendnaceLogs[j - 1].logDateTime)
        );

        if (breakTime.type == 'teaBreak') {
          if (breakTime.diff + +attendance.lunchBreak > +totalBreakTime)
            await addAsopalavBreakTimePenalty_Manual(
              findPenalty,
              attendance.userMasterID,
              attendance.AttendanceDate,
              penaltyID,
              transaction
            );

          await attendanceTransaction.update(
            {
              teaBreak: breakTime.diff,
              teaBreakInStartTime: breakTime.starttime,
              teaBreakEndTime: breakTime.endtime,
            },
            {
              where: { AttendanceTransID: attendance.AttendanceTransID },
              transaction,
            }
          );
        } else if (breakTime.type == 'lunchBreak') {
          if (breakTime.diff > totalBreakTime) {
            await addAsopalavBreakTimePenalty_Manual(
              findPenalty,
              attendance.userMasterID,
              attendance.AttendanceDate,
              penaltyID,
              transaction
            );
          }

          await attendanceTransaction.update(
            {
              lunchBreak: breakTime.diff,
              lunchBreakStartTime: breakTime.starttime,
              lunchBreakEndTime: breakTime.endtime,
            },
            {
              where: { AttendanceTransID: attendance.AttendanceTransID },
              transaction,
            }
          );
        }
      }
    }
  } catch (error) {
    throw new Error('Error in AsopalaveBreakTime: ' + error.message);
  }
}

async function createShiftRoster(
  employeeShitRoater,
  shiftID,
  date,
  userMasterID,
  createBy,
  createByIp,
  transaction
) {
  try {
    // Create a new shift roster if it doesn't exist
    if (!employeeShitRoater) {
      await ShiftRoster.create(
        {
          userMasterID,
          shiftID,
          shiftRosterDate: date,
          createBy,
          createByIp,
        },
        { hooks: false, transaction }
      );
      return;
    }

    // Update the existing shift roster

    await ShiftRoster.update(
      {
        shiftID,
        updateBy: createBy,
        updateByIp: createByIp,
      },
      {
        where: { shiftRosterID: employeeShitRoater.shiftRosterID },
        hooks: false,
        transaction,
      }
    );

    return;
  } catch (error) {
    throw new Error('Error in Create Shift Roster: ' + error.message);
  }
}

