async function generateSecretKey(length) {
  const characters =
    'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_-';
  let secretKey = '';
  for (let i = 0; i < length; i++) {
    const randomIndex = Math.floor(Math.random() * characters.length);
    secretKey += characters[randomIndex];
  }
  return secretKey;
}
async function convertSelfieToImage(photo, user_details) {
  let convertedphoto = '';
  const today = asiaKolkataDateTime(new Date()).slice(0, 10);
  const [year, month] = today.split('-');
  let dataUrl = 'data:image/png;base64,' + photo;
  let fileName = `attendaceLogs_${user_details.userMasterID}_${Date.now()}.png`;
  let filePath = `uploads/attendaceLogs/${user_details.companyMasterId}/${month}${year}/`;
  convertedphoto = filePath + fileName;
  attendancePhotobase64Topng(dataUrl, fileName, filePath);
  return convertedphoto;
}

async function getIncludeModels(date) {
  //Inclued Model to Get Data
  const includeModels = [
    // Employee Joining Details
    {
      model: EmployeeJoiningDetails,
      required: false,
    },
    // Employee Branch
    {
      separate: true,
      required: false,
      model: EmployeeBranch,
      where: {
        status: 1,
        applicableDate: {
          [Sequelize.Op.lte]: new Date(date),
        },
        [Sequelize.Op.or]: [
          {
            endDate: {
              [Sequelize.Op.gte]: new Date(date),
            },
          },
          {
            endDate: { [Sequelize.Op.eq]: null },
          },
        ],
      },
      attributes: ['branchID'],
      include: [
        {
          model: BranchMaster,
          as: 'branchMaster',
        },
      ],
    },
    // Employee Designation
    {
      required: false,
      model: EmployeeDesignation,
      where: {
        status: 1,
        applicableDate: { [Sequelize.Op.lte]: new Date(date) },
        [Sequelize.Op.or]: [
          { endDate: { [Sequelize.Op.gte]: new Date(date) } },
          { endDate: { [Sequelize.Op.eq]: null } },
        ],
      },
    },
    // Employee Department
    {
      required: false,
      model: EmployeeDepartment,
      where: {
        status: 1,
        applicableDate: { [Sequelize.Op.lte]: new Date(date) },
        [Sequelize.Op.or]: [
          { endDate: { [Sequelize.Op.gte]: new Date(date) } },
          { endDate: { [Sequelize.Op.eq]: null } },
        ],
      },
    },
    //Employee Attendance Policy
    {
      required: false,
      separate: true,
      model: EmployeeAttendancePolicy,
      where: {
        status: 1,
        startDate: {
          [Sequelize.Op.lte]: new Date(date),
        },
        [Sequelize.Op.or]: [
          {
            endDate: {
              [Sequelize.Op.gte]: new Date(date),
            },
          },
          {
            endDate: { [Sequelize.Op.eq]: null },
          },
        ],
      },
      attributes: ['attendancePolicyID'],
      include: [
        {
          model: AttendancePolicy,
          as: 'attendancePolicy',
        },
      ],
    },
    // Employee Late Early Policy
    {
      model: EmployeeLateEarlyPolicy,
      where: {
        status: 1,
        startDate: { [Sequelize.Op.lte]: new Date(date) },
        [Sequelize.Op.or]: [
          { endDate: { [Sequelize.Op.gte]: new Date(date) } },
          { endDate: { [Sequelize.Op.eq]: null } },
        ],
      },
      required: false,
      separate: true,
      attributes: ['lateEarlyPolicyMasterID'],
      include: [
        {
          model: LateEarlyPolicy,
          as: 'lateEarlyPolicy',
        },
      ],
    },
    // Employee Date wise Attendancepolicy
    {
      model: DateWiseAttendancePolicy,
      required: false,
      where: {
        fromDate: {
          [Sequelize.Op.lte]: new Date(date),
        },
        ToDate: {
          [Sequelize.Op.gte]: new Date(date),
        },
      },
    },
    // Employee Salary Policy
    {
      required: false,
      model: EmployeeSalaryPolicy,
      where: {
        status: 1,
        startDate: {
          [Sequelize.Op.lte]: new Date(date),
        },
        [Sequelize.Op.or]: [
          {
            endDate: { [Sequelize.Op.gte]: new Date(date) },
          },
          {
            endDate: { [Sequelize.Op.eq]: null },
          },
        ],
      },
      include: [
        {
          model: SalaryPolicy,
          as: 'salaryPolicy',
        },
      ],
    },
    // Employee Shift
    {
      model: EmployeeShift,
      required: false,
      where: {
        status: 1,
        startDate: {
          [Sequelize.Op.lte]: new Date(date),
        },
        [Sequelize.Op.or]: [
          {
            endDate: {
              [Sequelize.Op.gte]: new Date(date),
            },
          },
          {
            endDate: { [Sequelize.Op.eq]: null },
          },
        ],
      },
    },
    // Shift Roster
    {
      required: false,
      model: ShiftRoster,
      where: {
        status: 1,
        shiftRosterDate: date,
      },
    },
    // Coff Master
    {
      separate: true,
      required: false,
      model: coffMaster,
      where: {
        LeaveCreatedDate: date,
        status: 1,
      },
      include: [
        {
          required: false,
          model: CompensatoryOffAuthorization,
        },
      ],
    },
  ];
  return includeModels;
}

async function checkUserLeaveBalanceNew(
  leavedata,
  type,
  findAllUserLeave,
  userLapseleave,
  addbalance,
  usedBalance,
  leaveType,
  userWiseLeaveLapseOderBy
) {
  let currentLeave;

  if (type == 'update') {
    currentLeave = await UserLeave.findOne({
      raw: true,
      where: {
        UserLeaveApplicationID: leavedata[0].UserLeaveApplicationID,
      },
    });
  }
  // find UserLeave Balance
  const userleaveBalance = employeeeLeaveBalanceNew(
    +leavedata.companyMasterID,
    +leavedata.userMasterID,
    userLapseleave,
    addbalance,
    usedBalance,
    leaveType
  );

  const leaveSum = leavedata.reduce((accumulator, item) => {
    const { LeaveTranId, LeaveDays } = item;
    accumulator[LeaveTranId] = (accumulator[LeaveTranId] || 0) + LeaveDays;
    return accumulator;
  }, {});

  // merge all same leave in one object of leavedata

  const resultArray = Object.keys(leaveSum).map((LeaveTranId) => ({
    LeaveTranId: parseInt(LeaveTranId),
    LeaveDays: leaveSum[LeaveTranId],
  }));

  const userLeaveNotSufficient = [],
    userLeaveInPendingNotSufficient = [];

  await Promise.all(
    leavedata.map(async (e) => {
      // check LWP and Absent or not
      const filterbalance = userleaveBalance.find(
        (f) => f.LeaveTranId == e.LeaveTranId
      );

      if (!filterbalance) return;

      // find latest lapse leave
      const lapseLeave = userWiseLeaveLapseOderBy.find(
        (lapse) => +e.LeaveTranId == lapse.LeaveTranId
      );

      if (lapseLeave) {
        const month = e.FromDate.slice(0, 4) + e.FromDate.slice(5, 7);

        // compare last lapse leave month and current leave month

        if (+lapseLeave.LapseYearMonth > +month) {
          const findBeforelapse = userWiseLeaveLapseOderBy.find(
            (lapse) =>
              +e.LeaveTranId == lapse.LeaveTranId &&
              LapseYearMonth < lapseLeave.LapseYearMonth
          );

          let startdate = '',
            enddate = '';

          const date =
            lapseLeave.LapseYearMonth.slice(0, 4) +
            '-' +
            lapseLeave.LapseYearMonth.slice(4, 6) +
            '-' +
            '01';

          const oneDayBefore = new Date(date);
          oneDayBefore.setDate(oneDayBefore.getDate() - 1);

          enddate = oneDayBefore.toISOString().slice(0, 10);

          if (findBeforelapse)
            startdate =
              findBeforelapse.LapseYearMonth.slice(0, 4) +
              '-' +
              findBeforelapse.LapseYearMonth.slice(4, 6) +
              '01';

          const pendingLeave = await employeePendingLeaveBalance(
            e.userMasterID,
            startdate,
            enddate,
            +e.LeaveTranId
          );

          const pendingLeavedays =
            +pendingLeave.length === 0 ? 0 : +pendingLeave[0].totalDays;

          const leave = resultArray.find((l) => l.LeaveTranId == e.LeaveTranId);

          const leavedays = leave ? +leave.LeaveDays : 0;
          if (+leavedays > +lapseLeave.LapseDays) {
            userLeaveNotSufficient.push(
              lapseLeave['hrLeaveType.LeaveMaster.LeaveName']
            );

            return;
          }

          // check if leave is add or update

          if (type == 'add') {
            if (+lapseLeave.LapseDays < +leavedays + +pendingLeavedays) {
              userLeaveInPendingNotSufficient.push(
                lapseLeave['hrLeaveType.LeaveMaster.LeaveName']
              );

              return;
            }
          }

          if (type == 'update') {
            const currentdays = currentLeave ? +currentLeave.LeaveDays : 0;

            if (
              +lapseLeave.LapseDays <
              +leavedays + +pendingLeavedays - +currentdays
            ) {
              userLeaveInPendingNotSufficient.push(
                lapseLeave['hrLeaveType.LeaveMaster.LeaveName']
              );

              return;
            }
          }
        } else {
          const startdate =
            lapseLeave.LapseYearMonth.slice(0, 4) +
            '-' +
            lapseLeave.LapseYearMonth.slice(4, 6) +
            '-' +
            '01';

          const userpendingLeave = await employeePendingLeaveBalance(
            +leavedata[0].userMasterID,
            startdate,
            '',
            +e.LeaveTranId
          );

          const pendingLeavedays =
            +userpendingLeave.length > 0 ? +userpendingLeave[0].totalDays : 0;

          const findBalance = userleaveBalance.find(
            (b) => b.LeaveTranId == e.LeaveTranId
          );

          const userBalance = findBalance ? +findBalance.Balance : 0;

          const leave = resultArray.find((l) => l.LeaveTranId == e.LeaveTranId);

          const leavedays = leave ? +leave.LeaveDays : 0;

          if (+userBalance < +leavedays) {
            userLeaveNotSufficient.push(
              lapseLeave['hrLeaveType.LeaveMaster.LeaveName']
            );
            return;
          }

          // check if leave is add or update

          if (type == 'add') {
            if (+userBalance < +leavedays + +pendingLeavedays) {
              userLeaveInPendingNotSufficient.push(
                lapseLeave['hrLeaveType.LeaveMaster.LeaveName']
              );
              return;
            }
          }

          if (type == 'update') {
            const currentdays = currentLeave ? +currentLeave.LeaveDays : 0;

            if (+userBalance < +leavedays + +pendingLeavedays - +currentdays) {
              userLeaveInPendingNotSufficient.push(filterbalance.leaveName);

              return;
            }
          }
        }
      } else {
        const userpendingLeave = await employeePendingLeaveBalance(
          +leavedata[0].userMasterID,
          '',
          '',
          +e.LeaveTranId
        );

        const pendingLeavedays =
          +userpendingLeave.length > 0 ? +userpendingLeave[0].totalDays : 0;

        const findBalance = userleaveBalance.find(
          (b) => b.LeaveTranId == e.LeaveTranId
        );

        const userBalance = findBalance ? +findBalance.Balance : 0;

        const leave = resultArray.find((l) => l.LeaveTranId == e.LeaveTranId);

        const leavedays = leave ? +leave.LeaveDays : 0;

        if (+userBalance < +leavedays) {
          userLeaveNotSufficient.push(filterbalance.leaveName);
          return;
        }

        // check if leave is add or update

        if (type == 'add') {
          if (+userBalance < +leavedays + +pendingLeavedays) {
            userLeaveInPendingNotSufficient.push(filterbalance.leaveName);
            return;
          }
        }
      }
    })
  );

  let message = '';

  if (+userLeaveNotSufficient.length > 0) {
    message = `You don't have sufficient leave balance of ${userLeaveNotSufficient[0]}.`;
  }

  if (+userLeaveInPendingNotSufficient.length > 0) {
    message = `You don't have sufficient leave balance of ${userLeaveInPendingNotSufficient[0]}. It is already used in leaves which are in pending state.`;
  }

  return message;
}
function employeeeLeaveBalanceNew(
  companyId,
  userId,
  userLapseleave,
  addbalanceData,
  usedBalanceData,
  leaveType
) {
  const finalAddBalance = [],
    finalUsedBalance = [];

  for (const data of leaveType) {
    // const lapsleave = userLapseleave.find(
    //   (e) => e.LeaveTranId == data.LeaveTranId
    // );

    // const condition = {};

    // const usedleaveCondition = {};

    // usedleaveCondition.status = 1;
    // usedleaveCondition.LeaveTranId = data.LeaveTranId;

    // condition.userMasterID = userId;
    // condition.LeaveTranId = data.LeaveTranId;

    // condition for lotlikar of CL

    let startdate = null;
    let enddate = null;
    let month = null;
    // Check For Specific Company
    if (companyId == 201 && data.LeaveID == 2) {
      startdate = new Date().toISOString().slice(0, 8) + '01';

      enddate =
        new Date().toISOString().slice(0, 8) +
        daysInMonth(
          new Date().toISOString().slice(5, 7),
          new Date().toISOString().slice(0, 4)
        );

      month =
        new Date().toISOString().slice(0, 4) +
        new Date().toISOString().slice(5, 7);

      // (condition.YearMM = +month),
      // usedleaveCondition.date = {
      //   [Op.between]: [startdate, enddate],
      // };
    } else {
      // if (lapsleave)
      //   (condition.YearMM = {
      //     [Op.gte]: +lapsleave.LapseYearMonth,
      //   }),
      //     (usedleaveCondition.date = {
      //       [Op.gte]:
      //         lapsleave.LapseYearMonth.slice(0, 4) +
      //         '-' +
      //         lapsleave.LapseYearMonth.slice(4, 6) +
      //         '-' +
      //         '01',
      //     });
    }

    const addbalance = addbalanceData.filter(
      (e) => e.LeaveTranId == data.LeaveTranId && (!month || e.YearMM == +month)
    );

    const usedBalance = usedBalanceData.filter(
      (e) =>
        e.LeaveTranId == data.LeaveTranId &&
        ((!startdate && !enddate) || (e.date >= startdate && e.date <= enddate))
    );

    if (+addbalance.length > 0) finalAddBalance.push(addbalance[0]);
    if (+usedBalance.length > 0) finalUsedBalance.push(usedBalance[0]);

    if (+addbalance.length == 0)
      finalAddBalance.push({
        userMasterID: userId,
        leaveName: data['LeaveMaster.LeaveName'],
        LeaveDesc: data['LeaveMaster.LeaveDesc'],
        LeaveTranId: data.LeaveTranId,
        Leave_CF: data.Leave_CF,
        LeaveID: data.LeaveID,
        totalDays: 0,
      });
    if (+usedBalance.length == 0)
      finalUsedBalance.push({
        userMasterID: userId,
        leaveName: data['LeaveMaster.LeaveName'],
        LeaveDesc: data['LeaveMaster.LeaveDesc'],
        LeaveTranId: data.LeaveTranId,
        Leave_CF: data.Leave_CF,
        LeaveID: data.LeaveID,
        totalDays: 0,
      });
  }

  const usedLeaveTotalDaysMap = Object.fromEntries(
    finalUsedBalance.map((item) => [
      item.LeaveTranId,
      parseFloat(item.totalDays),
    ])
  );

  const finalBalance = finalAddBalance.map((item) => {
    const usedLeaveValue = usedLeaveTotalDaysMap[item.LeaveTranId] || 0;

    const lapsleave = userLapseleave.find(
      (e) => e.LeaveTranId == item.LeaveTranId
    );

    const calculatedTotalDays =
      +item.totalDays -
      +usedLeaveValue -
      (lapsleave ? +lapsleave.totalDays : 0);

    const formattedTotalDays = calculatedTotalDays
      ? Number.isInteger(calculatedTotalDays)
        ? +calculatedTotalDays.toFixed(0)
        : +calculatedTotalDays % 1 === 0.2
          ? +calculatedTotalDays.toFixed(1)
          : +calculatedTotalDays.toFixed(2)
      : 0;

    const { totalDays, ...rest } = item;

    return {
      ...rest,
      Balance: formattedTotalDays == -0 ? 0 : formattedTotalDays,
    };
  });

  return finalBalance;
}

