function isBase64(str) {
  try {
    const base64Regex =
      /^([0-9a-zA-Z+/]{4})*(([0-9a-zA-Z+/]{2}==)|([0-9a-zA-Z+/]{3}=))?$/;
    const isBase64 = base64Regex.test(str);
    return isBase64;
  } catch (e) {
    return false;
  }
}
