async function employeReportToData(userMasterID) {
  const today = asiaKolkataDateTime(new Date()).slice(0, 10);

  const reportToData = await UserReportTO.findAll({
    where: {
      reportToID: userMasterID,
      status: 1,
    },
    attributes: ['userMasterID'],
    include: {
      model: UserMaster,
      as: 'employee',
      attributes: ['displayName', 'userNumber', 'photo', 'firstName'],
    },
  });
  return reportToData && reportToData.length > 0 ? reportToData : [];
}

const calculateDays = (startDate, endDate) => {
  // Parse the dates into JavaScript Date objects
  const start = new Date(startDate);
  const end = new Date(endDate);

  // Calculate the difference in time (milliseconds)
  const timeDifference = end - start;

  // Convert the difference from milliseconds to days
  const daysDifference = timeDifference / (1000 * 60 * 60 * 24);

  // Return the number of days
  return daysDifference + 1;
};

function getAllDatesBetween(fromDate, toDate) {
  const startDate = new Date(fromDate);
  const endDate = new Date(toDate);
  const dates = [];

  while (startDate <= endDate) {
    dates.push(new Date(startDate)); // Add current date
    startDate.setDate(startDate.getDate() + 1); // Move to the next day
  }

  return dates.map((date) => date.toISOString().split('T')[0]);
}

function ToformatAddress(userAddress) {
  let formatedAddress = '';
  if (userAddress) {
    if (userAddress.houseNumber)
      formatedAddress += `${userAddress.houseNumber},`;

    if (userAddress.houseName) formatedAddress += `${userAddress.houseName},`;

    if (userAddress.landmark) formatedAddress += `${userAddress.landmark},`;
    if (userAddress.area) formatedAddress += `${userAddress.area},`;
    if (userAddress.districtMaster && userAddress.districtMaster.districtName)
      formatedAddress += `${userAddress.districtMaster.districtName},`;
    if (userAddress.cityMaster && userAddress.cityMaster.cityName)
      formatedAddress += `${userAddress.cityMaster.cityName},`;
    if (
      userAddress.cityMaster &&
      userAddress.cityMaster.stateMaster &&
      userAddress.cityMaster.stateMaster.stateName
    )
      formatedAddress += `${userAddress.cityMaster.stateMaster.stateName},`;
    if (
      userAddress.cityMaster &&
      userAddress.cityMaster.stateMaster &&
      userAddress.cityMaster.stateMaster.countryMaster &&
      userAddress.cityMaster.stateMaster.countryMaster.countryName
    )
      formatedAddress += `${userAddress.cityMaster.stateMaster.countryMaster.countryName}`;
    if (userAddress.zipcode) formatedAddress += ` ${userAddress.zipcode}`;
  }
  return formatedAddress;
}

function getHTMLTemplate(type, fileExtension) {
  const file = path.join(__dirname, `../html/${type}.${fileExtension}`);
  return file;
}

function readHTMLFile(name) {
  return new Promise((resolve, reject) => {
    fs.readFile(name, 'utf-8', (err, result) => {
      if (err) {
        reject(err);
      } else {
        resolve(result);
      }
    });
  });
}

async function generateHTMLToPDF_base64Path(
  pdfData,
  htmlFileName,
  pageType,
  fileExtension
) {
  Handlebars.registerHelper({
    eq: (v1, v2) => v1 === v2,
    ne: (v1, v2) => v1 !== v2,
    lt: (v1, v2) => v1 < v2,
    gt: (v1, v2) => v1 > v2,
    lte: (v1, v2) => v1 <= v2,
    gte: (v1, v2) => v1 >= v2,
    and() {
      return Array.prototype.every.call(arguments, Boolean);
    },
    or() {
      return Array.prototype.slice.call(arguments, 0, -1).some(Boolean);
    },
  });

  const filePath = getHTMLTemplate(htmlFileName, fileExtension);

  const file = await readHTMLFile(filePath);
  const template = Handlebars.compile(file);
  const html = template(pdfData);

  const browser = await puppeteer.launch({
    headless: 'new',
    args: ['--no-sandbox'],
  });
  const page = await browser.newPage();

  // Set the HTML content of the page
  await page.setContent(html);

  // Generate PDF
  const pdfBuffer = await page.pdf({
    format: 'A4', // Page format (A4 in this case)
    printBackground: true, // print background
    landscape: pageType == 'landscape' ? true : false,
    timeout: 120000,
  });
  await browser.close();

  let base64path = Buffer.from(pdfBuffer).toString('base64');

  return base64path;
}

function calculateTotalSalary(salaryData, fieldSrNo) {
  return salaryData
    .filter(function (item) {
      return item.salaryFieldSrNo === fieldSrNo;
    })
    .reduce(function (sum, item) {
      return sum + item.EmployeeSalaryAmount;
    }, 0);
}

function findDayName(date) {
  const dayname = new Date(date).toLocaleString('en-us', {
    weekday: 'long',
  });

  return dayname;
}

async function generateLetterHTMLToPDF_base64Path(htmlData, pageType) {
  Handlebars.registerHelper({
    eq: (v1, v2) => v1 === v2,
    ne: (v1, v2) => v1 !== v2,
    lt: (v1, v2) => v1 < v2,
    gt: (v1, v2) => v1 > v2,
    lte: (v1, v2) => v1 <= v2,
    gte: (v1, v2) => v1 >= v2,
    and() {
      return Array.prototype.every.call(arguments, Boolean);
    },
    or() {
      return Array.prototype.slice.call(arguments, 0, -1).some(Boolean);
    },
  });

  const html = htmlData;

  const browser = await puppeteer.launch({
    headless: 'new',
    args: ['--no-sandbox'],
  });
  const page = await browser.newPage();

  // Set the HTML content of the page
  await page.setContent(html);

  // Generate PDF
  const pdfBuffer = await page.pdf({
    format: 'A4', // Page format (A4 in this case)
    printBackground: true, // print background
    landscape: pageType == 'landscape' ? true : false,
    timeout: 120000,
  });
  await browser.close();

  let base64path = Buffer.from(pdfBuffer).toString('base64');

  return base64path;
}

function addPageBreak(letterData) {
  if (!letterData) return letterData;
  const PageBreak = '[PageBreak]';
  letterData = letterData
    .split(`<div class="pageBreak"> </div>`)
    .join(PageBreak);

  return letterData;
}

function addSalaryStructureKeyword(letterData) {
  if (!letterData) return letterData;
  // Define the substring to match
  let substring = 'NameGroupAmount(Monthly)';

  // Replace all occurrences of the substring
  let occurrences = letterData.split(substring).length - 1;
  for (let i = 0; i < occurrences; i++) {
    let type = 'SalaryStructure';

    // Find the index of the substring in the letterData string
    let index = letterData.indexOf(substring);

    // If the substring is found
    if (index !== -1) {
      // Find the start and end indices of the <p> tag enclosing the substring
      let startTagIndex = letterData.lastIndexOf('<p', index);
      let endTagIndex = letterData.indexOf('</p>', index) + '</p>'.length;

      // Extract the content between the start and end indices
      let contentBefore = letterData.substring(0, startTagIndex);
      let contentAfter = letterData.substring(endTagIndex);

      // Replace the entire <p> tag with the substring enclosed within square brackets
      letterData = contentBefore + '[' + type + ']' + contentAfter;
    }
  }

  return letterData;
}

function onTableHtmlAddSalaryStructureKeyword(letterData) {
  if (!letterData) return letterData;
  // Define the substring to match
  let substring1 = 'SalaryStructureOfUser';

  // Replace all occurrences of the substring
  let occurrences1 = letterData.split(substring1).length - 1;
  for (let i = 0; i < occurrences1; i++) {
    let type = 'SalaryStructure';

    // Find the index of the substring in the letterData.offerletterHTML string
    let index = letterData.indexOf(substring1);

    // If the substring is found
    if (index !== -1) {
      // Find the start and end indices of the <p> tag enclosing the substring
      let startTagIndex = letterData.lastIndexOf('<table', index);
      let endTagIndex =
        letterData.indexOf('</table>', index) + '</table>'.length;

      // Extract the content between the start and end indices
      let contentBefore = letterData.substring(0, startTagIndex);
      let contentAfter = letterData.substring(endTagIndex);

      // Replace the entire <p> tag with the substring enclosed within square brackets
      letterData = contentBefore + '[' + type + ']' + contentAfter;
    }
  }

  return letterData;
}
function nearestPastDate(dateArr, date) {
  const pastArr = dateArr.filter((n) => n <= date);
  return pastArr.length > 0 ? pastArr[pastArr.length - 1] : null;
}
function nearestFutureDate(dateArr, date) {
  const futArr = dateArr.filter((n) => n >= date);
  return futArr.length > 0 ? futArr[0] : null;
}
function getSubstractedDate(date, days) {
  // Make Sure Date is in "YYYY-MM-DD" Format
  return moment(date, 'YYYY-MM-DD').subtract(days, 'days').format('YYYY-MM-DD');
}

// skill category wise attendance calculation data

function getAttendanceCal_DataBySkillCategory(array = []) {
  const finalAttendanceData = [];
  array.forEach((e) => {
    const obj = {
      category: e.employeeSkillCategories?.[0]?.skillCategory || '',
      days: 0,
      salaryData: e.hrSalaryTrasactions || [],
    };

    const act = e.employeeJoiningDetails?.[0]?.salaryCalculationAct || '';

    switch (act) {
      case 'W':
        obj['days'] = [...e.hrLeaveMonthlyTrans]
          .filter((f) => ![7, 9].includes(f.hrLeaveType.LeaveID))
          .reduce((acc, obj) => acc + +obj.AttnVal, 0);
        break;
      case 'F':
        obj['days'] = [...e.hrLeaveMonthlyTrans]
          .filter((f) => ![7].includes(f.hrLeaveType.LeaveID))
          .reduce((acc, obj) => acc + +obj.AttnVal, 0);
        break;
      default:
        obj['days'] = [...e.hrLeaveMonthlyTrans].reduce(
          (acc, obj) => acc + +obj.AttnVal,
          0
        );
        break;
    }

    finalAttendanceData.push(obj);
  });
  return finalAttendanceData;
}
async function getHTMLFileData(pdfData, htmlFileName, fileExtension) {
  Handlebars.registerHelper({
    eq: (v1, v2) => v1 === v2,
    ne: (v1, v2) => v1 !== v2,
    lt: (v1, v2) => v1 < v2,
    gt: (v1, v2) => v1 > v2,
    lte: (v1, v2) => v1 <= v2,
    gte: (v1, v2) => v1 >= v2,
    and() {
      return Array.prototype.every.call(arguments, Boolean);
    },
    or() {
      return Array.prototype.slice.call(arguments, 0, -1).some(Boolean);
    },
  });

  const filePath = getHTMLTemplate(htmlFileName, fileExtension);

  const file = await readHTMLFile(filePath);
  const template = Handlebars.compile(file);
  const html = template(pdfData);

  return html;
}
