async function add_WeekOffHoliday_With_Transaction(
  companyMasterID,
  userMasterID,
  startDate,
  weekoffPolicyID,
  holidayPolicyID,
  returnValue = false,
  endDate = null,
  transaction
) {
  try {
    let returnArray;
    const companySubscription = await findCompanySubscription_transaction(
      companyMasterID,
      transaction
    );
    if (!companySubscription) return;
    const today = asiaKolkataDateTime(new Date()).slice(0, 10);
    let start_Date;
    let end_Date = endDate
      ? asiaKolkataDateTime(endDate).slice(0, 10)
      : asiaKolkataDateTime(companySubscription.endDate).slice(0, 10);
    let weekoffDates = [];
    let holidayDates = [];

    if (userMasterID.length > 0) {
      //only current user weekoffHoliday till subscription EndDate

      start_Date = startDate;
      for (const user of userMasterID) {
        weekoffDates = [];
        holidayDates = [];

        if (weekoffPolicyID)
          weekoffDates = await getWeekoffDates(
            weekoffPolicyID,
            start_Date,
            end_Date,
            user,
            transaction
          );
        if (holidayPolicyID)
          holidayDates = await getHolidayDates(
            holidayPolicyID,
            start_Date,
            end_Date,
            user,
            transaction
          );

        const insertdata =
          weekoffPolicyID && holidayPolicyID
            ? [...weekoffDates, ...holidayDates]
            : weekoffPolicyID
              ? weekoffDates
              : holidayDates;

        if (returnValue) {
          returnArray = insertdata;
        } else {
          await weekoffHolidayTran.destroy(
            {
              where: {
                userMasterID: user,
                date: {
                  [Sequelize.Op.and]: [
                    { [Sequelize.Op.gte]: start_Date },
                    { [Sequelize.Op.lte]: end_Date },
                  ],
                },
                tableName:
                  weekoffPolicyID && holidayPolicyID
                    ? ['weekoff', 'holiday']
                    : weekoffPolicyID
                      ? 'weekoff'
                      : 'holiday',
              },
            },
            { transaction }
          );

          await weekoffHolidayTran.bulkCreate(insertdata, { transaction });
        }
      }
    } else {
      //All users weekoffHoliday till subscription EndDate
      const get_one_data = await companyMaster.findAll({
        where: {
          [Sequelize.Op.or]: [
            { companyMasterID: +companyMasterID },
            { parentCompanyMasterID: +companyMasterID },
          ],
          status: [0, 1],
        },
      });

      const companyMasterIDs = get_one_data.map((e) => e.companyMasterID);

      const findAllUsers = await UserMaster.findAll({
        where: {
          companyMasterId: companyMasterIDs,
          status: 1,
        },
      });
      const findAllUserIDs = findAllUsers.map((e) => e.userMasterID);
      const getWeekoffPolicyByUsers = await EmployeeWeekOff.findAll({
        where: {
          userMasterID: findAllUserIDs,
          status: 1,
          applicableDate: {
            [Sequelize.Op.lte]: today,
          },
          [Sequelize.Op.or]: [
            {
              endDate: {
                [Sequelize.Op.gte]: today,
              },
            },
            {
              endDate: { [Sequelize.Op.eq]: null },
            },
          ],
        },
        include: [
          {
            model: weekOffPolicy,
            as: 'weekoff',
          },
        ],
      });

      for (let companyMasterID of companyMasterIDs) {
        const companyWiseUsers = findAllUsers.filter(
          (e) => e.companyMasterId == companyMasterID
        );
        for (const user of companyWiseUsers) {
          weekoffDates = [];
          const userWeekOffPolicy = getWeekoffPolicyByUsers.find(
            (e) => e.userMasterID == user.userMasterID
          );
          if (!userWeekOffPolicy) continue;

          const LastWeekOffHoliday = await getLastWeekOffHoliday(
            user.userMasterID,
            'weekoff',
            end_Date
          );
          start_Date = LastWeekOffHoliday
            ? LastWeekOffHoliday.date
            : userWeekOffPolicy.applicableDate;
          weekoffDates = await getWeekoffDates(
            userWeekOffPolicy.weekOffPolicyID,
            start_Date,
            end_Date,
            user.userMasterID,
            transaction
          );

          await weekoffHolidayTran.destroy(
            {
              where: {
                userMasterID: user.userMasterID,
                date: {
                  [Sequelize.Op.and]: [
                    { [Sequelize.Op.gte]: start_Date },
                    { [Sequelize.Op.lte]: end_Date },
                  ],
                },
                tableName: 'weekoff',
              },
            },
            { transaction }
          );

          const insertdata = weekoffDates;

          await weekoffHolidayTran.bulkCreate(insertdata, { transaction });
        }
      }
    }

    if (returnValue) return returnArray;
  } catch (error) {
    throw new Error('Error in Add Week off: ' + error.message);
  }
}

async function findCompanySubscription_transaction(
  companyMasterID,
  transaction
) {
  const parentCompany = await companyMaster.findOne({
    raw: true,
    where: {
      companyMasterID: companyMasterID,
      status: 1,
    },
    transaction,
  });

  if (parentCompany && parentCompany.parentCompanyMasterID != 0)
    companyMasterID = parentCompany.parentCompanyMasterID;

  const getCompanySubscription = await CompanySubscriptionMaster.findOne({
    raw: true,
    where: {
      companyMasterID: companyMasterID,
      status: 1,
    },
    transaction,
  });

  return getCompanySubscription;
}

async function coff_addLeave_Manual(
  attendancePolicy,
  attendanceData,
  createBy,
  createByIp,
  companyMasterID,
  total_In_Hrs,
  transaction
) {
  try {
    if (attendancePolicy.coffhalfday && attendancePolicy.cofffullday) {
      // let total_In_Hrs = +get_one_data.InHrs / 60;
      // let total_In_Hrs = +attendanceData.InHrs;

      let coffValue = 0;

      if (
        total_In_Hrs >= Number(attendancePolicy.coffhalfday) &&
        total_In_Hrs < Number(attendancePolicy.cofffullday)
      ) {
        coffValue = 0.5;
      } else if (
        total_In_Hrs >= Number(attendancePolicy.cofffullday) &&
        (!attendancePolicy.coffOneAndHalfDay ||
          total_In_Hrs < Number(attendancePolicy.coffOneAndHalfDay))
      ) {
        coffValue = 1;
      } else if (
        attendancePolicy.coffOneAndHalfDay &&
        total_In_Hrs >= Number(attendancePolicy.coffOneAndHalfDay) &&
        (!attendancePolicy.coffTwoFullDay ||
          total_In_Hrs < Number(attendancePolicy.coffTwoFullDay))
      ) {
        coffValue = 1.5;
      } else if (
        attendancePolicy.coffTwoFullDay &&
        total_In_Hrs >= Number(attendancePolicy.coffTwoFullDay)
      ) {
        coffValue = 2;
      }

      if (coffValue > 0) {
        await addCoff_Manual(
          attendanceData.userMasterID,
          attendanceData.AttendanceDate,
          coffValue,
          createBy,
          createByIp,
          companyMasterID,
          transaction
        );
      }
    }
  } catch (error) {
    throw new Error('Error in add Leave_Weekoff: ' + error.message);
  }
}

