function checkLeaveOnWH(leave = [], WH = []) {
  const leaveMap = new Map(leave.map((item) => [item.date, item.days]));

  const filteredArray = WH.filter((item) => {
    const daysInArray2 = leaveMap.get(item.date);
    return !(
      daysInArray2 === 1 ||
      (item.value === 1 && daysInArray2 !== undefined)
    );
  });

  return filteredArray;
}

