async function attendanceCalculation1(
  userMasterData,
  month,
  leftdate,
  Allleave_type = []
) {
  const userMasterID = userMasterData.userMasterID;
  const companyMasterID = userMasterData.companyMasterId;

  let year, Month, monday;

  if (leftdate) {
    year = String(leftdate).slice(0, 4);
    Month = String(leftdate).slice(5, 7);
    monday = daysInMonth(Month, year);
  } else {
    year = String(month).slice(0, 4);
    Month = String(month).slice(4, 6);
    monday = daysInMonth(Month, year);
  }

  const finaldata1 = [];
  let overtimeAdded = '';

  //--------------------------Employee salary policy ----------------------

  const user_salaryPolicy =
    userMasterData.employeeSalaryPolicies?.[0]?.salaryPolicy || null;

  let end_date,
    start_date,
    calculateon,
    paidSalary = false;

  // ----------- set start date and end date according to salary policy -------

  if (user_salaryPolicy) {
    calculateon = user_salaryPolicy.salarycalculationBasedon;
    overtimeAdded = user_salaryPolicy.overtimeAdded;

    let date = user_salaryPolicy.salaryCycleDate;

    date = (date < 10 ? '0' : '') + date;

    let leftdate1 = String(leftdate).slice(8, 10);

    start_date = year + '-' + Month + '-' + date;

    if (leftdate) {
      if (leftdate1 < date) {
        Month = Month - 1;
        Month = (Month < 10 ? '0' : '') + Month;
      }

      start_date = year + '-' + Month + '-' + date;

      end_date = leftdate;
    } else {
      // To Check salary consider Month

      if (user_salaryPolicy.salaryCycleConsider == 'E') {
        const tempDate = new Date(start_date);
        tempDate.setMonth(tempDate.getMonth() - 1);

        start_date =
          tempDate.getFullYear() +
          '-' +
          String(tempDate.getMonth() + 1).padStart(2, '0') +
          '-' +
          String(tempDate.getDate()).padStart(2, '0');

        // set Month days
        monday = daysInMonth(start_date.slice(5, 7), start_date.slice(0, 4));
      }

      let date1 = new Date(start_date);
      date1.setDate(date1.getDate() + (monday - 1));

      end_date =
        date1.getFullYear() +
        '-' +
        String(date1.getMonth() + 1).padStart(2, '0') +
        '-' +
        String(date1.getDate()).padStart(2, '0');
    }
  } else {
    start_date = year + '-' + Month + '-' + '01';
    end_date = leftdate ? leftdate : year + '-' + Month + '-' + monday;
  }

  // month Name

  const month1 = month_dict[Month];
  const yearmonth = month1 + ' ' + year;

  // Employee joining Details
  const empjoining = userMasterData.employeeJoiningDetails?.[0] || null;

  // Attendance calculation data
  const userAttnCalData = userMasterData.hrLeaveMonthlyTrans || [];

  let joining = false,
    left = false,
    notJoin = false,
    FNF = false;

  let coffValue = 0;

  if (empjoining) {
    if (
      empjoining.joiningDate > start_date &&
      empjoining.joiningDate <= end_date
    ) {
      start_date = empjoining.joiningDate;
    }
    // not join yet
    if (empjoining.joiningDate > end_date) {
      notJoin = true;
    }

    // end date
    if (empjoining.leavingDate) {
      if (
        empjoining.leavingDate <= end_date &&
        empjoining.leavingDate >= start_date
      ) {
        end_date = empjoining.leavingDate;
        FNF = true;
      }
      // left employee
      if (empjoining.leavingDate < start_date) {
        left = true;
      }
    }

    if (start_date > end_date || left || notJoin) {
      (start_date = ''), (end_date = '');
    } else {
      joining = true;
    }
  }

  if (joining) {
    // start date

    // -------------find if data is vaerified -------------------
    const leavedata2 = userAttnCalData.filter((e) => +e.verified == 1);

    if (leavedata2.length) {
      (end_date = leavedata2[0].monthenddate || end_date),
        (start_date = leavedata2[0].monthstartdate || start_date);
    }

    let start_Date1 = new Date(start_date);
    let end_Date1 = new Date(end_date);

    let timeDifference = start_Date1.getTime() - end_Date1.getTime();
    let dayMilliSeconds = 1000 * 60 * 60 * 24;
    let totalDays = Math.abs(timeDifference / dayMilliSeconds); // it returns negative value if start date < end date
    totalDays = Math.floor(totalDays + 1); // to get complete

    const branch =
      (userMasterData.employeeBranches || []).find(
        (e) =>
          new Date(e.applicableDate) <= new Date(end_date) &&
          (new Date(e.endDate) >= new Date(end_date) || !e.endDate)
      )?.branchMaster || null;
    const department =
      (userMasterData.employeeDepartments || []).find(
        (e) =>
          new Date(e.applicableDate) <= new Date(end_date) &&
          (new Date(e.endDate) >= new Date(end_date) || !e.endDate)
      )?.department || null;
    const designation =
      (userMasterData.employeeDesignations || []).find(
        (e) =>
          new Date(e.applicableDate) <= new Date(end_date) &&
          (new Date(e.endDate) >= new Date(end_date) || !e.endDate)
      )?.designation || null;
    const user_attendancePolicy =
      (userMasterData.employeeAttendancePolicies || []).find(
        (e) =>
          new Date(e.startDate) <= new Date(end_date) &&
          (new Date(e.endDate) >= new Date(end_date) || !e.endDate)
      )?.attendancePolicy || null;

    const weekOffHolidayPriority = user_attendancePolicy?.WHPHPriority || null;

    // attendance and Salary data--------------------
    const find_usersalary = await getSalaryData(userMasterID, month);

    const SalaryDone = find_usersalary.length ? 'Y' : 'N';
    const finalpenaltyArray = [];
    let monthly_Workingminutes = 0;
    let daily_workingminutes = 0;

    // declare attendancedata and it's flag

    let attendancedata = [],
      findAttendanceFlag = false;

    if (calculateon == 'hourwise') {
      if (!user_salaryPolicy.monthlyFixhours) {
        if (!user_salaryPolicy.dailyFixhours) {
          findAttendanceFlag = true;
          attendancedata = await getAttendanceData(
            userMasterID,
            start_date,
            end_date,
            true
          );

          if (+attendancedata.length > 0) {
            monthly_Workingminutes =
              +attendancedata[attendancedata.length - 1].Shifthrs *
              +monday *
              60;
            daily_workingminutes =
              +attendancedata[attendancedata.length - 1].Shifthrs * 60;
          } else {
            const shift = await employeeShift(userMasterID, end_date, '');

            if (shift) {
              const shifttime = await ShiftTIme.findOne({
                where: {
                  shiftID: shift.shiftID,
                },
              });

              if (shifttime) {
                (monthly_Workingminutes = +shifttime.totalhours * +monday * 60),
                  (daily_workingminutes = +shifttime.totalhours * 60);
              }
            }
          }
        } else {
          monthly_Workingminutes =
            Number(user_salaryPolicy.dailyFixhours) * Number(monday) * 60;
          daily_workingminutes = Number(user_salaryPolicy.dailyFixhours) * 60;
        }
      } else {
        monthly_Workingminutes = Number(user_salaryPolicy.monthlyFixhours) * 60;
        daily_workingminutes = Number(monthly_Workingminutes) / Number(monday);
      }
    }

    const typeCondition =
      weekOffHolidayPriority === 'PH' ? "'holiday'" : "'weekoff'";

    if (+find_usersalary.length == 0 && +leavedata2.length == 0) {
      // Penalty Calculation

      let penaltyDays = 0,
        penaltyMin = 0,
        penaltyAmount = 0,
        penaltyPercent = 0,
        addPenalty = true;

      // If attendance data hasn't been found yet, fetch it using getAttendanceData
      if (!findAttendanceFlag)
        attendancedata = await getAttendanceData(
          userMasterID,
          start_date,
          end_date,
          true
        );

      attendancedata.forEach((e) => {
        const processPenalty = (type) => {
          const value = +e[type];
          const deductionType = e[`${type}Deduction`];

          if (
            value &&
            deductionType &&
            ['min', 'amount', 'day', 'percent'].includes(deductionType)
          ) {
            switch (deductionType) {
              case 'min':
                penaltyMin += +value;
                break;
              case 'amount':
                penaltyAmount += +value;
                break;
              case 'day':
                penaltyDays += +value;
                break;
              case 'percent':
                penaltyPercent += +value;
                break;
            }
          }
        };

        processPenalty('Panalty');
        processPenalty('goEarlyPanalty');
      });

      // if full month present or company is asopalav
      if (
        empjoining.fullMonthPresence == 1 ||
        [277, 298, 300].includes(+companyMasterID)
      )
        penaltyDays = 0;

      // LCEG Policy
      const LCEGPolicy =
        (userMasterData.employeeLateEarlyPolicies || []).find(
          (e) =>
            new Date(e.startDate) <= new Date(end_date) &&
            (new Date(e.endDate) >= new Date(end_date) || !e.endDate)
        )?.lateEarlyPolicy || null;

      // find Weekoff Policy
      const weekoffPolicy =
        (userMasterData.employeeWeekOffs || []).find(
          (e) =>
            new Date(e.applicableDate) <= new Date(end_date) &&
            (new Date(e.endDate) >= new Date(end_date) || !e.endDate)
        )?.weekoff || null;

      const weekoffPolicyType = weekoffPolicy?.weekoffType || null;

      const WH_Condition = {
        userMasterID: userMasterID,
        date: {
          [Sequelize.Op.between]: [start_date, end_date],
        },
        tableName: 'holiday',
        [Sequelize.Op.and]: Sequelize.literal(`(date, "tableName") IN (
                SELECT date, "tableName"
                FROM "weekoffHolidayTrans"
                WHERE "userMasterID" = ${userMasterID}
                  AND date BETWEEN '${start_date}' AND '${end_date}'
                  AND ("optionalHoliday" IS FALSE OR "optionalHoliday" IS NULL) AND "tableName"='holiday'
                GROUP BY date,"tableName"
              )`),
      };

      let weekoffCount = 0,
        checkWeekoff = true,
        weekoffValue = 0;

      // find Weekoff
      if (
        weekoffPolicy &&
        weekoffPolicyType &&
        !weekoffPolicy.isNoWeekoffPolicy
      ) {
        // if monthly fix weekoff or on present days
        if (
          [weekoffTypeEnum.MONTHLYFIX, weekoffTypeEnum.ONPRESENTDAY].includes(
            weekoffPolicyType
          )
        ) {
          weekoffCount =
            weekoffPolicyType == weekoffTypeEnum.MONTHLYFIX
              ? +weekoffPolicy.monthlyFix
              : 0;

          // set value
          weekoffValue =
            weekoffPolicyType == weekoffTypeEnum.MONTHLYFIX
              ? +weekoffPolicy.monthlyFix
              : +weekoffPolicy.presentDays;

          checkWeekoff = false;
        }

        // if fix weekoff
        if (weekoffPolicyType == weekoffTypeEnum.FIX) {
          //delete tablename
          delete WH_Condition.tableName;

          WH_Condition[Sequelize.Op.and] =
            Sequelize.literal(`(date, "tableName") IN (
                          SELECT date, 
                                 CASE 
                                   WHEN SUM(CASE WHEN "tableName" = 'weekoff' THEN 1 ELSE 0 END) > 0 
                                        AND SUM(CASE WHEN "tableName" = 'holiday' THEN 1 ELSE 0 END) > 0 
                                   THEN MAX(CASE WHEN "tableName" = ${typeCondition} THEN "tableName" END)
                                   ELSE MAX("tableName") 
                                 END AS selected_tableName
                          FROM "weekoffHolidayTrans"
                          WHERE "userMasterID" = ${userMasterID}
                            AND date BETWEEN '${start_date}' AND '${end_date}'
                            AND ("optionalHoliday" IS FALSE OR "optionalHoliday" IS NULL)
                          GROUP BY date
                        )`);
        }
      } else {
        // if no weekoff policy

        //delete tablename
        delete WH_Condition.tableName;

        WH_Condition[Sequelize.Op.and] =
          Sequelize.literal(`(date, "tableName") IN (
                          SELECT date, 
                                 CASE 
                                   WHEN SUM(CASE WHEN "tableName" = 'weekoff' THEN 1 ELSE 0 END) > 0 
                                        AND SUM(CASE WHEN "tableName" = 'holiday' THEN 1 ELSE 0 END) > 0 
                                   THEN MAX(CASE WHEN "tableName" = ${typeCondition} THEN "tableName" END)
                                   ELSE MAX("tableName") 
                                 END AS selected_tableName
                          FROM "weekoffHolidayTrans"
                          WHERE "userMasterID" = ${userMasterID}
                            AND date BETWEEN '${start_date}' AND '${end_date}'
                            AND ("optionalHoliday" IS FALSE OR "optionalHoliday" IS NULL)
                          GROUP BY date
                        )`);
      }

      const queryArray = [
        weekoffHolidayTran.findAll({
          raw: true,
          where: WH_Condition,
          order: [
            ['date', 'ASC'],
            ['tableName', 'DESC'],
          ],
        }),
        UserLeaveTransaction.findAll({
          where: {
            date: {
              [Sequelize.Op.between]: [start_date, end_date],
            },
            status: 1,
          },
          include: [
            {
              required: true,
              model: UserLeave,
              where: { userMasterID: userMasterID, status: 1 },
              attributes: ['DayType'],
            },
            {
              required: true,
              model: HrLeaveTypes,
              attributes: ['LeaveID'],
            },
          ],
        }),
      ];

      // if attendance data not find
      if (!findAttendanceFlag)
        queryArray.push(
          getAttendanceData(userMasterID, start_date, end_date, true)
        );

      // find weekoff holiday and leaves
      const resultArray = await Promise.all(queryArray);

      const weekoffholidays = resultArray[0];
      const leave = resultArray[1];

      if (!findAttendanceFlag) attendancedata = resultArray[2];

      const finalweekoffholidays = await toGetFinalHolidayWeekoff(
        attendancedata,
        user_attendancePolicy,
        weekoffholidays,
        leave,
        start_date,
        end_date,
        userMasterID
      );

      let actual_Weekoff = [],
        finalWeekoffs = [];

      // if check weekoff is true
      if (checkWeekoff) {
        actual_Weekoff = weekoffholidays.filter(
          (e) => e.tableName == 'weekoff'
        );

        finalWeekoffs = checkLeaveOnWH(leave, finalweekoffholidays.weekoffs);
      }

      const actual_holiday = weekoffholidays.filter(
        (e) => e.tableName == 'holiday'
      );

      // filter week off and holiday where leave dates are exist

      let finalHolidays = checkLeaveOnWH(leave, finalweekoffholidays.holidays);

      // Set For All Final Earning weekoff Data
      const final_Weekoffs = finalWeekoffs;

      // condition for Asopalav
      let sundays = 0;
      if (
        companyMasterID == 277 ||
        companyMasterID == 298 ||
        companyMasterID == 300
      ) {
        sundays = +finalWeekoffs.length;
        finalWeekoffs = [];
      }

      // condition for SRI VAISHNAVI RETAIL (INDIA) LLP
      if (companyMasterID == 237) {
        const finalholiday = [];

        // Merge arrays based on the date
        finalHolidays.map((holiday) => {
          const correspondingAttendance = attendancedata.find(
            (attendance) => attendance.AttendanceDate == holiday.date
          );

          if (correspondingAttendance) {
            finalholiday.push({
              ...holiday,
              value: correspondingAttendance.fulldayhalfday,
            });
          }
        });

        finalHolidays = finalholiday;

        // finalHolidays = finalHolidays.filter(holiday => attendancedata.some(attendance => attendance.AttendanceDate === holiday.date));
      }
      const combinedboth = [...actual_Weekoff, ...actual_holiday];

      // for hourly attendance calculation

      if (calculateon == 'hourwise') {
        // push LECEG penalty

        if (+penaltyDays > 0)
          finalpenaltyArray.push(
            PenaltyAddInArray('Attendance Penalty(Days)', 'day', penaltyDays)
          );
        if (+penaltyAmount > 0)
          finalpenaltyArray.push(
            PenaltyAddInArray(
              'Attendance Penalty(Amt)',
              'amount',
              penaltyAmount
            )
          );
        if (+penaltyPercent > 0)
          finalpenaltyArray.push(
            PenaltyAddInArray(
              'Attendance Penalty(Per)',
              'percent',
              penaltyPercent
            )
          );

        if (
          LCEGPolicy?.lateEarlyPolicyType != 'noLcEgPolicy' &&
          LCEGPolicy?.deductFrom == PenaltyDeductFromEnum.SALARY &&
          +penaltyMin > 0
        ) {
          addPenalty = false;
          finalpenaltyArray.push(
            PenaltyAddInArray('Attendance Penalty(Min)', 'min', penaltyMin)
          );
        }

        let workingminutes = attendancedata.reduce(
          (acc, obj) => acc + +obj.roundOffMinutes,
          0
        );

        if (user_salaryPolicy.overtimeAdded == 'daily') {
          workingminutes = attendancedata.reduce(
            (acc, obj) => acc + +obj.withoutOtMinutes,
            0
          );
        }

        if (user_salaryPolicy.holidayHours == 'Y') {
          const holiday_sum = finalHolidays.reduce((acc, obj) => {
            return acc + +obj.value;
          }, 0);

          const holidayminutes =
            Number(holiday_sum) * Number(daily_workingminutes);

          workingminutes = Number(workingminutes) + Number(holidayminutes);
        }

        if (user_salaryPolicy.weekoffHours == 'Y') {
          const weekoff_sum = finalWeekoffs.reduce((acc, obj) => {
            return acc + +obj.value;
          }, 0);

          const weekoffminutes =
            Number(weekoff_sum) * Number(daily_workingminutes);

          workingminutes = Number(workingminutes) + Number(weekoffminutes);
        }

        if (user_salaryPolicy.leaveHours == 'Y') {
          const leaveBalance = await HrLeaveBalance.findAll({
            raw: true,
            where: {
              userMasterID: userMasterID,
              YearMM: month,
            },
          });

          const finalleave = leaveBalance.reduce((acc, obj) => {
            return acc + Number(obj.LeaveAddNew);
          }, 0);

          const leaveminutes =
            Number(finalleave) * Number(daily_workingminutes);

          workingminutes = Number(workingminutes) + Number(leaveminutes);
        }

        if (user_salaryPolicy.breakHours == 'N') {
          if (attendancedata.length > 0) {
            let breaktime = [];

            for (let a = 0; a < attendancedata.length; a++) {
              if (
                attendancedata[a].OutDateTime != null &&
                attendancedata[a].OutDateTime != ''
              ) {
                const day = getDayOfWeek(attendancedata[a].AttendanceDate);

                const find_shift = [...attendancedata[a].shift.shiftTimes].find(
                  (e) => e.day == day
                );

                if (find_shift) {
                  const startbreak =
                    attendancedata[a].AttendanceDate +
                    ' ' +
                    find_shift.secondhalfstarttime;

                  const endbreak =
                    attendancedata[a].AttendanceDate +
                    ' ' +
                    find_shift.firsthalfendtime;

                  const date =
                    new Date(startbreak).getTime() -
                    new Date(endbreak).getTime();

                  const min = Number(date) / (60 * 1000);

                  breaktime.push(min);
                }
              }
            }

            const totalbreaktime = breaktime.reduce((acc, obj) => {
              return acc + obj;
            }, 0);

            workingminutes = Number(workingminutes) - Number(totalbreaktime);
          }
        }

        if (penaltyMin > 0 && addPenalty) {
          workingminutes = Number(workingminutes) - Number(penaltyMin);
        }

        workingminutes = Math.round(workingminutes);

        let otminutes;
        let showworkingminutes;

        if (workingminutes > monthly_Workingminutes) {
          if (user_salaryPolicy.overtimeAdded == 'daily') {
            otminutes = 0;
            showworkingminutes = Number(monthly_Workingminutes);
          } else {
            otminutes = Number(workingminutes) - Number(monthly_Workingminutes);
            showworkingminutes = Number(monthly_Workingminutes);
          }
        } else {
          showworkingminutes = Number(workingminutes);
          otminutes = 0;
        }

        // remove Absent
        const leave_type = Allleave_type.filter((e) => e.LeaveID != 5);

        let user_leave = [];
        let leave_data = 0;
        let weekoffholiday = 0;

        for (let j = 0; j < leave_type.length; j++) {
          if (leave_type[j].LeaveID == 20) {
            user_leave.push(
              AddLeaveTypesInArray(
                leave_type[j].LeaveMaster.LeaveName,
                leave_type[j].LeaveMaster.LeaveDesc,
                leave_type[j].LeaveID,
                Math.round(+showworkingminutes),
                leave_type[j].LeaveTranId,
                userMasterID,
                month,
                monday
              )
            );
          } else if (leave_type[j].LeaveID == 21) {
            user_leave.push(
              AddLeaveTypesInArray(
                leave_type[j].LeaveMaster.LeaveName,
                leave_type[j].LeaveMaster.LeaveDesc,
                leave_type[j].LeaveID,
                Math.round(+otminutes),
                leave_type[j].LeaveTranId,
                userMasterID,
                month,
                monday
              )
            );
          } else if (leave_type[j].LeaveID == 22) {
            user_leave.push(
              AddLeaveTypesInArray(
                leave_type[j].LeaveMaster.LeaveName,
                leave_type[j].LeaveMaster.LeaveDesc,
                leave_type[j].LeaveID,
                addPenalty ? penaltyMin : 0,
                leave_type[j].LeaveTranId,
                userMasterID,
                month,
                monday
              )
            );
          } else if (leave_type[j].LeaveID == 1) {
            const attendance = attendancedata;

            const weekoffHolidaydates = combinedboth.map((item) => item.date);

            const leavedates = leave
              .filter((item) => item.days == 1)
              .map((e) => e.date);

            const removedatesFromPresent = [
              ...weekoffHolidaydates,
              ...leavedates,
            ];

            // Filter array a based on the datesToRemove
            const presentArray = attendance.filter(
              (item) => !removedatesFromPresent.includes(item.AttendanceDate)
            );

            const present = presentArray.reduce((acc, obj) => {
              return acc + +obj.fulldayhalfday;
            }, 0);

            const present_day = +presentArray.length > 0 ? +present : 0;

            leave_data += +present_day;

            user_leave.push(
              AddLeaveTypesInArray(
                leave_type[j].LeaveMaster.LeaveName,
                leave_type[j].LeaveMaster.LeaveDesc,
                leave_type[j].LeaveID,
                +present_day,
                leave_type[j].LeaveTranId,
                userMasterID,
                month,
                monday
              )
            );
          } else if (leave_type[j].LeaveID == 7) {
            const weekoff_sum = finalWeekoffs.reduce(
              (acc, obj) => acc + +obj.value,
              0
            );

            leave_data += +weekoff_sum;
            weekoffholiday += +weekoff_sum;

            user_leave.push(
              AddLeaveTypesInArray(
                leave_type[j].LeaveMaster.LeaveName,
                leave_type[j].LeaveMaster.LeaveDesc,
                leave_type[j].LeaveID,
                +weekoff_sum,
                leave_type[j].LeaveTranId,
                userMasterID,
                month,
                monday
              )
            );
          } else if (leave_type[j].LeaveID == 9) {
            const holiday_sum = finalHolidays.reduce(
              (acc, obj) => acc + +obj.value,
              0
            );

            leave_data += +holiday_sum;
            weekoffholiday += +holiday_sum;

            user_leave.push(
              AddLeaveTypesInArray(
                leave_type[j].LeaveMaster.LeaveName,
                leave_type[j].LeaveMaster.LeaveDesc,
                leave_type[j].LeaveID,
                +holiday_sum,
                leave_type[j].LeaveTranId,
                userMasterID,
                month,
                monday
              )
            );
          } else if (leave_type[j].LeaveID == 28) {
            // Absent Due To Sandwich Leave

            const absent_Sandwhich = weekoffholidays
              .filter(
                (weekoff) =>
                  !leave.some((d) => d.date == weekoff.date) &&
                  ![...finalWeekoffs, ...finalHolidays].some(
                    (e) => e.date == weekoff.date
                  )
              )
              .reduce((sum, weekoff) => sum + +weekoff.value, 0);

            leave_data += +absent_Sandwhich;

            user_leave.push(
              AddLeaveTypesInArray(
                leave_type[j].LeaveMaster.LeaveName,
                leave_type[j].LeaveMaster.LeaveDesc,
                leave_type[j].LeaveID,
                +absent_Sandwhich,
                leave_type[j].LeaveTranId,
                userMasterID,
                month,
                monday
              )
            );
          } else if (leave_type[j].LeaveID == 29) {
            //Leave Behalf Of Sandwich Leave
            user_leave.push(
              AddLeaveTypesInArray(
                leave_type[j].LeaveMaster.LeaveName,
                leave_type[j].LeaveMaster.LeaveDesc,
                leave_type[j].LeaveID,
                weekoffholidays
                  .filter(
                    (weekoff) =>
                      leave.some((d) => d.date == weekoff.date) &&
                      ![...finalWeekoffs, ...finalHolidays].some(
                        (e) => e.date == weekoff.date
                      )
                  )
                  .reduce((sum, weekoff) => sum + +weekoff.value, 0),
                leave_type[j].LeaveTranId,
                userMasterID,
                month,
                monday
              )
            );
          } else if (leave_type[j].LeaveID == 30) {
            user_leave.push(
              AddLeaveTypesInArray(
                leave_type[j].LeaveMaster.LeaveName,
                leave_type[j].LeaveMaster.LeaveDesc,
                leave_type[j].LeaveID,
                actual_Weekoff.reduce((acc, obj) => acc + +obj.value, 0),
                leave_type[j].LeaveTranId,
                userMasterID,
                month,
                monday
              )
            );
          } else if (leave_type[j].LeaveID == 31) {
            user_leave.push(
              AddLeaveTypesInArray(
                leave_type[j].LeaveMaster.LeaveName,
                leave_type[j].LeaveMaster.LeaveDesc,
                leave_type[j].LeaveID,
                actual_holiday.reduce((acc, obj) => acc + +obj.value, 0),
                leave_type[j].LeaveTranId,
                userMasterID,
                month,
                monday
              )
            );
          } else if (leave_type[j].LeaveID == 32) {
            user_leave.push(
              AddLeaveTypesInArray(
                leave_type[j].LeaveMaster.LeaveName,
                leave_type[j].LeaveMaster.LeaveDesc,
                leave_type[j].LeaveID,
                0,
                leave_type[j].LeaveTranId,
                userMasterID,
                month,
                monday
              )
            );
          } else {
            //find userleave
            const leave_sum = leave
              .filter((e) => e.LeaveTranId == leave_type[j].LeaveTranId)
              .reduce((acc, obj) => acc + +obj.days, 0);

            leave_data += +leave_sum;
            user_leave.push(
              AddLeaveTypesInArray(
                leave_type[j].LeaveMaster.LeaveName,
                leave_type[j].LeaveMaster.LeaveDesc,
                leave_type[j].LeaveID,
                +leave_sum,
                leave_type[j].LeaveTranId,
                userMasterID,
                month,
                monday
              )
            );
          }
        }

        const absent_leave_type = Allleave_type.filter((e) => e.LeaveID == 5);

        //calculate absent

        let absent = +totalDays - +leave_data;

        //calculate workingdays
        let workingdays = +totalDays - +weekoffholiday;

        user_leave.push(
          AddLeaveTypesInArray(
            absent_leave_type[0].LeaveMaster.LeaveName,
            absent_leave_type[0].LeaveMaster.LeaveDesc,
            5,
            +absent,
            absent_leave_type[0].LeaveTranId,
            userMasterID,
            month,
            monday
          )
        );

        for (let m = 0; m < user_leave.length; m++) {
          user_leave[m].workingdays = workingdays;
        }

        const newJson = {
          userPhoto: userMasterData.photo || null,
          userMasterID: userMasterID,
          empcode: empjoining.employeeCode,
          firstName: userMasterData.firstName,
          lastName: userMasterData.lastName,
          userName: userMasterData.displayName,
          userNumber: userMasterData.userNumber,
          gender: userMasterData.gender,
          branch: branch ? branch.branchName : '',
          depart: department ? department.departmentName : '',
          desig: designation ? designation.designationName : '',
          yearMonth: month,
          month: yearmonth,
          MonDays: monday,
          TotalDays: totalDays,
          WorkingDays: workingdays,
          Workinghours: Math.round(+monthly_Workingminutes),
          start_date: start_date,
          end_date: end_date,
          user_leave: user_leave.sort((a, b) => a.leavetranid - b.leavetranid),
          SalaryDone: SalaryDone,
          calculateon: 'hourly',
          overtimeAdded: overtimeAdded,
          verified: 0,
          salaryStructurevalue: true,
          earningside_salarystructure: [],
          deductionside_salarystructure: [],
          extraEarning_salarystructure: [],
          earningside_employeesalary: [],
          deductionside_employeesalary: [],
          extraEarning_employeesalary: [],
          gross_salarystructure: null,
          netPay_salarystructure: null,
          gross_employeesalary: null,
          netPay_employeesalary: null,
          salarySlip: false,
          unRelease: false,
          verifiedBy: '',
          branchid: branch ? +branch.branchMasterID : null,
          departid: department ? +department.departmentId : null,
          desigid: designation ? +designation.designationId : null,
          salaryCalculateBy: '',
          penaltyArray: finalpenaltyArray,
          left,
          notJoin,
          FNF,
          coff: '',
          coffValue,
          paidSalary,
        };

        finaldata1.push(newJson);
      } else {
        let final_penaltydays = +penaltyDays;

        // push LECEG penalty

        if (+penaltyMin > 0)
          finalpenaltyArray.push(
            PenaltyAddInArray('Attendance Penalty(Min)', 'min', penaltyMin)
          );
        if (+penaltyAmount > 0)
          finalpenaltyArray.push(
            PenaltyAddInArray(
              'Attendance Penalty(Amt)',
              'amount',
              penaltyAmount
            )
          );
        if (+penaltyPercent > 0)
          finalpenaltyArray.push(
            PenaltyAddInArray(
              'Attendance Penalty(Per)',
              'percent',
              penaltyPercent
            )
          );

        if (
          LCEGPolicy?.lateEarlyPolicyType != 'noLcEgPolicy' &&
          LCEGPolicy?.deductFrom == PenaltyDeductFromEnum.SALARY &&
          +penaltyDays > 0
        ) {
          finalpenaltyArray.push(
            PenaltyAddInArray('Attendance Penalty(Days)', 'day', penaltyDays)
          );
          final_penaltydays = 0;
        }

        const leave_type = Allleave_type.filter(
          (e) => e.LeaveID != 5 && e.LeaveID != 20 && e.LeaveID != 21
        );

        let user_leave = [];
        let leave_data = 0;
        let weekoffholiday = 0;
        let presentDay = 0;

        for (let j = 0; j < leave_type.length; j++) {
          if (leave_type[j].LeaveID == 22) {
            leave_data += +final_penaltydays;
            user_leave.push(
              AddLeaveTypesInArray(
                leave_type[j].LeaveMaster.LeaveName,
                leave_type[j].LeaveMaster.LeaveDesc,
                leave_type[j].LeaveID,
                +final_penaltydays,
                leave_type[j].LeaveTranId,
                userMasterID,
                month,
                monday
              )
            );
          } else if (leave_type[j].LeaveID == 1) {
            if (empjoining.fullMonthPresence == 1) {
              user_leave.push(
                AddLeaveTypesInArray(
                  leave_type[j].LeaveMaster.LeaveName,
                  leave_type[j].LeaveMaster.LeaveDesc,
                  leave_type[j].LeaveID,
                  0,
                  leave_type[j].LeaveTranId,
                  userMasterID,
                  month,
                  monday
                )
              );
              continue;
            }

            const attendance = attendancedata;

            let presentArray = [],
              present = 0;

            // condition for Asopalav
            if (
              companyMasterID == 277 ||
              companyMasterID == 298 ||
              companyMasterID == 300
            ) {
              presentArray = attendance.filter(
                (item) =>
                  ![...actual_holiday]
                    .map((item) => item.date)
                    .includes(item.AttendanceDate)
              );

              present = presentArray.reduce((acc, obj) => {
                return acc + +obj.fulldayhalfday;
              }, 0);
            } else {
              const leavedates = leave
                .filter((item) => item.days == 1)
                .map((e) => e.date);

              // Filter array based on the datesToRemove
              presentArray = attendance.filter(
                (item) => !leavedates.includes(item.AttendanceDate)
              );

              present = presentArray.reduce((acc, obj) => {
                const WH = combinedboth.find(
                  (e) => e.date == obj.AttendanceDate
                );
                if (!WH) {
                  acc += +obj.fulldayhalfday;
                } else if (WH.value == 0.5) {
                  acc += +obj.fulldayhalfday > 0.5 ? 0.5 : +obj.fulldayhalfday;
                }
                return acc;
              }, 0);
            }

            const present_day =
              +presentArray.length > 0 ? +present - +final_penaltydays : 0;

            presentDay = +present_day;

            leave_data += +presentDay;

            user_leave.push(
              AddLeaveTypesInArray(
                leave_type[j].LeaveMaster.LeaveName,
                leave_type[j].LeaveMaster.LeaveDesc,
                leave_type[j].LeaveID,
                +presentDay,
                leave_type[j].LeaveTranId,
                userMasterID,
                month,
                monday
              )
            );
          } else if (leave_type[j].LeaveID == 7) {
            // condition for Asopalav
            let weekoff_sum = 0;
            if (
              companyMasterID == 277 ||
              companyMasterID == 298 ||
              companyMasterID == 300
            ) {
              weekoff_sum = +sundays;
            } else {
              weekoff_sum = finalWeekoffs.reduce(
                (acc, obj) => acc + +obj.value,
                0
              );
            }

            leave_data += +weekoff_sum;
            weekoffholiday += +weekoff_sum;

            user_leave.push(
              AddLeaveTypesInArray(
                leave_type[j].LeaveMaster.LeaveName,
                leave_type[j].LeaveMaster.LeaveDesc,
                leave_type[j].LeaveID,
                empjoining.fullMonthPresence == 1
                  ? actual_Weekoff.reduce((acc, obj) => acc + +obj.value, 0)
                  : +weekoff_sum,
                leave_type[j].LeaveTranId,
                userMasterID,
                month,
                monday
              )
            );
          } else if (leave_type[j].LeaveID == 9) {
            const holiday_sum = finalHolidays.reduce(
              (acc, obj) => acc + +obj.value,
              0
            );

            leave_data += +holiday_sum;
            weekoffholiday += +holiday_sum;

            user_leave.push(
              AddLeaveTypesInArray(
                leave_type[j].LeaveMaster.LeaveName,
                leave_type[j].LeaveMaster.LeaveDesc,
                leave_type[j].LeaveID,
                empjoining.fullMonthPresence == 1
                  ? actual_holiday.reduce((acc, obj) => acc + +obj.value, 0)
                  : Number(holiday_sum),
                leave_type[j].LeaveTranId,
                userMasterID,
                month,
                monday
              )
            );
          } else if (leave_type[j].LeaveID == 28) {
            // Absent Due To Sandwich Leave

            const absent_Sandwhich =
              empjoining.fullMonthPresence == 1
                ? 0
                : weekoffholidays
                    .filter(
                      (weekoff) =>
                        !leave.some((d) => d.date === weekoff.date) &&
                        ![...final_Weekoffs, ...finalHolidays].some(
                          (e) => e.date === weekoff.date
                        )
                    )
                    .reduce((sum, weekoff) => sum + +weekoff.value, 0);

            leave_data += +absent_Sandwhich;

            user_leave.push(
              AddLeaveTypesInArray(
                leave_type[j].LeaveMaster.LeaveName,
                leave_type[j].LeaveMaster.LeaveDesc,
                leave_type[j].LeaveID,
                +absent_Sandwhich,
                leave_type[j].LeaveTranId,
                userMasterID,
                month,
                monday
              )
            );
          } else if (leave_type[j].LeaveID == 29) {
            //Leave Behalf Of Sandwich Leave

            user_leave.push(
              AddLeaveTypesInArray(
                leave_type[j].LeaveMaster.LeaveName,
                leave_type[j].LeaveMaster.LeaveDesc,
                leave_type[j].LeaveID,
                empjoining.fullMonthPresence == 1
                  ? 0
                  : weekoffholidays
                      .filter(
                        (weekoff) =>
                          leave.some((d) => d.date === weekoff.date) &&
                          ![...finalWeekoffs, ...finalHolidays].some(
                            (e) => e.date === weekoff.date
                          )
                      )
                      .reduce((sum, weekoff) => sum + +weekoff.value, 0),
                leave_type[j].LeaveTranId,
                userMasterID,
                month,
                monday
              )
            );
          } else if (leave_type[j].LeaveID == 30) {
            user_leave.push(
              AddLeaveTypesInArray(
                leave_type[j].LeaveMaster.LeaveName,
                leave_type[j].LeaveMaster.LeaveDesc,
                leave_type[j].LeaveID,
                actual_Weekoff.reduce((acc, obj) => acc + +obj.value, 0),
                leave_type[j].LeaveTranId,
                userMasterID,
                month,
                monday
              )
            );
          } else if (leave_type[j].LeaveID == 31) {
            user_leave.push(
              AddLeaveTypesInArray(
                leave_type[j].LeaveMaster.LeaveName,
                leave_type[j].LeaveMaster.LeaveDesc,
                leave_type[j].LeaveID,
                actual_holiday.reduce((acc, obj) => acc + +obj.value, 0),
                leave_type[j].LeaveTranId,
                userMasterID,
                month,
                monday
              )
            );
          } else if (leave_type[j].LeaveID == 32) {
            user_leave.push(
              AddLeaveTypesInArray(
                leave_type[j].LeaveMaster.LeaveName,
                leave_type[j].LeaveMaster.LeaveDesc,
                leave_type[j].LeaveID,
                0,
                leave_type[j].LeaveTranId,
                userMasterID,
                month,
                monday
              )
            );
          } else {
            // condition for Asopalav
            let leave_sum = 0;
            if (
              companyMasterID != 277 &&
              companyMasterID != 298 &&
              companyMasterID != 300
            ) {
              leave_sum = leave
                .filter((e) => e.LeaveTranId == leave_type[j].LeaveTranId)
                .reduce((acc, obj) => acc + +obj.days, 0);
            }

            //find userleave

            leave_data += +leave_sum;

            user_leave.push(
              AddLeaveTypesInArray(
                leave_type[j].LeaveMaster.LeaveName,
                leave_type[j].LeaveMaster.LeaveDesc,
                leave_type[j].LeaveID,
                +leave_sum,
                leave_type[j].LeaveTranId,
                userMasterID,
                month,
                monday
              )
            );
          }
        }
        // For full Month Present
        if (empjoining.fullMonthPresence == 1) {
          const sum = user_leave
            .filter(
              (e) => e.leaveID != 29 && e.leaveID != 30 && e.leaveID != 31
            )
            .reduce((acc, obj) => acc + +obj.values, 0);
          user_leave.map((e) => {
            if (e.leaveID == 1)
              e.values = +totalDays - +sum > 0 ? +totalDays - +sum : 0;
            return e;
          });
        }

        const absent_leave_type = Allleave_type.filter((e) => e.LeaveID == 5);

        //calculate absent
        let absent = +totalDays - +leave_data;
        // condition for Asopalav
        if (
          companyMasterID == 277 ||
          companyMasterID == 298 ||
          companyMasterID == 300
        ) {
          if (+leave_data > +totalDays) {
            absent = 0;

            const data = +leave_data - +totalDays;

            user_leave.map((e) => {
              if (e.leaveID == 1) {
                e.values -= +data;
              }
            });
          }
        }

        // ---------------------------- set Weekoff Policy Wise -------------------------------

        // if Policy on Paid Days
        if (
          [weekoffTypeEnum.ONPRESENTDAY, weekoffTypeEnum.MONTHLYFIX].includes(
            weekoffPolicyType
          )
        ) {
          // if weekoff Policy is On Paid Days
          if (weekoffPolicyType == weekoffTypeEnum.ONPRESENTDAY) {
            const paidDays = user_leave
              .filter(
                (e) => ![5, 7, 18, 22, 28, 29, 30, 31, 32].includes(e.leaveID)
              )
              .reduce((acc, obj) => acc + +obj.values, 0);

            weekoffCount = Math.floor(+paidDays / +weekoffPolicy.presentDays);
            // if paidDays is greater than Total Days
            if (+paidDays > +totalDays) weekoffCount = 0;
          }

          // set weekoff

          for (let l = 0; l < user_leave.length; l++) {
            if ([7, 30].includes(+user_leave[l].leaveID)) {
              user_leave[l].values = +weekoffCount;
            }
          }

          const getTotalDays = user_leave
            .filter((e) => ![29, 30, 31, 32].includes(e.leaveID))
            .reduce((acc, obj) => acc + +obj.values, 0);

          const remainingDays = +totalDays - +getTotalDays;

          if (+remainingDays < 0) {
            absent = 0;
            // set Present Days
            for (let l = 0; l < user_leave.length; l++) {
              if (+user_leave[l].leaveID == 1) {
                user_leave[l].values =
                  user_leave[l].values + remainingDays > 0
                    ? user_leave[l].values + remainingDays
                    : 0;
                break;
              }
            }
            // set Extra Days or AddLeave value
            if (
              ['AddLeave', 'AddExtraDays'].includes(user_attendancePolicy?.coff)
            )
              coffValue =
                empjoining.fullMonthPresence == 1 ? 0 : Math.abs(remainingDays);
          } else {
            absent = remainingDays;
          }
        }

        const weekoffholidaydays = weekoffholidays.reduce(
          (acc, obj) => acc + +obj.value,
          0
        );

        //calculate workingdays
        let workingdays = +totalDays - +weekoffholidaydays - +weekoffCount;

        user_leave.push(
          AddLeaveTypesInArray(
            absent_leave_type[0].LeaveMaster.LeaveName,
            absent_leave_type[0].LeaveMaster.LeaveDesc,
            5,
            empjoining.fullMonthPresence == 1 ? 0 : +absent,
            absent_leave_type[0].LeaveTranId,
            userMasterID,
            month,
            monday
          )
        );

        for (let m = 0; m < user_leave.length; m++) {
          user_leave[m].workingdays = workingdays;
        }

        user_leave = user_leave.sort(function (a, b) {
          return Number(a.leavetranid) - Number(b.leavetranid);
        });

        const newJson = {
          userPhoto: userMasterData.photo || null,
          userMasterID: userMasterID,
          empcode: empjoining.employeeCode,
          firstName: userMasterData.firstName,
          lastName: userMasterData.lastName,
          userName: userMasterData.displayName,
          userNumber: userMasterData.userNumber,
          gender: userMasterData.gender,
          branch: branch ? branch.branchName : '',
          depart: department ? department.departmentName : '',
          desig: designation ? designation.designationName : '',
          yearMonth: month,
          month: yearmonth,
          MonDays: monday,
          TotalDays: totalDays,
          WorkingDays: workingdays,
          start_date: start_date,
          end_date: end_date,
          user_leave: user_leave.sort((a, b) => a.leavetranid - b.leavetranid),
          SalaryDone: SalaryDone,
          calculateon: 'monthly',
          overtimeAdded: overtimeAdded,
          verified: 0,
          salaryStructurevalue: true,
          earningside_salarystructure: [],
          deductionside_salarystructure: [],
          extraEarning_salarystructure: [],
          earningside_employeesalary: [],
          deductionside_employeesalary: [],
          extraEarning_employeesalary: [],
          gross_salarystructure: null,
          netPay_salarystructure: null,
          gross_employeesalary: null,
          netPay_employeesalary: null,
          salarySlip: false,
          unRelease: false,
          verifiedBy: '',
          branchid: branch ? +branch.branchMasterID : null,
          departid: department ? +department.departmentId : null,
          desigid: designation ? +designation.designationId : null,
          salaryCalculateBy: '',
          penaltyArray: finalpenaltyArray,
          left,
          notJoin,
          FNF,
          coffValue,
          coff: user_attendancePolicy?.coff || '',
          weekoffValue,
          weekoffPolicyType,
          paidSalary,
        };

        finaldata1.push(newJson);
      }
    } else {
      // ----------find Coff -----

      const coffData = userMasterData.coffMasters?.[0] || null;

      let extraDaysData = null;
      // if not Coff found Then check Extra Days
      if (!coffData) {
        extraDaysData = await ExtraDays.findOne({
          where: {
            userMasterID,
            date: end_date,
            From: 'AC',
          },
        });
      }

      // -------------------- set LCEG Penalty-----

      const lcegPenalty = userMasterData.lcegPenalties || [];

      lcegPenalty.forEach((e) => {
        const leavename =
          e.penaltyType == LCEGPenaltyTypeEnum.DAY
            ? 'Days'
            : e.penaltyType == LCEGPenaltyTypeEnum.MINUTE
              ? 'Min'
              : e.penaltyType == LCEGPenaltyTypeEnum.AMOUNT
                ? 'Amt'
                : e.penaltyType == LCEGPenaltyTypeEnum.PERCENT
                  ? 'Per'
                  : '';
        finalpenaltyArray.push(
          PenaltyAddInArray(
            `Attendance Penalty (${leavename})`,
            e.penaltyType,
            e.penaltyValue
          )
        );
      });

      // set leave types
      const user_leave = leavedata2.map((e) => {
        return AddLeaveTypesInArray(
          e.hrLeaveType.LeaveMaster.LeaveName,
          e.hrLeaveType.LeaveMaster.LeaveDesc,
          e.hrLeaveType.LeaveID,
          +e.AttnVal,
          e.LeaveTranId,
          userMasterID,
          month,
          monday
        );
      });

      const find_hourly = user_leave.filter((e) => {
        return e.leaveID == 20;
      });

      let calculateon;
      let paidDays = 0;

      if (find_hourly.length > 0) {
        calculateon = 'hourly';
      } else {
        calculateon = 'monthly';

        let notIncludeIds = [];

        if (empjoining.salaryCalculationAct == 'F') {
          notIncludeIds = [5, 7, 18, 20, 21, 22, 28, 29, 30, 31, 32];
        } else if (empjoining.salaryCalculationAct == 'W') {
          notIncludeIds = [5, 7, 9, 18, 20, 21, 22, 28, 29, 30, 31, 32];
        } else {
          notIncludeIds = [5, 18, 20, 21, 22, 28, 29, 30, 31, 32];
        }

        paidDays = user_leave
          .filter((e) => ![...notIncludeIds].includes(+e.leaveID))
          .reduce((acc, obj) => acc + +obj.values, 0);
      }

      let salaryStructure = [];
      let employeeSalary = [];
      let salarySlip = false;
      let unRelease = false;
      let salaryStructurevalue = false;

      // find salary structure

      const salarystructure = await getUserSalaryMasterByMonth(
        userMasterID,
        month
      );

      let salaryCalculatedBy = '';
      if (salarystructure.length > 0) {
        salaryStructurevalue = true;

        if (+find_usersalary.length > 0) {
          salaryCalculatedBy = find_usersalary[0].createByUserName || '';

          const showfinalalsalary = find_usersalary.filter((e) => {
            if (e.salaryFieldSrNo != 'C') {
              if (e.salaryFieldSide == 'D') {
                if (+e.EmployeeSalaryAmount > 0) return e;
              } else {
                return e;
              }
            }
          });

          // salary structure

          const finalsalaryStructure = salarystructure.filter(
            (e) => e.salaryFieldSrNo != 'C' && e.salaryFieldShow == 'Y'
          );

          const salarySlipData = userMasterData.hrSalarySlips?.[0] || null;

          // paid salary
          paidSalary = salarySlipData?.paid || false;

          const salaryslip = salarySlipData?.salarySlipIssue == 1 || false;

          salaryStructure = finalsalaryStructure;
          employeeSalary = showfinalalsalary;
          salarySlip = salaryslip ? false : true;
          unRelease = salaryslip ? true : false;
        }
      }

      const verifyBy = await UserMaster.findOne({
        raw: true,
        where: {
          userMasterID: +leavedata2[0].updateBy,
        },
        attributes: ['displayName'],
      });

      // salary slip

      const newJson = {
        userPhoto: userMasterData.photo || null,
        userMasterID: userMasterID,
        empcode: empjoining.employeeCode,
        firstName: userMasterData.firstName,
        lastName: userMasterData.lastName,
        userName: userMasterData.displayName,
        userNumber: userMasterData.userNumber,
        gender: userMasterData.gender,
        branch: branch ? branch.branchName : '',
        depart: department ? department.departmentName : '',
        desig: designation ? designation.designationName : '',
        Workinghours: monthly_Workingminutes,
        yearMonth: month,
        month: yearmonth,
        MonDays: monday,
        TotalDays: totalDays,
        WorkingDays: leavedata2[0].MonWorkDays,
        start_date: start_date,
        end_date: end_date,
        user_leave: user_leave.sort((a, b) => a.leavetranid - b.leavetranid),
        SalaryDone: SalaryDone,
        verified: 1,
        calculateon: calculateon,
        overtimeAdded: overtimeAdded,
        paidDays: paidDays,
        salaryStructurevalue: salaryStructurevalue,
        earningside_salarystructure: salaryStructure.filter(
          (e) =>
            e.salaryFieldSide == 'E' &&
            e.salaryFieldShow == 'Y' &&
            e.considerIn != 'net' &&
            ![1, 50, 92].includes(e.payheadMasterId)
        ),
        deductionside_salarystructure: salaryStructure.filter(
          (e) =>
            e.salaryFieldSide == 'D' && ![1, 50, 92].includes(e.payheadMasterId)
        ),
        extraEarning_salarystructure: salaryStructure.filter(
          (e) =>
            e.salaryFieldSide == 'E' &&
            e.salaryFieldShow == 'Y' &&
            e.considerIn == 'net' &&
            ![1, 50, 92].includes(e.payheadMasterId)
        ),
        earningside_employeesalary: employeeSalary.filter(
          (e) =>
            e.salaryFieldSide == 'E' &&
            e.considerIn != 'net' &&
            ![1, 50, 92].includes(e.payheadMasterId)
        ),
        deductionside_employeesalary: employeeSalary.filter(
          (e) =>
            e.salaryFieldSide == 'D' && ![1, 50, 92].includes(e.payheadMasterId)
        ),
        extraEarning_employeesalary: employeeSalary.filter(
          (e) =>
            e.salaryFieldSide == 'E' &&
            e.considerIn == 'net' &&
            ![1, 50, 92].includes(e.payheadMasterId)
        ),
        gross_salarystructure: salarystructure.find(
          (e) => e.payheadMasterId == 50
        ),
        netPay_salarystructure: salarystructure.find(
          (e) => e.payheadMasterId == 92
        ),
        gross_employeesalary: employeeSalary.find(
          (e) => e.payheadMasterId == 50
        ),
        netPay_employeesalary: employeeSalary.find(
          (e) => e.payheadMasterId == 92
        ),
        salarySlip: salarySlip,
        unRelease: unRelease,
        verifiedBy: verifyBy ? verifyBy.displayName : '',
        branchid: branch ? +branch.branchMasterID : null,
        departid: department ? +department.departmentId : null,
        desigid: designation ? +designation.designationId : null,
        salaryCalculateBy: salaryCalculatedBy,
        penaltyArray: finalpenaltyArray,
        left,
        notJoin,
        FNF,
        coff: coffData ? 'AddLeave' : extraDaysData ? 'AddExtraDays' : '',
        coffValue: coffData
          ? +coffData.LeaveAddNew
          : extraDaysData
            ? +extraDaysData.days
            : 0,
        paidSalary,
      };

      finaldata1.push(newJson);
    }
  } else {
    const newJson = {
      userPhoto: userMasterData.photo || null,
      userMasterID: userMasterID,
      firstName: userMasterData.firstName,
      lastName: userMasterData.lastName,
      userName: userMasterData.displayName,
      userNumber: userMasterData.userNumber,
      branch: '',
      depart: '',
      desig: '',
      Workinghours: 0,
      yearMonth: month,
      month: yearmonth,
      MonDays: monday,
      start_date: start_date,
      end_date: end_date,
      user_leave: '',
      attendance: [],
      salaryStructurevalue: true,
      earningside_salarystructure: [],
      deductionside_salarystructure: [],
      extraEarning_salarystructure: [],
      earningside_employeesalary: [],
      deductionside_employeesalary: [],
      extraEarning_employeesalary: [],
      gross_salarystructure: null,
      netPay_salarystructure: null,
      gross_employeesalary: null,
      netPay_employeesalary: null,
      salarySlip: false,
      unRelease: false,
      verifiedBy: '',
      branch: '',
      depart: '',
      desig: '',
      salaryCalculateBy: '',
      penaltyArray: [],
      left,
      notJoin,
      FNF,
      coff: '',
      coffValue,
      paidSalary,
    };

    finaldata1.push(newJson);
  }

  return finaldata1;
}

function getDateRangeBySalaryPolicy(year, Month, salaryPolicy) {
  if (!year || !Month) return { start_date: '', end_date: '' };

  let monday = daysInMonth(Month, year);

  // ----------- set start date and end date according to salary policy -------
  let start_date = year + '-' + Month + '-' + '01';
  let end_date = year + '-' + Month + '-' + monday;

  if (salaryPolicy) {
    let date = salaryPolicy.salaryCycleDate;

    date = (date < 10 ? '0' : '') + date;

    start_date = year + '-' + Month + '-' + date;

    // To Check salary consider Month

    if (salaryPolicy.salaryCycleConsider == 'E') {
      const tempDate = new Date(start_date);
      tempDate.setMonth(tempDate.getMonth() - 1);

      start_date =
        tempDate.getFullYear() +
        '-' +
        String(tempDate.getMonth() + 1).padStart(2, '0') +
        '-' +
        String(tempDate.getDate()).padStart(2, '0');

      // set Month days
      monday = daysInMonth(start_date.slice(5, 7), start_date.slice(0, 4));
    }

    let date1 = new Date(start_date);
    date1.setDate(date1.getDate() + (monday - 1));

    end_date =
      date1.getFullYear() +
      '-' +
      String(date1.getMonth() + 1).padStart(2, '0') +
      '-' +
      String(date1.getDate()).padStart(2, '0');
  }

  return { start_date, end_date };
}

function getPreviousMonth(month) {
  let year = parseInt(String(month).substring(0, 4), 10);
  let currentMonth = parseInt(String(month).substring(4, 6), 10);

  // Decrease the month, adjust the year if necessary
  currentMonth -= 1;
  if (currentMonth === 0) {
    currentMonth = 12;
    year -= 1;
  }

  // Format the result as YYYYMM
  return `${year}${currentMonth.toString().padStart(2, '0')}`;
}

function isValidValue(num) {
  return num >= 0 && num <= 30 && num % 0.5 === 0;
}

function findNearestNumbers(arr, target) {
  let past = null;
  let future = null;

  // Sort the array to make sure we're checking in ascending order
  arr.sort((a, b) => a - b);

  for (let i = 0; i < arr.length; i++) {
    if (arr[i] < target) {
      past = arr[i]; // Record the past number
    }
    if (arr[i] > target && future === null) {
      future = arr[i]; // Record the first future number
    }
  }

  return { past, future };
}
function getPreviousDateString(dateStr) {
  const date = new Date(dateStr);
  date.setDate(date.getDate() - 1); // subtract 1 day

  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0'); // zero-padded
  const day = String(date.getDate()).padStart(2, '0'); // zero-padded

  return `${year}-${month}-${day}`;
}

function paginateArray(data, page, limit) {
  const startIndex = (page - 1) * limit;
  const endIndex = startIndex + limit;
  return data.slice(startIndex, endIndex);
}

