function getDateRangesByType(type, year) {
  const result = [];

  if (
    ![PayrollFrequencyType.FORTNIGHTLY, PayrollFrequencyType.WEEKLY].includes(
      type
    )
  )
    return result;

  const jan1 = new Date(`${year}-01-01`);
  const dec31 = new Date(`${year}-12-31`);

  // Go to the Monday on or before Jan 1
  const start = new Date(jan1);
  const day = start.getDay(); // 0 = Sun, 1 = Mon, ..., 6 = Sat
  const diffToMonday = day === 0 ? -6 : 1 - day;
  start.setDate(start.getDate() + diffToMonday);

  let currentStart = new Date(start);
  let counter = 1;
  const intervalDays = type === PayrollFrequencyType.WEEKLY ? 6 : 13;

  while (true) {
    const from = new Date(currentStart);
    const to = new Date(currentStart);
    to.setDate(to.getDate() + intervalDays);

    // Skip ranges that end before Jan 1
    if (to < jan1) {
      currentStart.setDate(currentStart.getDate() + intervalDays + 1);
      continue;
    }

    // Stop once the start date is beyond Dec 31
    if (from > dec31) break;

    result.push({
      title: `${type === PayrollFrequencyType.WEEKLY ? 'W' : 'F'}${counter}`,
      from: from.toISOString().slice(0, 10),
      to: to.toISOString().slice(0, 10),
    });

    currentStart.setDate(currentStart.getDate() + intervalDays + 1);
    counter++;
  }

  return result;
}

function signData(dataObj) {
  const json = JSON.stringify(dataObj);
  const encoded = Buffer.from(json).toString('base64');

  const signature = crypto
    .createHmac('sha256', cryptokey)
    .update(encoded)
    .digest('hex');

  return `${encoded}.${signature}`;
}

function verifyData(signed) {
  const [encoded, signature] = signed.split('.');
  const expectedSig = crypto
    .createHmac('sha256', cryptokey)
    .update(encoded)
    .digest('hex');

  if (expectedSig !== signature) throw new Error('Invalid or tampered data');

  const json = Buffer.from(encoded, 'base64').toString('utf-8');
  return JSON.parse(json);
}

function encodeSecureBreak(data) {
  const json = JSON.stringify(data);
  const base64 = Buffer.from(json).toString('base64');
  const marker = Buffer.from(secretTokenForEnc).toString('hex');
  const pos = Math.floor(base64.length / 2);
  const broken = base64.slice(0, pos) + marker + base64.slice(pos);
  return broken;
}

function decodeSecureFix(brokenBase64) {
  const marker = Buffer.from(secretTokenForEnc).toString('hex');
  if (!brokenBase64.includes(marker)) {
    throw new Error('Invalid or tampered string.');
  }
  const repaired = brokenBase64.replace(marker, '');
  const json = Buffer.from(repaired, 'base64').toString('utf8');
  return JSON.parse(json);
}

function getDaysFromDates(startDate, endDate) {
  let totalDays = 0;

  if (new Date(startDate) > new Date(endDate)) return totalDays;

  const totalDaysData = Math.abs(
    (new Date(endDate).getTime() - new Date(startDate).getTime()) /
      (1000 * 60 * 60 * 24)
  ); // it returns negative value if start date < end date
  totalDays = Math.floor(totalDaysData + 1); // to get complete

  return totalDays;
}

