function sendNotification_NEW(
  firebaseToken,
  deviceType,
  notification,
  notificationBody
) {
  if (firebaseToken != null && firebaseToken != '') {
    const firebase_token = firebaseToken;

    // Common message structure
    const message_notification = {
      token: firebase_token, // Set the registration token here
      notification: notification,
      data: notificationBody, // Custom data payload
    };

    // Conditionally add platform-specific options
    if (deviceType && deviceType.toLowerCase() === 'ios') {
      // iOS-specific options
      message_notification.apns = {
        payload: {
          aps: {
            alert: {
              title: notification.title,
              body: notification.body,
            },
            sound: 'default', // Enable sound for iOS notifications
            badge: 1, // Badge count for iOS
          },
        },
        headers: {
          'apns-priority': '10', // High priority for iOS
          'apns-expiration': (
            Math.floor(Date.now() / 1000) +
            60 * 60 * 24
          ).toString(), // Expiration for 24 hours as a string
        },
      };
    } else {
      // Android-specific options
      message_notification.android = {
        priority: 'high', // High priority for Android
        ttl: 60 * 60 * 24 * 1000, // 24 hours in milliseconds for TTL
      };
    }

    // Send notification through the appropriate admin (iosFirebaseAdmin or androidFirebaseAdmin)
    const Notification_ =
      deviceType && deviceType.toLowerCase() === 'ios'
        ? iosFirebaseAdmin
        : androidFirebaseAdmin;

    Notification_.messaging()
      .send(message_notification)
      .then((response) => {})
      .catch((error) => {
        console.log('Error sending notification:', error);
      });
  }
}

// ---- get previous month to next month
function getStartAndEndDate(month) {
  // Extract year and month
  const year = Math.floor(month / 100); // Extract year (e.g., 2024)
  const currentMonth = month % 100; // Extract month (e.g., 02 for February)

  // Calculate Previous Month's Start Date (YYYY-MM-01)
  const prevMonthDate = new Date(year, currentMonth - 2, 2); // Go back one month
  const startDate = prevMonthDate.toISOString().split('T')[0]; // Format YYYY-MM-DD

  // Calculate Next Month's End Date (Last day of next month)
  const nextMonthDate = new Date(year, currentMonth, 1); // Move to next month
  nextMonthDate.setMonth(nextMonthDate.getMonth() + 1); // Move to the month after next
  nextMonthDate.setDate(1); // Set to last day of the month
  const endDate = nextMonthDate.toISOString().split('T')[0]; // Format YYYY-MM-DD

  return { startDate, endDate };
}

function getNextMonth(month) {
  // Extract year and month
  const year = Math.floor(month / 100); // Extract year (e.g., 2024)
  const currentMonth = month % 100; // Extract month (e.g., 02 for February)

  // Calculate Next Month's End Date (Last day of next month)
  const nextMonthDate = new Date(year, currentMonth, 1); // Move to next month
  nextMonthDate.setMonth(nextMonthDate.getMonth() + 1); // Move to the month after next
  nextMonthDate.setDate(1); // Set to last day of the month
  const endDate = nextMonthDate.toISOString().split('T')[0]; // Format YYYY-MM-DD

  return endDate;
}

// Helper to split array into chunks
function chunkArray(array, chunkSize) {
  const results = [];
  for (let i = 0; i < array.length; i += chunkSize) {
    results.push(array.slice(i, i + chunkSize));
  }
  return results;
}

